import React, { useCallback, useEffect, useState } from "react";
import { FiChevronLeft, FiChevronRight, FiRefreshCw } from "react-icons/fi";
import { api } from "./api";
import { AdminErrorState, Badge, Button, EmptyState, Label, Panel, Spinner, TextInput, cx, toast } from "./ui";

function resultTone(result) {
  if (!result) return "neutral";
  if (result === "ok") return "ok";
  return "bad";
}

function toIso(value) {
  if (!value) return "";
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? "" : parsed.toISOString();
}

/* Newest-first view of the admin audit log. Retention is TTL-only — there is
   no delete endpoint. */
export default function AuditPage() {
  const [data, setData] = useState(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [actor, setActor] = useState("");
  const [action, setAction] = useState("");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [page, setPage] = useState(1);
  const [pageSize] = useState(50);

  const load = useCallback(async () => {
    setBusy(true);
    try {
      const d = await api.get("/admin/api/audit", {
        actor,
        action,
        date_from: toIso(dateFrom),
        date_to: toIso(dateTo),
        page,
        page_size: pageSize,
      });
      setData(d);
      setError("");
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  }, [actor, action, dateFrom, dateTo, page, pageSize]);

  useEffect(() => {
    load();
  }, [load]);

  const applyFilters = () => {
    // ``load`` closes over the current page. Going back to page 1 must wait
    // for the state change, otherwise the request still uses the old page.
    if (page === 1) load();
    else setPage(1);
  };

  const clearFilters = () => {
    setActor("");
    setAction("");
    setDateFrom("");
    setDateTo("");
    setPage(1);
  };

  if (error && !data)
    return (
      <Panel>
        <AdminErrorState title="Audit log unavailable" error={error} />
      </Panel>
    );
  if (!data)
    return (
      <div className="flex justify-center py-24">
        <Spinner className="w-6 h-6" />
      </div>
    );

  const items = data.items || [];
  const total = data.total_count || 0;
  const pages = Math.max(1, Math.ceil(total / pageSize));

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-end gap-3">
        <div className="mr-auto">
          <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Oversight</p>
          <h1 className="font-display text-3xl mt-1.5">Audit log</h1>
          <p className="text-sm text-bone/60 mt-1">
            {total.toLocaleString()} entries · newest first · retained 90 days
          </p>
        </div>
        <Button variant="ghost" onClick={load} disabled={busy}>
          <FiRefreshCw size={14} /> Refresh
        </Button>
      </header>

      <Panel title="Filters" subtitle="Actor/action match is a case-insensitive substring; dates are inclusive">
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-[1fr_1fr_1fr_1fr_auto_auto] items-end">
          <div>
            <Label htmlFor="audit-actor">Actor</Label>
            <TextInput
              id="audit-actor"
              value={actor}
              placeholder="admin"
              onChange={(e) => setActor(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && applyFilters()}
            />
          </div>
          <div>
            <Label htmlFor="audit-action">Action</Label>
            <TextInput
              id="audit-action"
              value={action}
              placeholder="media.delete"
              onChange={(e) => setAction(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && applyFilters()}
            />
          </div>
          <div>
            <Label htmlFor="audit-from">From</Label>
            <TextInput
              id="audit-from"
              type="datetime-local"
              value={dateFrom}
              className="[color-scheme:dark]"
              onChange={(e) => setDateFrom(e.target.value)}
            />
          </div>
          <div>
            <Label htmlFor="audit-to">To</Label>
            <TextInput
              id="audit-to"
              type="datetime-local"
              value={dateTo}
              className="[color-scheme:dark]"
              onChange={(e) => setDateTo(e.target.value)}
            />
          </div>
          <Button variant="primary" onClick={applyFilters} disabled={busy}>
            Apply
          </Button>
          <Button variant="ghost" onClick={clearFilters} disabled={busy}>
            Clear
          </Button>
        </div>
      </Panel>

      <Panel title="Entries" subtitle="Every admin mutation, from the panel and from Telegram">
        {items.length === 0 ? (
          <EmptyState title="No audit entries match">
            Mutations appear here as soon as they happen.
          </EmptyState>
        ) : (
          <ul className="space-y-2">
            {items.map((row) => (
              <li
                key={row.id}
                className="rounded-md border border-bone/8 bg-ink/40 px-4 py-3"
              >
                <div className="flex flex-wrap items-center gap-2">
                  <span className="text-sm font-medium text-bone">{row.action}</span>
                  <Badge tone={row.actor_kind === "telegram" ? "warn" : "neutral"}>
                    {row.actor_kind}
                  </Badge>
                  <Badge tone={resultTone(row.result)}>
                    {row.result === "ok" ? "ok" : "error"}
                  </Badge>
                  <span className="timecode text-[10px] text-bone/50 ml-auto tabular-nums">
                    {row.ts ? new Date(row.ts).toLocaleString() : "—"}
                  </span>
                </div>
                <p className="timecode text-[11px] text-bone/50 mt-1">
                  {row.actor} → {row.target || "—"}
                  {row.ip ? ` · ${row.ip}` : ""}
                </p>
                {row.detail ? (
                  <p className="text-[12px] text-bone/55 mt-1.5 break-words whitespace-pre-wrap">
                    {row.detail}
                  </p>
                ) : null}
              </li>
            ))}
          </ul>
        )}

        <div className="mt-4 pt-4 border-t border-bone/6 flex items-center justify-between">
          <p className="timecode text-[10px] text-bone/60">
            page {data.page} of {pages}
          </p>
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              disabled={busy || data.page <= 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              <FiChevronLeft size={14} /> Newer
            </Button>
            <Button
              variant="ghost"
              disabled={busy || data.page >= pages}
              onClick={() => setPage((p) => p + 1)}
            >
              Older <FiChevronRight size={14} />
            </Button>
          </div>
        </div>
      </Panel>
    </div>
  );
}

import React, { useEffect, useState } from "react";
import { FiRefreshCw, FiTrash2 } from "react-icons/fi";
import { api } from "./api";
import { AdminErrorState, Badge, Button, EmptyState, Panel, Spinner, formatEta, toast } from "./ui";

function Bar({ used, max }) {
  const pct = Math.min(100, max ? (used / max) * 100 : 0);
  return (
    <div className="h-1.5 rounded-full bg-bone/8 overflow-hidden">
      <div
        className={
          pct > 85
            ? "h-full rounded-full bg-signal transition-all"
            : "h-full rounded-full bg-projector/80 transition-all"
        }
        style={{ width: `${Math.max(2, pct)}%` }}
      />
    </div>
  );
}

export default function CachePage() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");

  const load = async () => {
    setLoading(true);
    try {
      setData(await api.get("/admin/api/cache"));
      setError("");
    } catch (e) {
      setError(e.message);
      toast(e.message, "error");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const clear = async (target) => {
    setBusy(target);
    try {
      await api.post("/admin/api/cache/clear", { target });
      toast(`${target === "all" ? "All" : target} cache cleared`);
      await load();
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setBusy("");
    }
  };

  if (loading)
    return (
      <div className="flex justify-center py-24">
        <Spinner className="w-6 h-6" />
      </div>
    );
  if (!data)
    return (
      <Panel>
        <AdminErrorState
          title="Cache report unavailable"
          error={error || "Try refreshing — the backend may still be warming up."}
        />
      </Panel>
    );

  const caches = data.caches || {};
  const overall = caches.overall_stats || {};
  const remux = data.remux || {};
  const redis = data.redis || {};
  const chunks = caches.video_chunks || {};

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-end gap-3">
        <div className="mr-auto">
          <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Performance</p>
          <h1 className="font-display text-3xl mt-1.5">Cache</h1>
          <p className="text-sm text-bone/60 mt-1">In-memory stores, remux files on disk and Redis health.</p>
        </div>
        <Button variant="ghost" onClick={load}>
          <FiRefreshCw size={14} /> Refresh
        </Button>
        <Button variant="danger" disabled={!!busy} onClick={() => clear("all")}>
          {busy === "all" ? <Spinner /> : <FiTrash2 size={14} />} Clear everything
        </Button>
      </header>

      <div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-3">
        {[
          ["Redis", redis.status || (redis.available ? "connected" : "disabled"), redis.status === "error" ? "bad" : "ok"],
          ["File metadata", `${caches.file_metadata?.size ?? 0} / ${caches.file_metadata?.maxsize ?? "?"}`, "neutral"],
          ["Hot movies", `${caches.hot_movies?.size ?? 0} / ${caches.hot_movies?.maxsize ?? "?"}`, "neutral"],
          ["Hits / misses", `${overall.hits ?? 0} / ${overall.misses ?? 0}`, "neutral"],
        ].map(([label, value, tone]) => (
          <div key={label} className="glass-card rounded-lg px-4 py-4">
            <p className="timecode text-[9px] uppercase tracking-[0.2em] text-bone/60">{label}</p>
            <p className="mt-1.5 font-display text-2xl leading-none tabular-nums text-bone">{value}</p>
            <span className="inline-block mt-2">
              {tone !== "neutral" && <Badge tone={tone}>{tone === "ok" ? "healthy" : "check"}</Badge>}
            </span>
          </div>
        ))}
      </div>

      <div className="grid lg:grid-cols-2 gap-5">
        <Panel
          title="Remux directory"
          subtitle="ffmpeg output cached on disk"
          actions={
            <Button variant="ghost" disabled={!!busy} onClick={() => clear("remux")}>
              {busy === "remux" ? <Spinner /> : <FiTrash2 size={14} />} Clear
            </Button>
          }
        >
          <dl className="space-y-3 text-sm">
            <div>
              <div className="flex items-baseline gap-3 mb-1.5">
                <dt className="timecode text-[10px] uppercase tracking-[0.14em] text-bone/60 mr-auto">Budget used</dt>
                <dd className="timecode text-bone/80">
                  {remux.mb ?? 0} / {remux.budget_mb ?? "?"} MB
                </dd>
              </div>
              <Bar used={remux.mb} max={remux.budget_mb} />
            </div>
            {[
              ["Cached files", remux.files],
              ["Partial writes", remux.partials],
              ["Entry TTL", remux.ttl_hours ? formatEta(remux.ttl_hours * 3600) : "—"],
            ].map(([k, v]) => (
              <div key={k} className="flex items-baseline gap-3">
                <dt className="timecode text-[10px] uppercase tracking-[0.14em] text-bone/60 mr-auto">{k}</dt>
                <dd className="timecode text-bone/80">{v ?? "—"}</dd>
              </div>
            ))}
          </dl>
        </Panel>

        <Panel
          title="Video chunk cache"
          subtitle="Byte-range chunks served to the player"
          actions={
            <Button variant="ghost" disabled={!!busy} onClick={() => clear("video")}>
              {busy === "video" ? <Spinner /> : <FiTrash2 size={14} />} Clear
            </Button>
          }
        >
          <dl className="grid grid-cols-2 gap-y-3 gap-x-4 text-sm">
            {Object.entries(chunks).length === 0 ? (
              <div className="col-span-2">
                <EmptyState title="No chunk stats reported" />
              </div>
            ) : (
              Object.entries(chunks).map(([k, v]) => (
                <React.Fragment key={k}>
                  <dt className="timecode text-[10px] uppercase tracking-[0.14em] text-bone/60">{k.replace(/_/g, " ")}</dt>
                  <dd className="timecode text-bone/80 text-right">
                    {typeof v === "object" ? JSON.stringify(v) : String(v)}
                  </dd>
                </React.Fragment>
              ))
            )}
          </dl>
        </Panel>
      </div>
    </div>
  );
}

import React, { useState } from "react";
import { FiCheck, FiRefreshCw, FiSave, FiZap } from "react-icons/fi";
import { api } from "./api";
import { useChannels } from "./channels";
import { Button, EmptyState, Field, Label, Panel, Select, Spinner, TextInput, toast } from "./ui";

export default function CommandsPage() {
  const { channels } = useChannels();
  const [defaultId, setDefaultId] = useState("");
  const [rescan, setRescan] = useState({ channel_index: 0, limit: 100 });
  const [merge, setMerge] = useState(null);
  const [busy, setBusy] = useState("");

  const run = async (key, fn, ok) => {
    setBusy(key);
    try {
      const res = await fn();
      if (ok) toast(ok);
      return res;
    } catch (e) {
      toast(e.message, "error");
      return null;
    } finally {
      setBusy("");
    }
  };

  return (
    <div className="space-y-5">
      <header>
        <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Operations</p>
        <h1 className="font-display text-3xl mt-1.5">Commands</h1>
        <p className="text-sm text-bone/60 mt-1">Bot-wide switches that take effect on the running backend.</p>
      </header>

      <div className="grid lg:grid-cols-2 gap-5">
        <Panel title="Default metadata ID" subtitle="Overrides TMDB lookups for every new upload">
          <div className="flex items-end gap-2">
            <div className="flex-1">
              <Label htmlFor="cmd-default">Default id</Label>
              <TextInput
                id="cmd-default"
                value={defaultId}
                onChange={(e) => setDefaultId(e.target.value)}
                placeholder="e.g. 12345 or blank to disable"
              />
            </div>
            <Button
              variant="primary"
              disabled={!!busy}
              onClick={() =>
                run("set", () => api.post("/admin/api/commands/set", { default_id: defaultId || null }), "Default id applied")
              }
            >
              {busy === "set" ? <Spinner /> : <FiSave size={14} />} Save
            </Button>
            <Button
              variant="ghost"
              disabled={!!busy}
              onClick={() => {
                setDefaultId("");
                run("clear", () => api.post("/admin/api/commands/set", { default_id: null }), "Default id cleared");
              }}
            >
              Disable
            </Button>
          </div>
          <p className="text-[11px] text-bone/55 mt-3">
            Applies to the live process only — a backend restart restores the configured value.
          </p>
        </Panel>

        <Panel title="Rescan a channel" subtitle="Finds files the bot missed, then queues them">
          <div className="flex items-end gap-2 flex-wrap">
            <div className="w-56">
              <Label htmlFor="cmd-channel">Channel</Label>
              {channels.length > 0 ? (
                <Select
                  id="cmd-channel"
                  value={String(rescan.channel_index)}
                  onChange={(e) =>
                    setRescan({ ...rescan, channel_index: Number(e.target.value) })
                  }
                >
                  {channels.map((c) => (
                    <option key={c.index} value={c.index}>
                      {c.label}
                    </option>
                  ))}
                </Select>
              ) : (
                <TextInput
                  id="cmd-channel"
                  type="number"
                  value={rescan.channel_index}
                  onChange={(e) =>
                    setRescan({ ...rescan, channel_index: Number(e.target.value) })
                  }
                />
              )}
            </div>
            <div className="w-28">
              <Label htmlFor="cmd-limit">Message limit</Label>
              <TextInput
                id="cmd-limit"
                type="number"
                value={rescan.limit}
                onChange={(e) => setRescan({ ...rescan, limit: Number(e.target.value) })}
              />
            </div>
            <Button
              variant="primary"
              className="ml-auto"
              disabled={!!busy}
              onClick={() =>
                run("rescan", () => api.post("/admin/api/commands/rescan", rescan), "Rescan started in the background")
              }
            >
              {busy === "rescan" ? <Spinner /> : <FiZap size={14} />} Start rescan
            </Button>
          </div>
          <p className="text-[11px] text-bone/55 mt-3">
            The user session must be valid for history scans. Watch the queue desk for new pending items.
          </p>
        </Panel>

        <Panel
          title="Merge duplicate titles"
          subtitle="Same title stored on more than one cluster"
          actions={
            <>
              <Button
                variant="ghost"
                disabled={!!busy}
                onClick={() => run("dry", () => api.post("/admin/api/merge-duplicates", {}, { apply: "false" }).then(setMerge), "Dry run complete")}
              >
                {busy === "dry" ? <Spinner /> : <FiRefreshCw size={14} />} Dry run
              </Button>
              <Button
                variant="danger"
                disabled={!!busy}
                onClick={() => run("apply", () => api.post("/admin/api/merge-duplicates", {}, { apply: "true" }).then(setMerge), "Duplicates merged")}
              >
                {busy === "apply" ? <Spinner /> : <FiCheck size={14} />} Apply merge
              </Button>
            </>
          }
        >
          {merge ? (
            <pre className="timecode text-[11px] leading-relaxed text-bone/65 bg-ink/60 border border-bone/8 rounded-md p-3 max-h-72 overflow-auto whitespace-pre-wrap break-all">
              {JSON.stringify(merge, null, 2)}
            </pre>
          ) : (
            <EmptyState title="No run yet">Start with a dry run to see what would be merged.</EmptyState>
          )}
        </Panel>

        <Panel title="Clear all caches" subtitle="Forces fresh reads on the next request">
          <div className="flex items-center gap-2">
            <Button
              variant="danger"
              disabled={!!busy}
              onClick={() => run("cache", () => api.post("/admin/api/commands/clear-cache", {}), "All caches cleared")}
            >
              {busy === "cache" ? <Spinner /> : <FiZap size={14} />} Clear everything
            </Button>
            <span className="text-[11px] text-bone/55">
              Video chunks, metadata, hot movies and the remux directory.
            </span>
          </div>
          <Field label="Targeted clear">
            <div className="flex flex-wrap gap-2 mt-1">
              {["video", "remux"].map((target) => (
                <Button
                  key={target}
                  variant="ghost"
                  disabled={!!busy}
                  onClick={() =>
                    run(`t-${target}`, () => api.post("/admin/api/cache/clear", { target }), `${target} cache cleared`)
                  }
                >
                  Clear {target}
                </Button>
              ))}
            </div>
          </Field>
        </Panel>
      </div>
    </div>
  );
}

import React, { useCallback, useEffect, useState } from "react";
import { FiChevronLeft, FiChevronRight, FiPlay, FiRefreshCw, FiSquare } from "react-icons/fi";
import { api } from "./api";
import {
  AdminErrorState,
  Badge,
  Button,
  ConfirmModal,
  EmptyState,
  Label,
  Modal,
  Panel,
  Select,
  Spinner,
  cx,
  toast,
} from "./ui";

/* Audio-language curation plus the two bulk jobs that feed it. Both jobs are
   off by default on the server; the switches below reflect that. */
export default function CurationPage() {
  const [rows, setRows] = useState(null);
  const [jobs, setJobs] = useState(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [minCount, setMinCount] = useState(0);
  const [sort, setSort] = useState("count:desc");
  const [page, setPage] = useState(1);
  const [flag, setFlag] = useState("no_poster");
  const [confirmRemediation, setConfirmRemediation] = useState(false);
  const [detail, setDetail] = useState(null);

  const loadCuration = useCallback(async () => {
    try {
      const d = await api.get("/admin/api/audio-curation", {
        min_count: minCount,
        sort,
        page,
        page_size: 30,
      });
      setRows(d);
      setError("");
    } catch (e) {
      setError(e.message);
    }
  }, [minCount, sort, page]);

  const loadJobs = useCallback(async () => {
    try {
      setJobs(await api.get("/admin/api/jobs"));
    } catch (e) {
      /* the jobs panel is secondary — the curation list still works */
    }
  }, []);

  useEffect(() => {
    loadCuration();
  }, [loadCuration]);
  useEffect(() => {
    loadJobs();
  }, [loadJobs]);

  const act = async (label, fn) => {
    setBusy(true);
    try {
      await fn();
      toast(label);
      await Promise.all([loadCuration(), loadJobs()]);
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setBusy(false);
    }
  };

  const openDetail = async (row) => {
    setBusy(true);
    try {
      const d = await api.get(
        `/admin/api/media/${row.type}/${row.db_index}/${row.tmdb_id}`
      );
      setDetail({ row, media: d });
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setBusy(false);
    }
  };

  if (error && !rows)
    return (
      <Panel>
        <AdminErrorState title="Curation unavailable" error={error} />
      </Panel>
    );
  if (!rows)
    return (
      <div className="flex justify-center py-24">
        <Spinner className="w-6 h-6" />
      </div>
    );

  const items = rows.items || [];
  const total = rows.total_count || 0;
  const pages = Math.max(1, Math.ceil(total / (rows.page_size || 30)));
  const switches = jobs?.switches || {};
  const jobRows = jobs?.jobs || [];
  const flags = jobs?.flags || ["no_poster", "no_backdrop", "no_description", "no_genres", "no_cast"];

  const latestJob = (kind) => jobRows.find((j) => j.kind === kind);

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-end gap-3">
        <div className="mr-auto">
          <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Curation</p>
          <h1 className="font-display text-3xl mt-1.5">Audio languages</h1>
          <p className="text-sm text-bone/60 mt-1">
            {total.toLocaleString()} titles ranked by distinct audio languages
          </p>
        </div>
        <Button variant="ghost" onClick={() => { loadCuration(); loadJobs(); }} disabled={busy}>
          <FiRefreshCw size={14} /> Refresh
        </Button>
      </header>

      <div className="grid lg:grid-cols-2 gap-5">
        <Panel
          title="Audio-language backfill"
          subtitle="Denormalize the audio languages of every title"
          actions={
            switches.audio_lang_backfill ? (
              <Badge tone="ok">Enabled</Badge>
            ) : (
              <Badge tone="warn">Disabled</Badge>
            )
          }
        >
          <p className="text-sm text-bone/60">
            Walks every cluster and both media collections, writing
            <code className="text-bone/80"> audio_languages</code> and
            <code className="text-bone/80"> audio_language_count</code> onto each title.
            A title that was never probed stays at zero — the job reports how
            many, so the gap is a number rather than a surprise.
          </p>
          {latestJob("audio_lang_backfill") ? (
            <JobSummary job={latestJob("audio_lang_backfill")} />
          ) : null}
          <div className="mt-4 flex items-center gap-2">
            <Button
              variant="primary"
              disabled={busy || !switches.audio_lang_backfill}
              onClick={() =>
                act("Backfill started", () =>
                  api.post("/admin/api/jobs/start", {
                    kind: "audio_lang_backfill",
                    params: {},
                  })
                )
              }
            >
              <FiPlay size={14} /> Start backfill
            </Button>
            <Button
              variant="ghost"
              disabled={busy}
              onClick={() =>
                act("Backfill stopping", () =>
                  api.post("/admin/api/jobs/stop", { kind: "audio_lang_backfill" })
                )
              }
            >
              <FiSquare size={14} /> Stop
            </Button>
            {!switches.audio_lang_backfill ? (
              <span className="text-[11px] text-bone/55">
                Set AUDIO_LANG_BACKFILL=true on the server to enable this.
              </span>
            ) : null}
          </div>
        </Panel>

        <Panel
          title="Metadata remediation"
          subtitle="Refresh metadata for titles missing a field"
          actions={
            switches.metadata_remediation ? (
              <Badge tone="ok">Enabled</Badge>
            ) : (
              <Badge tone="warn">Disabled</Badge>
            )
          }
        >
          <div className="mb-3">
            <Label htmlFor="remediation-flag">Missing</Label>
            <Select
              id="remediation-flag"
              value={flag}
              onChange={(e) => setFlag(e.target.value)}
            >
              {flags.map((f) => (
                <option key={f} value={f}>
                  {f}
                </option>
              ))}
            </Select>
          </div>
          {latestJob("metadata_remediation") ? (
            <JobSummary job={latestJob("metadata_remediation")} />
          ) : null}
          <div className="mt-4 flex items-center gap-2">
            <Button
              variant="primary"
              disabled={busy || !switches.metadata_remediation}
              onClick={() => setConfirmRemediation(true)}
            >
              <FiPlay size={14} /> Start remediation
            </Button>
            <Button
              variant="ghost"
              disabled={busy}
              onClick={() =>
                act("Remediation stopping", () =>
                  api.post("/admin/api/jobs/stop", { kind: "metadata_remediation" })
                )
              }
            >
              <FiSquare size={14} /> Stop
            </Button>
            {!switches.metadata_remediation ? (
              <span className="text-[11px] text-bone/55">
                Set METADATA_REMEDIATION=true on the server to enable this.
              </span>
            ) : null}
          </div>
        </Panel>
      </div>

      <Panel
        title="Titles"
        subtitle="A title whose audio was replaced by a thinner one is findable here"
        actions={
          <div className="flex items-center gap-2">
            <Select
              aria-label="Minimum language count"
              value={String(minCount)}
              onChange={(e) => {
                setMinCount(Number(e.target.value));
                setPage(1);
              }}
              className="w-28"
            >
              {[0, 1, 2, 3, 4, 5].map((n) => (
                <option key={n} value={n}>
                  {n === 0 ? "All" : `${n}+`}
                </option>
              ))}
            </Select>
            <Select
              aria-label="Sort"
              value={sort}
              onChange={(e) => {
                setSort(e.target.value);
                setPage(1);
              }}
              className="w-36"
            >
              <option value="count:desc">Most languages</option>
              <option value="count:asc">Fewest languages</option>
              <option value="title:asc">Title A–Z</option>
              <option value="title:desc">Title Z–A</option>
            </Select>
          </div>
        }
      >
        {items.length === 0 ? (
          <EmptyState title="Nothing to curate yet">
            Run the audio-language backfill to populate this list.
          </EmptyState>
        ) : (
          <div className="overflow-x-auto -mx-1 px-1">
            <table className="w-full text-sm min-w-[640px]">
              <thead>
                <tr className="text-left">
                  {["Title", "Type", "Languages", "Count", ""].map((h) => (
                    <th
                      key={h}
                      className="timecode text-[10px] uppercase tracking-[0.14em] text-bone/60 pb-2 pr-3 font-normal"
                    >
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {items.map((row) => (
                  <tr key={`${row.db_index}-${row.type}-${row.tmdb_id}`} className="border-t border-bone/6">
                    <td className="py-2.5 pr-3">
                      <p className="text-bone truncate max-w-[280px]">{row.title || "—"}</p>
                      <p className="timecode text-[10px] text-bone/55">
                        {row.tmdb_id}
                        {row.release_year ? ` • ${row.release_year}` : ""}
                      </p>
                    </td>
                    <td className="py-2.5 pr-3">
                      <Badge>{row.type}</Badge>
                    </td>
                    <td className="py-2.5 pr-3">
                      <div className="flex flex-wrap gap-1">
                        {(row.audio_languages || []).length === 0 ? (
                          <span className="text-[11px] text-bone/55">none known</span>
                        ) : (
                          (row.audio_languages || []).map((lang) => (
                            <span
                              key={lang}
                              className="timecode text-[10px] border border-projector/35 text-projector px-1.5 py-0.5 rounded-[2px]"
                            >
                              {lang}
                            </span>
                          ))
                        )}
                      </div>
                      {(row.dropped_audio_languages || []).length ? (
                        <p className="timecode text-[10px] text-amber-200/80 mt-1">
                          capped away: {row.dropped_audio_languages.join(", ")}
                        </p>
                      ) : null}
                    </td>
                    <td className="py-2.5 pr-3 timecode text-[12px] text-bone/70 tabular-nums">
                      {row.audio_language_count ?? 0}
                    </td>
                    <td className="py-2.5 text-right">
                      <Button variant="ghost" disabled={busy} onClick={() => openDetail(row)}>
                        Files
                      </Button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        <div className="mt-4 pt-4 border-t border-bone/6 flex items-center justify-between">
          <p className="timecode text-[10px] text-bone/60">
            page {rows.page} of {pages}
          </p>
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              disabled={busy || rows.page <= 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              <FiChevronLeft size={14} /> Newer
            </Button>
            <Button
              variant="ghost"
              disabled={busy || rows.page >= pages}
              onClick={() => setPage((p) => p + 1)}
            >
              Older <FiChevronRight size={14} />
            </Button>
          </div>
        </div>
      </Panel>

      <ConfirmModal
        open={confirmRemediation}
        onClose={() => setConfirmRemediation(false)}
        busy={busy}
        title={`Refresh metadata for every title missing "${flag}"`}
        confirmWord="RUN"
        confirmLabel="Start remediation"
        onConfirm={() =>
          act("Remediation started", () =>
            api.post("/admin/api/jobs/start", {
              kind: "metadata_remediation",
              params: { flag, media_type: "all" },
            })
          ).finally(() => setConfirmRemediation(false))
        }
      />

      <Modal
        open={Boolean(detail)}
        onClose={() => setDetail(null)}
        title={detail?.row?.title || "Files"}
        width="max-w-3xl"
      >
        {detail ? <FileBreakdown media={detail.media} /> : null}
      </Modal>
    </div>
  );
}

function JobSummary({ job }) {
  const counts = job.counts || {};
  const entries = Object.entries(counts);
  return (
    <div className="mt-3 rounded-md border border-bone/8 bg-ink/40 px-3.5 py-3">
      <div className="flex items-center gap-2">
        <Badge tone={job.status === "error" ? "bad" : job.status === "running" ? "good" : "neutral"}>
          {job.status}
        </Badge>
        {job.updated_at ? (
          <span className="timecode text-[10px] text-bone/60">{job.updated_at}</span>
        ) : null}
      </div>
      {entries.length > 0 ? (
        <dl className="mt-2 grid grid-cols-2 sm:grid-cols-4 gap-y-1 gap-x-3 text-[11px]">
          {entries.map(([key, value]) => (
            <React.Fragment key={key}>
              <dt className="timecode text-bone/60 truncate">{key}</dt>
              <dd className="timecode text-bone/80 text-right tabular-nums">{String(value)}</dd>
            </React.Fragment>
          ))}
        </dl>
      ) : null}
      {job.error ? <p className="text-[11px] text-signal mt-2">{job.error}</p> : null}
    </div>
  );
}

function FileBreakdown({ media }) {
  const files = [];
  if (media?.telegram) {
    media.telegram.forEach((q) => files.push({ file: q }));
  }
  (media?.seasons || []).forEach((season) => {
    (season.episodes || []).forEach((episode) => {
      (episode.telegram || []).forEach((q) =>
        files.push({
          file: q,
          label: `S${season.season_number}E${episode.episode_number}`,
        })
      );
    });
  });

  if (!files.length) return <p className="text-sm text-bone/50">This title has no files.</p>;

  return (
    <ul className="space-y-2">
      {files.map((entry, i) => {
        const tracks = entry.file.audio_tracks || [];
        return (
          <li
            key={i}
            className="rounded-md border border-bone/8 bg-ink/40 px-3.5 py-2.5 flex items-start gap-3"
          >
            <div className="min-w-0 flex-1">
              <p className="text-sm text-bone truncate">
                {entry.label ? `${entry.label} • ` : ""}
                {entry.file.name || entry.file.quality || "file"}
              </p>
              <div className="flex flex-wrap gap-1 mt-1">
                {tracks.length === 0 ? (
                  <span className="timecode text-[10px] text-bone/55">not probed</span>
                ) : (
                  tracks.map((t, j) => (
                    <span
                      key={j}
                      className="timecode text-[10px] border border-bone/15 text-bone/60 px-1.5 py-0.5 rounded-[2px]"
                    >
                      {t.language}
                    </span>
                  ))
                )}
              </div>
            </div>
          </li>
        );
      })}
    </ul>
  );
}

import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { FiAlertTriangle, FiArrowRight, FiRefreshCw } from "react-icons/fi";
import { api } from "./api";
import { Badge, Button, EmptyState, Panel, Spinner, cx, toast } from "./ui";
import ViewsPanel from "./ViewsPanel";

function Stat({ label, value, hint, tone = "neutral" }) {
  const accents = {
    neutral: "text-bone",
    good: "text-projector",
    warn: "text-amber-200",
    bad: "text-signal",
  };
  return (
    <div className="glass-card rounded-lg px-4 py-4 relative overflow-hidden">
      <p className="timecode text-[9px] uppercase tracking-[0.22em] text-bone/60">{label}</p>
      <p className={cx("mt-2 font-display text-3xl leading-none tabular-nums", accents[tone])}>
        {value ?? "—"}
      </p>
      {hint && <p className="mt-2 text-[11px] text-bone/55 truncate">{hint}</p>}
    </div>
  );
}

export default function DashboardPage() {
  const [stats, setStats] = useState(null);
  const [health, setHealth] = useState(null);
  const [recent, setRecent] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  const load = async () => {
    setRefreshing(true);
    try {
      const [a, h, list] = await Promise.all([
        api.get("/admin/api/analytics"),
        api.get("/admin/api/health").catch(() => null),
        api
          .get("/admin/api/media", { media_type: "all", page: 1, page_size: 8, sort: "updated:desc" })
          .catch(() => ({ items: [] })),
      ]);
      setStats(a);
      setHealth(h);
      setRecent(list.items || []);
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (loading)
    return (
      <div className="flex justify-center py-24">
        <Spinner className="w-6 h-6" />
      </div>
    );

  const queue = health?.queue || {};
  const alerts = health?.alerts || [];
  const uptime = health?.system?.uptime_seconds;
  const uptimeLabel =
    uptime != null ? `${Math.floor(uptime / 3600)}h ${Math.floor((uptime % 3600) / 60)}m` : stats?.system?.uptime;

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-end gap-3 mb-1">
        <div className="mr-auto">
          <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Overview</p>
          <h1 className="font-display text-3xl mt-1.5">Library at a glance</h1>
        </div>
        <Badge tone={health?.status === "ok" ? "ok" : "warn"}>
          {health?.status === "ok" ? "All systems nominal" : "Degraded"}
        </Badge>
        <Button variant="ghost" onClick={load} disabled={refreshing}>
          {refreshing ? <Spinner /> : <FiRefreshCw size={14} />} Refresh
        </Button>
      </header>

      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-3">
        <Stat label="Movies" value={stats?.media?.movies} tone="good" />
        <Stat label="Series" value={stats?.media?.tv_series} tone="good" />
        <Stat label="Anime" value={stats?.media?.anime} />
        <Stat label="Video files" value={stats?.files?.total} />
        <Stat label="Subtitles" value={stats?.files?.subtitles} />
        <Stat
          label="Queue pending"
          value={queue.pending ?? 0}
          tone={queue.pending > 500 ? "warn" : "neutral"}
          hint={queue.paused ? "queue paused" : `${queue.workers || 0} workers`}
        />
      </div>

      <div className="grid lg:grid-cols-[1.4fr_1fr] gap-5">
        <Panel title="Recently updated" subtitle="Last eight titles touched">
          {recent.length === 0 ? (
            <EmptyState title="Nothing here yet">Media saved by the bot will show up here.</EmptyState>
          ) : (
            <ul className="grid sm:grid-cols-2 gap-2.5">
              {recent.map((m) => (
                <li key={`${m.type}-${m.db_index}-${m.tmdb_id}`}>
                  <Link
                    to={`/admin/media/${m.collection || m.type}/${m.db_index}/${m.tmdb_id}`}
                    className="group flex items-center gap-3 rounded-md border border-bone/8 bg-ink/40 p-2.5 hover:border-projector/40 hover:bg-bone/4 transition-colors"
                  >
                    <img
                      src={m.poster || m.backdrop || ""}
                      alt=""
                      loading="lazy"
                      className="w-9 h-[3.25rem] object-cover rounded-[3px] bg-carbon ring-1 ring-inset ring-bone/10 shrink-0"
                    />
                    <span className="min-w-0 flex-1">
                      <span className="block text-sm font-medium text-bone truncate group-hover:text-projector transition-colors">
                        {m.title}
                      </span>
                      <span className="block timecode text-[10px] text-bone/60 mt-0.5">
                        {m.release_year || "—"} • {m.file_count || 0} files • {m.subtitle_count || 0} subs
                      </span>
                    </span>
                    <FiArrowRight className="text-bone/50 group-hover:text-projector shrink-0" />
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </Panel>

        <div className="space-y-5">
          <ViewsPanel />
          <Panel title="Alerts" subtitle="Straight from the health check">
            {alerts.length === 0 ? (
              <p className="text-sm text-bone/50">No active alerts. 🎉</p>
            ) : (
              <ul className="space-y-2">
                {alerts.map((a, i) => (
                  <li
                    key={i}
                    className="flex items-start gap-2.5 rounded-md border border-amber-300/30 bg-amber-300/6 px-3 py-2.5 text-sm text-amber-100/90"
                  >
                    <FiAlertTriangle className="mt-0.5 shrink-0 text-amber-300" size={14} />
                    <span>{a}</span>
                  </li>
                ))}
              </ul>
            )}
          </Panel>

          <Panel title="System" subtitle="Backend vitals">
            <dl className="space-y-2.5 text-sm">
              {[
                ["Version", stats?.system?.version],
                ["Uptime", uptimeLabel],
                ["Python", health?.system?.python],
                ["ffmpeg", health?.system?.ffmpeg ? "available" : "missing"],
                ["Disk free", health?.system?.disk ? `${health.system.disk.free_gb} GB` : undefined],
              ].map(([k, v]) => (
                <div key={k} className="flex items-baseline gap-3">
                  <dt className="timecode text-[10px] uppercase tracking-[0.14em] text-bone/60 mr-auto">{k}</dt>
                  <dd className="timecode text-bone/80">{v ?? "—"}</dd>
                </div>
              ))}
            </dl>
            <div className="mt-4 pt-4 border-t border-bone/6 flex flex-wrap gap-2">
              <Link to="/admin/queue">
                <Button variant="ghost">Queue desk</Button>
              </Link>
              <Link to="/admin/commands">
                <Button variant="ghost">Commands</Button>
              </Link>
              <Link to="/admin/health">
                <Button variant="ghost">Full health</Button>
              </Link>
            </div>
          </Panel>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useState } from "react";
import { FiRefreshCw, FiTrash2, FiX } from "react-icons/fi";
import { api } from "./api";
import { Badge, Button, EmptyState, Label, Panel, Spinner, TextInput, toast } from "./ui";

const PAGE_SIZE = 50;

export default function FailedFilesPage() {
  const [data, setData] = useState(null);
  const [page, setPage] = useState(1);
  const [reason, setReason] = useState("");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const load = async (targetPage = page) => {
    setLoading(true);
    try {
      const d = await api.get("/admin/api/failed-files", {
        page: targetPage,
        page_size: PAGE_SIZE,
        reason_filter: reason || undefined,
        date_from: from || undefined,
        date_to: to || undefined,
      });
      setData(d);
      setError("");
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load(1);
    setPage(1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reason, from, to]);

  const guard = async (fn, ok) => {
    setBusy(true);
    try {
      await fn();
      toast(ok);
      await load();
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setBusy(false);
    }
  };

  const items = data?.items || [];
  const total = data?.total_count || 0;
  const pages = data?.total_pages || 1;

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-end gap-3">
        <div className="mr-auto">
          <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Ingest errors</p>
          <h1 className="font-display text-3xl mt-1.5">Failed files</h1>
          <p className="text-sm text-bone/60 mt-1">
            {loading ? "Loading…" : `${total.toLocaleString()} entries waiting to be retried or cleared`}
          </p>
        </div>
        <Button
          variant="ghost"
          disabled={busy || total === 0}
          onClick={() =>
            guard(() => api.post("/admin/api/failed-files/retry-all", undefined, { reason_filter: reason || undefined, limit: 25 }), "Oldest 25 re-queued")
          }
        >
          <FiRefreshCw size={14} /> Retry oldest 25
        </Button>
        <Button
          variant="danger"
          disabled={busy || total === 0}
          onClick={() => {
            if (!window.confirm("Clear all failed-file log entries?")) return;
            guard(() => api.delete("/admin/api/failed-files", { reason_filter: reason || undefined }), "Log cleared");
          }}
        >
          <FiTrash2 size={14} /> Clear log
        </Button>
      </header>

      <Panel>
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          <div>
            <Label htmlFor="ff-text">Reason contains</Label>
            <TextInput
              id="ff-text"
              defaultValue={reason}
              placeholder="e.g. FloodWait"
              onKeyDown={(e) => e.key === "Enter" && setReason(e.currentTarget.value.trim())}
            />
          </div>
          <div>
            <Label htmlFor="ff-from">From</Label>
            <TextInput id="ff-from" type="date" value={from} onChange={(e) => setFrom(e.target.value)} />
          </div>
          <div>
            <Label htmlFor="ff-to">To</Label>
            <TextInput id="ff-to" type="date" value={to} onChange={(e) => setTo(e.target.value)} />
          </div>
        </div>
      </Panel>

      <Panel title="Entries" subtitle={`Page ${page} of ${pages}`}>
        {error ? (
          <EmptyState icon={<FiX />} title="Could not load failed files">
            {error}
          </EmptyState>
        ) : loading ? (
          <div className="flex justify-center py-14">
            <Spinner className="w-6 h-6" />
          </div>
        ) : items.length === 0 ? (
          <EmptyState title="Nothing failed here">
            Every file the bot received made it into the library. 🎉
          </EmptyState>
        ) : (
          <ul className="space-y-2">
            {items.map((f) => (
              <li
                key={f._id || f.id}
                className="flex items-start gap-3 rounded-md border border-bone/8 bg-ink/40 px-3.5 py-3 hover:border-signal/30 transition-colors"
              >
                <span className="w-8 h-8 rounded-md bg-signal/10 text-signal flex items-center justify-center shrink-0">
                  ⚠
                </span>
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-bone truncate">{f.title || f.filename || "Untitled"}</p>
                  <p className="text-[12px] text-bone/50 mt-0.5 line-clamp-2">{f.reason || "Unknown reason"}</p>
                  <p className="timecode text-[10px] text-bone/55 mt-1">
                    {f.timestamp ? new Date(f.timestamp).toLocaleString() : "—"}
                    {f.filename ? ` • ${f.filename}` : ""}
                  </p>
                </div>
                <div className="flex gap-1.5 shrink-0">
                  <Button
                    variant="ghost"
                    disabled={busy}
                    onClick={() => guard(() => api.post(`/admin/api/failed-files/${f._id}/retry`), "Re-queued from Telegram")}
                  >
                    Retry
                  </Button>
                  <Button
                    variant="danger"
                    disabled={busy}
                    onClick={() => guard(() => api.delete(`/admin/api/failed-files/${f._id}`), "Entry removed")}
                  >
                    <FiTrash2 size={14} />
                  </Button>
                </div>
              </li>
            ))}
          </ul>
        )}

        {pages > 1 && (
          <nav className="mt-5 pt-4 border-t border-bone/6 flex items-center justify-center gap-2">
            <Button
              variant="ghost"
              disabled={page <= 1 || loading}
              onClick={() => {
                setPage(page - 1);
                load(page - 1);
              }}
            >
              Previous
            </Button>
            <Badge>{`${page} / ${pages}`}</Badge>
            <Button
              variant="ghost"
              disabled={page >= pages || loading}
              onClick={() => {
                setPage(page + 1);
                load(page + 1);
              }}
            >
              Next
            </Button>
          </nav>
        )}
      </Panel>
    </div>
  );
}

import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { FiActivity, FiAlertTriangle, FiRefreshCw } from "react-icons/fi";
import { api } from "./api";
import { Badge, Button, EmptyState, Panel, Spinner, cx, formatEta, toast } from "./ui";

export default function HealthPage() {
  const [health, setHealth] = useState(null);
  const [lib, setLib] = useState(null);
  const [loading, setLoading] = useState(true);
  const [auto, setAuto] = useState(true);

  const load = async () => {
    try {
      const [h, l] = await Promise.all([
        api.get("/admin/api/health"),
        api.get("/admin/api/library-health", { sample_limit: 4 }).catch(() => null),
      ]);
      setHealth(h);
      setLib(l);
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
    if (!auto) return undefined;
    const id = setInterval(load, 15000);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [auto]);

  if (loading)
    return (
      <div className="flex justify-center py-24">
        <Spinner className="w-6 h-6" />
      </div>
    );
  if (!health)
    return (
      <Panel>
        <EmptyState title="Health check failed">The backend did not answer — try again in a moment.</EmptyState>
      </Panel>
    );

  const sys = health.system || {};
  const q = health.queue || {};
  const clusters = health.clusters || [];
  const storage = health.storage?.clusters || [];

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-end gap-3">
        <div className="mr-auto">
          <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Diagnostics</p>
          <h1 className="font-display text-3xl mt-1.5 flex items-center gap-3">
            Health
            <Badge tone={health.status === "ok" ? "ok" : "warn"}>{health.status}</Badge>
          </h1>
        </div>
        <Button variant="ghost" onClick={() => setAuto((v) => !v)}>
          <FiActivity size={14} /> {auto ? "Auto on" : "Auto off"}
        </Button>
        <Button variant="ghost" onClick={load}>
          <FiRefreshCw size={14} /> Refresh
        </Button>
      </header>

      <Panel title="Alerts">
        {(health.alerts || []).length === 0 ? (
          <p className="text-sm text-bone/50">Nothing is on fire. 🎉</p>
        ) : (
          <ul className="space-y-2">
            {health.alerts.map((a, i) => (
              <li
                key={i}
                className="flex items-start gap-2.5 rounded-md border border-amber-300/30 bg-amber-300/6 px-3 py-2.5 text-sm text-amber-100/90"
              >
                <FiAlertTriangle className="mt-0.5 shrink-0 text-amber-300" size={14} />
                {a}
              </li>
            ))}
          </ul>
        )}
      </Panel>

      <div className="grid lg:grid-cols-2 gap-5">
        <Panel title="MongoDB clusters" subtitle={`${clusters.length} reachable endpoints`}>
          <ul className="space-y-2">
            {clusters.map((c) => (
              <li key={c.cluster} className="flex items-center gap-3 rounded-md border border-bone/8 bg-ink/40 px-3.5 py-2.5">
                <span
                  className={cx(
                    "w-2 h-2 rounded-full shrink-0",
                    c.status === "up" ? "bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,0.8)]" : "bg-signal"
                  )}
                />
                <span className="text-sm text-bone mr-auto">Cluster {c.cluster}</span>
                <span className="timecode text-[10px] text-bone/50 uppercase tracking-wider">
                  {c.error || c.status}
                </span>
              </li>
            ))}
          </ul>
        </Panel>

        <Panel title="Storage quota" subtitle="Per-cluster usage against the configured cap">
          {storage.length === 0 ? (
            <p className="text-sm text-bone/60">Storage report unavailable.</p>
          ) : (
            <ul className="space-y-3.5">
              {storage.map((c) => (
                <li key={c.cluster}>
                  <div className="flex items-baseline gap-3 mb-1.5">
                    <span className="text-sm text-bone mr-auto">Cluster {c.cluster}</span>
                    <span className="timecode text-[11px] text-bone/60">
                      {c.used_mb ?? 0} / {c.quota_mb ?? "?"} MB
                    </span>
                    <Badge tone={c.status === "alert" ? "warn" : "ok"}>{c.used_percent ?? 0}%</Badge>
                  </div>
                  <div className="h-1.5 rounded-full bg-bone/8 overflow-hidden">
                    <div
                      className={cx(
                        "h-full rounded-full transition-all",
                        c.status === "alert" ? "bg-signal" : "bg-projector/80"
                      )}
                      style={{ width: `${Math.max(2, Math.min(100, c.used_percent || 0))}%` }}
                    />
                  </div>
                </li>
              ))}
            </ul>
          )}
        </Panel>

        <Panel title="Runtime" subtitle="Backend process and tooling">
          <dl className="grid grid-cols-2 gap-y-3 gap-x-4 text-sm">
            {[
              ["Version", `v${sys.version || "—"}`],
              ["Python", sys.python],
              ["Uptime", sys.uptime_seconds ? formatEta(sys.uptime_seconds) : "—"],
              ["ffmpeg", sys.ffmpeg ? "available" : "missing"],
              ["ffprobe", sys.ffprobe ? "available" : "missing"],
              ["Disk free", sys.disk ? `${sys.disk.free_gb} / ${sys.disk.total_gb} GB` : "—"],
            ].map(([k, v]) => (
              <React.Fragment key={k}>
                <dt className="timecode text-[10px] uppercase tracking-[0.14em] text-bone/60">{k}</dt>
                <dd className="timecode text-bone/80 text-right">{v ?? "—"}</dd>
              </React.Fragment>
            ))}
          </dl>
        </Panel>

        <Panel title="Queue" subtitle="Live ingest pressure">
          <dl className="grid grid-cols-2 gap-y-3 gap-x-4 text-sm">
            {[
              ["State", q.paused ? "paused" : "running"],
              ["Engine", q.engine],
              ["Pending", q.pending],
              ["Processing", q.processing],
              ["Failed", q.failed],
              ["FloodWait", q.floodwait_seconds ? `${q.floodwait_seconds}s` : "none"],
              ["ETA", q.eta_seconds ? formatEta(q.eta_seconds) : "—"],
            ].map(([k, v]) => (
              <React.Fragment key={k}>
                <dt className="timecode text-[10px] uppercase tracking-[0.14em] text-bone/60">{k}</dt>
                <dd className="timecode text-bone/80 text-right">{v ?? "—"}</dd>
              </React.Fragment>
            ))}
          </dl>
          <Link
            to="/admin/queue"
            className="mt-4 inline-flex items-center gap-2 text-sm text-projector/80 hover:text-projector transition-colors"
          >
            Open the queue desk →
          </Link>
        </Panel>
      </div>

      {lib && (
        <Panel
          title="Library integrity"
          subtitle={`${lib.totals?.documents ?? 0} titles • ${lib.totals?.files ?? 0} files • ${
            lib.totals?.subtitles ?? 0
          } subs • ${lib.totals?.episodes ?? 0} episodes`}
        >
          <div className="grid sm:grid-cols-2 xl:grid-cols-3 gap-3">
            {(lib.categories || []).map((c) => (
              <div
                key={c.key}
                className={cx(
                  "rounded-md border px-3.5 py-3",
                  c.count ? "border-amber-300/25 bg-amber-300/5" : "border-bone/8 bg-ink/40"
                )}
              >
                <div className="flex items-baseline gap-2">
                  <p className="text-sm text-bone mr-auto">{c.label}</p>
                  <p
                    className={cx(
                      "font-display text-xl leading-none tabular-nums",
                      c.count ? "text-amber-200" : "text-emerald-300/80"
                    )}
                  >
                    {c.count}
                  </p>
                </div>
                <div className="flex flex-wrap gap-1.5 mt-2">
                  {(c.items || []).slice(0, 3).map((i) => (
                    <Link
                      key={`${i.type}-${i.tmdb_id}`}
                      to={`/admin/media/${i.type}/${i.db_index || 1}/${i.tmdb_id}`}
                      className="text-[11px] px-2 py-0.5 rounded-[3px] border border-bone/12 text-bone/60 hover:text-projector hover:border-projector/40 transition-colors truncate max-w-[150px]"
                    >
                      {i.title}
                    </Link>
                  ))}
                  {(c.items || []).length === 0 && (
                    <span className="text-[11px] text-bone/55">Nothing to fix</span>
                  )}
                </div>
              </div>
            ))}
          </div>
        </Panel>
      )}
    </div>
  );
}

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { FiArrowDown, FiArrowUp, FiPlus, FiRefreshCw, FiSearch, FiTrash2, FiX } from "react-icons/fi";
import { api } from "./api";
import {
  AdminErrorState,
  Badge,
  Button,
  EmptyState,
  Label,
  Modal,
  Panel,
  Select,
  Spinner,
  TextInput,
  cx,
  toast,
} from "./ui";

/* Curated hero carousel for the homepage. Empty picks = the backend serves its
   own newest-titles fallback, so this page is inert until someone pins a title. */

const keyOf = (p) => `${p.type}/${p.db_index}/${p.tmdb_id}`;
const trim = (picks) => picks.map(({ type, db_index, tmdb_id }) => ({ type, db_index, tmdb_id }));

export default function HeroPage() {
  const [picks, setPicks] = useState([]);
  const [max, setMax] = useState(12);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [savedJson, setSavedJson] = useState("[]");
  const [searchOpen, setSearchOpen] = useState(false);

  const load = useCallback(async () => {
    try {
      const d = await api.get("/admin/api/hero");
      const rows = d.picks || [];
      setPicks(rows);
      setSavedJson(JSON.stringify(trim(rows)));
      setMax(d.max || 12);
      setError("");
    } catch (e) {
      setError(
        String(e.message).startsWith("404")
          ? "This backend has no hero endpoints yet — restart the API server (or deploy the backend) so /admin/api/hero exists. The homepage keeps serving its latest-releases carousel."
          : e.message
      );
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const dirty = JSON.stringify(trim(picks)) !== savedJson;
  const broken = picks.filter((p) => p.resolved === false);
  const full = picks.length >= max;
  const used = useMemo(() => new Set(picks.map(keyOf)), [picks]);

  const move = (index, delta) =>
    setPicks((prev) => {
      const to = index + delta;
      if (to < 0 || to >= prev.length) return prev;
      const next = [...prev];
      [next[index], next[to]] = [next[to], next[index]];
      return next;
    });

  const remove = (index) => setPicks((prev) => prev.filter((_, i) => i !== index));

  const add = (row) => {
    const kind = row.collection || row.type;
    if (kind !== "movie" && kind !== "tv") {
      toast("Only movies and series can be pinned", "error");
      return;
    }
    const pick = {
      type: kind,
      db_index: row.db_index,
      tmdb_id: row.tmdb_id,
      title: row.title,
      poster: row.poster,
      release_year: row.release_year,
      resolved: true,
    };
    if (used.has(keyOf(pick))) {
      toast("Already in the carousel", "error");
      return;
    }
    if (full) {
      toast(`The hero holds ${max} slots — remove one first`, "error");
      return;
    }
    setPicks((prev) => [...prev, pick]);
    setSearchOpen(false);
  };

  const save = async () => {
    if (broken.length) {
      toast(`${broken.length} slot(s) point at deleted titles — remove them first`, "error");
      return;
    }
    setBusy(true);
    try {
      await api.post("/admin/api/hero", { picks: trim(picks) });
      toast(picks.length ? "Hero carousel saved" : "Hero restored to automatic");
      await load();
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setBusy(false);
    }
  };

  if (loading)
    return (
      <div className="flex justify-center py-24">
        <Spinner className="w-6 h-6" />
      </div>
    );

  if (error && picks.length === 0 && savedJson === "[]")
    return (
      <Panel>
        <AdminErrorState title="Hero settings unavailable" error={error} />
      </Panel>
    );

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-end gap-3">
        <div className="mr-auto">
          <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Homepage</p>
          <h1 className="font-display text-3xl mt-1.5">Hero carousel</h1>
          <p className="text-sm text-bone/60 mt-1">
            {picks.length
              ? `${picks.length} of ${max} slots pinned, in slide order`
              : `Automatic — the newest ${max} titles until you pin something`}
          </p>
        </div>
        {error && <Badge tone="bad">{error}</Badge>}
        <Badge tone={picks.length ? "good" : "neutral"}>{picks.length ? "Curated" : "Auto"}</Badge>
        <Button variant="ghost" onClick={load} disabled={busy}>
          <FiRefreshCw size={14} /> Reload
        </Button>
        <Button variant="primary" disabled={busy || !dirty} onClick={save}>
          {dirty ? "Save changes" : "Saved"}
        </Button>
      </header>

      {broken.length > 0 && (
        <Panel
          title="Broken slots"
          subtitle="These titles are no longer in the library, so saving is blocked until they are removed"
        >
          <div className="flex flex-wrap gap-2">
            {picks.map(
              (p, i) =>
                p.resolved === false && (
                  <Button key={keyOf(p)} variant="danger" disabled={busy} onClick={() => remove(i)}>
                    <FiTrash2 size={14} /> Remove slot {i + 1}
                  </Button>
                )
            )}
          </div>
        </Panel>
      )}

      <Panel
        title="Slots"
        subtitle="The first slot is the slide the homepage opens on"
        actions={
          <>
            <Button variant="ghost" disabled={busy || picks.length === 0} onClick={() => setPicks([])}>
              Clear all
            </Button>
            <Button variant="primary" disabled={busy || full} onClick={() => setSearchOpen(true)}>
              <FiPlus size={14} /> Add title
            </Button>
          </>
        }
      >
        {picks.length === 0 ? (
          <EmptyState title="No pinned titles">
            The homepage falls back to the newest titles in the library. Pin a movie or series to take
            control.
          </EmptyState>
        ) : (
          <ul className="grid gap-3 grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6">
            {picks.map((p, i) => (
              <li
                key={keyOf(p)}
                className={cx(
                  "relative rounded-md border overflow-hidden",
                  p.resolved === false ? "border-signal/50 bg-signal/6" : "border-bone/8 bg-ink/40"
                )}
              >
                <div className="relative aspect-[2/3] bg-carbon">
                  {p.poster ? (
                    <img src={p.poster} alt="" loading="lazy" className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-bone/50 timecode text-[10px] uppercase">
                      no poster
                    </div>
                  )}
                  <span className="absolute top-1.5 left-1.5 timecode text-[10px] px-1.5 py-0.5 rounded-[2px] bg-ink/80 border border-bone/20 text-projector">
                    {i + 1}
                  </span>
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-ink via-ink/70 to-transparent pt-8 pb-2 px-2">
                    <p className="text-[11px] font-semibold text-bone leading-snug line-clamp-2">
                      {p.title || `${p.type} #${p.tmdb_id}`}
                    </p>
                    <p className="timecode text-[9px] text-bone/50 mt-1 uppercase tracking-wider">
                      {p.type === "tv" ? "Series" : "Movie"} • {p.release_year || "—"} • db {p.db_index}
                    </p>
                  </div>
                  {p.resolved === false && (
                    <span className="absolute top-1.5 right-1.5">
                      <Badge tone="bad">Missing</Badge>
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-1 px-2 py-1.5 border-t border-bone/6">
                  <Button variant="quiet" disabled={busy || i === 0} onClick={() => move(i, -1)}>
                    <FiArrowUp size={14} />
                  </Button>
                  <Button variant="quiet" disabled={busy || i === picks.length - 1} onClick={() => move(i, 1)}>
                    <FiArrowDown size={14} />
                  </Button>
                  <Button variant="quiet" className="ml-auto" disabled={busy} onClick={() => remove(i)}>
                    <FiX size={14} />
                  </Button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </Panel>

      <TitlePicker
        open={searchOpen}
        onClose={() => setSearchOpen(false)}
        onPick={add}
        used={used}
      />
    </div>
  );
}

function TitlePicker({ open, onClose, onPick, used }) {
  const [query, setQuery] = useState("");
  const [type, setType] = useState("movie");
  const [rows, setRows] = useState([]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const run = useCallback(async () => {
    setBusy(true);
    setError("");
    try {
      const d = await api.get("/admin/api/media", {
        media_type: type,
        query,
        sort: "year:desc",
        page: 1,
        page_size: 24,
      });
      setRows(d.items || []);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  }, [type, query]);

  useEffect(() => {
    if (open) run();
  }, [open, run]);

  return (
    <Modal open={open} onClose={onClose} title="Add a title to the hero" width="max-w-3xl">
      <div className="flex flex-wrap items-end gap-3 mb-4">
        <div className="flex-1 min-w-[200px]">
          <Label htmlFor="hero-q">Search</Label>
          <div className="relative">
            <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-bone/55" size={15} />
            <TextInput
              id="hero-q"
              value={query}
              placeholder="Title…"
              className="pl-9"
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && run()}
            />
          </div>
        </div>
        <div className="w-[160px]">
          <Label htmlFor="hero-type">Kind</Label>
          <Select id="hero-type" value={type} onChange={(e) => setType(e.target.value)}>
            <option value="movie">Movies</option>
            <option value="tv">Series</option>
            <option value="all">Everything</option>
          </Select>
        </div>
        <Button variant="primary" disabled={busy} onClick={run}>
          <FiSearch size={14} /> Search
        </Button>
      </div>

      {error ? (
        <EmptyState title="Search failed">{error}</EmptyState>
      ) : busy ? (
        <div className="flex justify-center py-14">
          <Spinner className="w-6 h-6" />
        </div>
      ) : rows.length === 0 ? (
        <EmptyState title="No titles found">Try a shorter search term.</EmptyState>
      ) : (
        <ul className="grid gap-3 grid-cols-2 sm:grid-cols-3 lg:grid-cols-4">
          {rows.map((m) => {
            const k = `${m.collection || m.type}/${m.db_index}/${m.tmdb_id}`;
            const already = used.has(k);
            return (
              <li key={k} className="rounded-md border border-bone/8 bg-ink/40 p-2">
                <div className="aspect-[2/3] rounded-[4px] bg-carbon overflow-hidden">
                  {m.poster ? (
                    <img src={m.poster} alt="" loading="lazy" className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-bone/50 timecode text-[10px] uppercase">
                      no poster
                    </div>
                  )}
                </div>
                <p className="text-[11px] text-bone leading-snug line-clamp-2 mt-2">{m.title}</p>
                <p className="timecode text-[9px] text-bone/60 mt-1 uppercase tracking-wider">
                  {m.collection || m.type} • {m.release_year || "—"} • {m.file_count || 0}f
                </p>
                <Button
                  variant={already ? "ghost" : "primary"}
                  className="w-full mt-2"
                  disabled={already}
                  onClick={() => onPick(m)}
                >
                  {already ? "In carousel" : "Add"}
                </Button>
              </li>
            );
          })}
        </ul>
      )}
    </Modal>
  );
}

import React, { useCallback, useEffect, useState } from "react";
import { FiActivity, FiPlay, FiRefreshCw, FiSquare } from "react-icons/fi";
import { api } from "./api";
import { useChannels } from "./channels";
import { AdminErrorState, Badge, Button, EmptyState, Label, Panel, Spinner, TextArea, TextInput, cx, formatEta, toast } from "./ui";

function scanTone(status) {
  if (status === "running") return "good";
  if (status === "waiting") return "warn";
  if (status === "error") return "bad";
  if (status === "completed") return "ok";
  return "neutral";
}

/* Channel indexing: the same start/stop path the bot uses, so the panel and
   the bot can never diverge. */
export default function IndexingPage() {
  const { channels } = useChannels();
  const [data, setData] = useState(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [links, setLinks] = useState("");
  const [picked, setPicked] = useState([]);
  const [auto, setAuto] = useState(true);
  const [skipFirst, setSkipFirst] = useState("0");
  const [skipDefault, setSkipDefault] = useState(0);

  const toggleChannel = (id) =>
    setPicked((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    );

  const load = useCallback(async () => {
    try {
      const d = await api.get("/admin/api/index-scans");
      setData(d);
      setError("");
    } catch (e) {
      setError(e.message);
    }
  }, []);

  useEffect(() => {
    load();
    if (!auto) return undefined;
    const id = setInterval(load, 5000);
    return () => clearInterval(id);
  }, [load, auto]);

  /* The runtime knob is the default for both the bot prompt and this page. */
  useEffect(() => {
    api
      .get("/admin/api/config")
      .then((d) => {
        const row = (d.knobs || []).find(
          (k) => k.key === "index_skip_first_messages"
        );
        if (row) {
          setSkipDefault(Number(row.value) || 0);
          setSkipFirst(String(row.value ?? 0));
        }
      })
      .catch(() => {
        /* an older backend simply has no knob — the field still works */
      });
  }, []);

  const act = async (label, fn) => {
    setBusy(true);
    try {
      await fn();
      toast(label);
      await load();
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setBusy(false);
    }
  };

  if (error && !data)
    return (
      <Panel>
        <AdminErrorState title="Indexing unavailable" error={error} />
      </Panel>
    );
  if (!data)
    return (
      <div className="flex justify-center py-24">
        <Spinner className="w-6 h-6" />
      </div>
    );

  const registry = data.registry || {};
  const scans = data.scans || [];
  const running = registry.running || [];
  const waiting = data.waiting || [];

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-end gap-3">
        <div className="mr-auto">
          <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Coverage</p>
          <h1 className="font-display text-3xl mt-1.5">Channel indexing</h1>
          <p className="text-sm text-bone/60 mt-1">
            cap {data.cap} scan{data.cap === 1 ? "" : "s"} · {running.length} running ·{" "}
            {waiting.length} waiting{auto ? " · refreshing every 5s" : ""}
          </p>
        </div>
        <Badge tone={running.length ? "good" : "neutral"}>
          {running.length ? "Scanning" : "Idle"}
        </Badge>
        <Button variant="ghost" onClick={() => setAuto((v) => !v)}>
          <FiActivity size={14} /> {auto ? "Auto-refresh on" : "Auto-refresh off"}
        </Button>
        <Button variant="ghost" onClick={load} disabled={busy}>
          <FiRefreshCw size={14} />
        </Button>
      </header>

      <div className="grid lg:grid-cols-2 gap-5">
        <Panel
          title="Start a scan"
          subtitle="Paste t.me post links, one per line"
          actions={
            <Button
              variant="danger"
              disabled={busy || (running.length === 0 && waiting.length === 0)}
              onClick={() =>
                act("All scans stopping", () => api.post("/admin/api/index-scans/stop", {}))
              }
            >
              <FiSquare size={14} /> Stop all
            </Button>
          }
        >
          <Label>Or pick configured channels</Label>
          {channels.length > 0 ? (
            <div className="flex flex-wrap gap-2 mb-3">
              {channels.map((c) => {
                const active = picked.includes(c.id);
                return (
                  <button
                    key={c.index}
                    type="button"
                    aria-pressed={active}
                    onClick={() => toggleChannel(c.id)}
                    className={cx(
                      "rounded-md border px-2.5 py-1.5 timecode text-[11px] transition-colors",
                      active
                        ? "border-projector/60 bg-projector/12 text-projector"
                        : "border-bone/12 bg-ink/40 text-bone/55 hover:text-bone"
                    )}
                  >
                    {active ? "✓ " : ""}{c.label}
                  </button>
                );
              })}
            </div>
          ) : (
            <p className="text-[11px] text-bone/55 mb-3">
              No channels listed by the backend — paste post links below instead.
            </p>
          )}

          <Label htmlFor="index-links">Links (optional)</Label>
          <TextArea
            id="index-links"
            value={links}
            onChange={(e) => setLinks(e.target.value)}
            rows={4}
            className="font-mono text-[12px]"
            placeholder={"https://t.me/c/123456/789\nhttps://t.me/mychannel/42"}
          />
          <div className="mt-3 flex flex-wrap items-end gap-3">
            <div>
              <Label htmlFor="index-skip">Skip newest messages</Label>
              <TextInput
                id="index-skip"
                type="number"
                min="0"
                max="100000"
                step="1"
                value={skipFirst}
                onChange={(e) => setSkipFirst(e.target.value)}
                className="w-32 text-right tabular-nums"
                aria-label="Skip newest messages"
              />
            </div>
            <p className="text-[11px] text-bone/60 max-w-[340px] pb-2">
              Ignore the newest N posts in each channel (pinned promos, welcome
              posts). 0 indexes everything · runtime default {skipDefault}. The
              answer is saved with the scan and survives a restart.
            </p>
          </div>
          <div className="mt-3 flex items-center gap-2">
            <Button
              variant="primary"
              disabled={busy || (!links.trim() && picked.length === 0)}
              onClick={() => {
                const raw = String(skipFirst).trim();
                const skip = raw === "" ? skipDefault : Number(raw);
                if (!Number.isInteger(skip) || skip < 0 || skip > 100000) {
                  toast("Skip count must be a whole number between 0 and 100000.", "error");
                  return;
                }
                act("Scan started", async () => {
                  await api.post("/admin/api/index-scans/start", {
                    links,
                    channels: picked,
                    mode: "index",
                    skip_first: skip,
                  });
                  setLinks("");
                  setPicked([]);
                });
              }}
            >
              <FiPlay size={14} /> Start indexing
            </Button>
            <span className="text-[11px] text-bone/55">
              Scans beyond the cap wait for a free slot.
            </span>
          </div>
        </Panel>

        <Panel title="Concurrency" subtitle="How many channels may be scanned at once">
          <div className="space-y-3">
            <div className="flex items-center justify-between gap-3">
              <div>
                <p className="text-sm text-bone">Maximum concurrent scans</p>
                <p className="timecode text-[10px] text-bone/60 mt-0.5">
                  All scans share one read budget, so raising this does not raise
                  the total Telegram read rate.
                </p>
              </div>
              <Badge tone="good">cap {data.cap}</Badge>
            </div>
            <p className="text-[11px] text-bone/55">
              Change it on the Runtime settings page — the value is live and takes
              effect on the next launch.
            </p>
          </div>
        </Panel>
      </div>

      {waiting.length > 0 && (
        <Panel title="Waiting for a slot" subtitle="Confirmed but not started yet">
          <ul className="space-y-1.5">
            {waiting.map((row) => (
              <li
                key={row.channel_id}
                className="flex items-center gap-3 rounded-md border border-bone/8 bg-ink/40 px-3.5 py-2.5"
              >
                <span className="timecode text-[11px] text-bone/60 w-32 shrink-0 truncate">
                  {row.channel_id}
                </span>
                <span className="text-sm text-bone/70 truncate flex-1">{row.title || "—"}</span>
                <Badge tone="warn">waiting</Badge>
              </li>
            ))}
          </ul>
        </Panel>
      )}

      <Panel title="Scans" subtitle="One durable state per channel">
        {scans.length === 0 ? (
          <EmptyState title="No scan has run yet">
            Send a t.me post link in DM, or start one from above.
          </EmptyState>
        ) : (
          <div className="overflow-x-auto -mx-1 px-1">
            <table className="w-full text-sm min-w-[840px]">
              <thead>
                <tr className="text-left">
                  {["Channel", "Status", "Checked", "Skipped", "Queued", "Existing", "Errors", "Cursor", "Elapsed", ""].map(
                    (h) => (
                      <th
                        key={h}
                        className="timecode text-[10px] uppercase tracking-[0.14em] text-bone/60 pb-2 pr-3 font-normal"
                      >
                        {h}
                      </th>
                    )
                  )}
                </tr>
              </thead>
              <tbody>
                {scans.map((scan) => {
                  const cursor = scan.next_offset_id;
                  return (
                    <tr key={scan.channel_id} className="border-t border-bone/6">
                      <td className="py-2.5 pr-3">
                        <p className="timecode text-[11px] text-bone/75">{scan.channel_id}</p>
                        <p className="text-[11px] text-bone/60 truncate max-w-[180px]">
                          {scan.title || "—"}
                        </p>
                      </td>
                      <td className="py-2.5 pr-3">
                        <Badge tone={scanTone(scan.status)}>{scan.status}</Badge>
                        {scan.mode === "audit" ? (
                          <Badge className="ml-1">audit</Badge>
                        ) : null}
                      </td>
                      <td className="py-2.5 pr-3 timecode text-[11px] text-bone/60 tabular-nums">
                        {scan.checked ?? 0}
                      </td>
                      <td
                        className="py-2.5 pr-3 timecode text-[11px] text-bone/60 tabular-nums"
                        title={`Requested skip: ${scan.skip_first ?? 0}`}
                      >
                        {scan.skipped ?? 0}
                        {scan.skip_first ? (
                          <span className="text-bone/55"> / {scan.skip_first}</span>
                        ) : null}
                      </td>
                      <td className="py-2.5 pr-3 timecode text-[11px] text-bone/60 tabular-nums">
                        {scan.queued ?? 0}
                      </td>
                      <td className="py-2.5 pr-3 timecode text-[11px] text-bone/60 tabular-nums">
                        {scan.existing ?? 0}
                      </td>
                      <td className="py-2.5 pr-3 timecode text-[11px] text-bone/60 tabular-nums">
                        {scan.errors ?? 0}
                      </td>
                      <td className="py-2.5 pr-3 timecode text-[11px] text-bone/50 tabular-nums">
                        {cursor ? `#${cursor}` : "—"}
                      </td>
                      <td className="py-2.5 pr-3 timecode text-[11px] text-bone/50 tabular-nums">
                        {formatEta(scan.elapsed_seconds)}
                      </td>
                      <td className="py-2.5 text-right">
                        <Button
                          variant="ghost"
                          disabled={
                            busy
                            || !(running.includes(scan.channel_id)
                              || scan.status === "waiting")
                          }
                          onClick={() =>
                            act(
                              "Scan stopping",
                              () =>
                                api.post("/admin/api/index-scans/stop", {
                                  channel_id: scan.channel_id,
                                })
                            )
                          }
                        >
                          <FiSquare size={13} /> Stop
                        </Button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </Panel>
    </div>
  );
}

import React, { useEffect, useRef, useState } from "react";
import { FiEye, FiEyeOff, FiLock, FiArrowRight, FiSettings, FiCheck } from "react-icons/fi";
import { login, getAdminBase, setAdminBase, clearAdminBase, getSavedAdminBase } from "./api";
import { SITENAME } from "../config";
import { Button, Label, Spinner, TextInput } from "./ui";

export default function LoginPage({ onSuccess }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [showConn, setShowConn] = useState(
    () => typeof window !== "undefined" && new URLSearchParams(window.location.search).has("conn")
  );
  const [apiUrl, setApiUrl] = useState(() => getSavedAdminBase() || getAdminBase());
  const [connSaved, setConnSaved] = useState(false);
  const userRef = useRef(null);

  useEffect(() => {
    userRef.current?.focus();
  }, []);

  const saveConn = () => {
    const base = setAdminBase(apiUrl);
    setApiUrl(base || getAdminBase());
    setConnSaved(true);
    window.setTimeout(() => setConnSaved(false), 1800);
  };

  const resetConn = () => {
    clearAdminBase();
    setApiUrl(getAdminBase());
    setConnSaved(true);
    window.setTimeout(() => setConnSaved(false), 1800);
  };

  const submit = async (e) => {
    e.preventDefault();
    if (busy) return;
    if (!username || !password) {
      setError("Enter your username and password.");
      return;
    }
    setBusy(true);
    setError("");
    try {
      await login(username, password);
      onSuccess();
    } catch (err) {
      setError(
        err.status === 429
          ? "Too many attempts — wait a few minutes and try again."
          : err.status === 401
            ? "Invalid username or password."
            : err.message
      );
      // A connection failure usually means the API URL is wrong.
      if (err.status === 0) setShowConn(true);
      setPassword("");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="min-h-screen bg-ink text-bone relative overflow-hidden flex items-center justify-center px-4 py-10">
      {/* projector beam + stage glow */}
      <div
        aria-hidden="true"
        className="absolute inset-0 pointer-events-none"
        style={{
          background:
            "radial-gradient(1100px 480px at 50% -8%, rgba(233,184,114,0.13), transparent 62%)," +
            "radial-gradient(700px 420px at 85% 100%, rgba(255,90,60,0.06), transparent 60%)," +
            "linear-gradient(180deg, #0a0b0e 0%, #08090b 55%, #060709 100%)",
        }}
      />
      {/* faint film grain dots */}
      <div
        aria-hidden="true"
        className="absolute inset-0 pointer-events-none opacity-[0.05]"
        style={{
          backgroundImage: "radial-gradient(rgba(242,237,227,0.6) 0.6px, transparent 0.6px)",
          backgroundSize: "22px 22px",
        }}
      />

      <main className="relative w-full max-w-[400px]">
        <header className="text-center mb-8">
          <p className="timecode text-[10px] uppercase tracking-[0.34em] text-projector/80 mb-3">
            Reel Control Room
          </p>
          <h1 className="font-display text-4xl font-medium leading-tight">{SITENAME}</h1>
          <p className="text-sm text-bone/50 mt-2">Admin console — staff only.</p>
        </header>

        <form
          onSubmit={submit}
          className="glass rounded-xl p-6 sm:p-7 shadow-[0_40px_90px_-40px_rgba(0,0,0,0.95)]"
        >
          <div className="mb-5">
            <Label htmlFor="admin-user">Username</Label>
            <TextInput
              id="admin-user"
              ref={userRef}
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              autoComplete="username"
              autoCapitalize="none"
              spellCheck={false}
              placeholder="admin"
            />
          </div>

          <div className="mb-6">
            <Label htmlFor="admin-pass">Password</Label>
            <div className="relative">
              <TextInput
                id="admin-pass"
                type={showPass ? "text" : "password"}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                autoComplete="current-password"
                placeholder="••••••••"
                className="pr-11"
              />
              <button
                type="button"
                aria-label={showPass ? "Hide password" : "Show password"}
                onClick={() => setShowPass((v) => !v)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-bone/55 hover:text-bone/80 transition-colors"
              >
                {showPass ? <FiEyeOff size={16} /> : <FiEye size={16} />}
              </button>
            </div>
          </div>

          {error && (
            <p
              role="alert"
              className="mb-5 rounded-md border border-signal/40 bg-signal/8 px-3.5 py-2.5 text-sm text-signal leading-snug"
            >
              {error}
            </p>
          )}

          <Button
            type="submit"
            variant="primary"
            disabled={busy}
            className="w-full !py-3 rounded-md tracking-wide"
          >
            {busy ? (
              <>
                <Spinner className="border-ink/25 border-t-ink" /> Checking reel…
              </>
            ) : (
              <>
                Enter console <FiArrowRight />
              </>
            )}
          </Button>

          <p className="mt-5 flex items-center justify-center gap-1.5 timecode text-[10px] uppercase tracking-[0.14em] text-bone/55">
            <FiLock size={11} /> Session stays in this tab only
          </p>
        </form>

        <div className="mt-4 text-center">
          <button
            type="button"
            onClick={() => setShowConn((v) => !v)}
            className="inline-flex items-center gap-1.5 text-[11px] text-bone/60 hover:text-bone/80 transition-colors"
          >
            <FiSettings size={13} /> Backend connection
            {getSavedAdminBase() ? <span className="text-projector">· custom</span> : null}
          </button>
          {showConn ? (
            <div className="mt-3 glass rounded-xl p-4 text-left">
              <Label htmlFor="admin-api-url">Backend API URL</Label>
              <TextInput
                id="admin-api-url"
                value={apiUrl}
                onChange={(e) => setApiUrl(e.target.value)}
                placeholder="https://api.example.com"
                autoCapitalize="none"
                spellCheck={false}
                className="font-mono text-[12px]"
              />
              <p className="text-[11px] text-bone/55 leading-snug mt-2">
                The console needs the backend origin (not the website). If every
                page is empty or login fails, this URL is usually the cause. It is
                stored only in this browser.
              </p>
              <div className="flex gap-2 mt-3">
                <Button variant="primary" onClick={saveConn} className="flex-1">
                  {connSaved ? <FiCheck size={14} /> : null} {connSaved ? "Saved" : "Save URL"}
                </Button>
                <Button variant="ghost" onClick={resetConn}>
                  Use default
                </Button>
              </div>
            </div>
          ) : null}
        </div>

        <p className="text-center text-[11px] text-bone/50 mt-6">
          Wrong password 8 times in 5 minutes locks the attempt window.
        </p>
      </main>
    </div>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { FiArrowLeft, FiCheck, FiRefreshCw, FiSave, FiTrash2, FiExternalLink, FiShuffle } from "react-icons/fi";
import { api } from "./api";
import {
  Badge,
  Button,
  ConfirmModal,
  EmptyState,
  Field,
  Label,
  Modal,
  Panel,
  Select,
  Spinner,
  TextArea,
  TextInput,
  cx,
  toast,
} from "./ui";

const TABS = [
  { id: "details", label: "Details" },
  { id: "files", label: "Files" },
  { id: "subs", label: "Subtitles" },
  { id: "episodes", label: "Episodes", tvOnly: true },
  { id: "images", label: "Images" },
  { id: "cast", label: "Cast" },
  { id: "danger", label: "Danger zone" },
];

const blankForm = {
  title: "",
  release_year: "",
  rating: "",
  runtime: "",
  rip: "",
  languages: "",
  genres: "",
  description: "",
  poster: "",
  backdrop: "",
  cast: "",
};

const toForm = (m) => ({
  ...blankForm,
  title: m.title || "",
  release_year: m.release_year ?? "",
  rating: m.rating ?? "",
  runtime: m.type === "tv" ? `${m.total_seasons || 0} seasons / ${m.total_episodes || 0} episodes` : m.runtime || "",
  rip: m.rip || "",
  languages: (m.languages || []).join(", "),
  genres: (m.genres || []).join(", "),
  description: m.description || "",
  poster: m.poster || "",
  backdrop: m.backdrop || "",
  cast: (m.cast || [])
    .map((c) =>
      [c.name, c.character || c.role, c.profile_path || c.profile || c.image, c.id]
        .filter((v) => v !== undefined && v !== null)
        .join(" | ")
    )
    .join("\n"),
});

/* Flatten every quality file, tagging series files with their S/E position. */
function flattenQualities(media) {
  if (!media) return [];
  if ((media.type || "movie") !== "tv") return media.telegram || [];
  const out = [];
  (media.seasons || []).forEach((s) =>
    (s.episodes || []).forEach((ep) =>
      (ep.telegram || []).forEach((q) =>
        out.push({ ...q, _season: s.season_number, _episode: ep.episode_number, _episodeTitle: ep.title })
      )
    )
  );
  return out;
}

/* Season 0 is a legitimate season number (TMDB uses it for Specials), so every
 * test here has to be `!= null` rather than truthiness — the old `_season ?`
 * form dropped season/episode context for Specials, which made edits and
 * deletes target the wrong document. */
const hasSeason = (q) => q != null && q._season != null && q._season !== "";
const epParams = (q) =>
  hasSeason(q) ? { season_number: q._season, episode_number: q._episode } : {};

export default function MediaEditorPage() {
  const { type, dbIndex, tmdbId } = useParams();
  const navigate = useNavigate();
  const base = `/admin/api/media/${type}/${dbIndex}/${tmdbId}`;
  const [media, setMedia] = useState(null);
  const [form, setForm] = useState(blankForm);
  const [tab, setTab] = useState("details");
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [modal, setModal] = useState(null);
  const [draft, setDraft] = useState(null);
  const [deleteWord, setDeleteWord] = useState("");
  const [moveDraft, setMoveDraft] = useState(null);

  const qualities = useMemo(() => flattenQualities(media), [media]);
  const isTv = media?.type === "tv";

  const load = async (showSpinner = true) => {
    if (showSpinner) setLoading(true);
    try {
      const m = await api.get(base);
      setMedia(m);
      setForm(toForm(m));
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
    setDeleteWord("");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [base]);

  const set = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.value }));

  const withBusy = (fn) => async (...args) => {
    setBusy(true);
    try {
      await fn(...args);
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setBusy(false);
    }
  };

  const saveDetails = withBusy(async () => {
    const payload = {
      title: form.title,
      release_year: form.release_year,
      rating: form.rating,
      rip: form.rip,
      languages: form.languages,
      genres: form.genres,
      description: form.description,
      cast: form.cast,
    };
    if (isTv) {
      payload.poster = form.poster;
      payload.backdrop = form.backdrop;
    } else {
      payload.runtime = form.runtime;
    }
    const d = await api.patch(base, payload);
    setMedia(d.media);
    setForm(toForm(d.media));
    toast("Details saved");
  });

  const saveImages = withBusy(async () => {
    const d = await api.patch(base, { poster: form.poster, backdrop: form.backdrop });
    setMedia(d.media);
    toast("Images saved");
  });

  const refreshTmdb = withBusy(async (overwrite) => {
    const d = await api.post(`${base}/refresh-metadata`, { overwrite });
    const updated = d.media || d;
    setMedia(updated);
    setForm(toForm(updated));
    toast(
      d.updated_fields && d.updated_fields.length
        ? `TMDB refreshed ${d.updated_fields.length} field(s)`
        : "Nothing to update from TMDB"
    );
  });

  const saveFile = withBusy(async () => {
    await api.patch(`${base}/files/${encodeURIComponent(draft.id)}`, 
      { quality: draft.quality, size: draft.size, name: draft.name },
      epParams(draft)
    );
    setModal(null);
    await load(false);
    toast("File updated");
  });

  const deleteFile = withBusy(async (telegramToo) => {
    const res = await api.delete(`${base}/files/${encodeURIComponent(draft.id)}`, {
      ...epParams(draft),
      ...(telegramToo ? { delete_telegram: "true" } : {}),
    });
    setModal(null);
    await load(false);
    toast(telegramToo ? `File deleted • Telegram ${res.telegram_deleted || 0}/${res.telegram_total || 0}` : "File removed from DB only");
  });

  const moveFile = withBusy(async () => {
    if (!moveDraft?.media_ref?.trim()) {
      toast("Paste the correct TMDB/IMDb reference first", "error");
      return;
    }
    const source = { db_index: dbIndex, tmdb_id: tmdbId };
    if (type === "movie" || type === "tv") source.collection = type;
    if (draft._season != null) {
      source.season_number = draft._season;
      source.episode_number = draft._episode;
    }
    const res = await api.post("/admin/api/files/reassign", {
      file_id: draft.id,
      media_ref: moveDraft.media_ref.trim(),
      kind: moveDraft.kind || null,
      quality: moveDraft.quality.trim() || null,
      season: moveDraft.season === "" ? null : Number(moveDraft.season),
      episode: moveDraft.episode === "" ? null : Number(moveDraft.episode),
      replace_existing_quality: Boolean(moveDraft.replace_existing_quality),
      remove_empty_title: Boolean(moveDraft.remove_empty_title),
      source,
    });
    setModal(null);
    setMoveDraft(null);
    toast(res.moved ? `Moved to ${res.title}` : res.warning || "Move incomplete",
      res.moved ? "success" : "error");
    if (res.old_title_removed) {
      navigate("/admin/media");
    } else {
      await load(false);
    }
  });

  const openMove = (q) => {
    setDraft(q);
    setMoveDraft({
      media_ref: "",
      kind: "",
      quality: "",
      season: q._season ?? "",
      episode: q._episode ?? "",
      replace_existing_quality: false,
      remove_empty_title: true,
    });
    setModal("moveFile");
  };

  const setMove = (key) => (e) => {
    const value = e.target.type === "checkbox" ? e.target.checked : e.target.value;
    setMoveDraft((d) => ({ ...d, [key]: value }));
  };

  const saveSub = withBusy(async () => {
    await api.patch(
      `${base}/subtitles/${encodeURIComponent(draft.sub.id)}`,
      { language: draft.language, format: draft.format, name: draft.name },
      { file_id: draft.fileId, ...epParams(draft) }
    );
    setModal(null);
    await load(false);
    toast("Subtitle updated");
  });

  const deleteSub = withBusy(async (telegramToo) => {
    const res = await api.delete(`${base}/subtitles/${encodeURIComponent(draft.sub.id)}`, {
      file_id: draft.fileId,
      ...epParams(draft),
      ...(telegramToo ? { delete_telegram: "true" } : {}),
    });
    setModal(null);
    await load(false);
    toast(telegramToo ? `Subtitle deleted • Telegram ${res.telegram_deleted || 0}/${res.telegram_total || 0}` : "Subtitle removed from DB only");
  });

  const addSub = withBusy(async () => {
    const payload = {
      id: draft.id,
      name: draft.name,
      language: draft.language,
      format: draft.format,
    };
    if (isTv && draft.target === "all") {
      await api.post(`${base}/episodes/subtitles`, { ...payload, season_number: "all" });
    } else {
      const q = qualities.find((x) => (x.id || "") === draft.target);
      payload.target_file_id = draft.target;
      if (hasSeason(q)) {
        payload.season_number = q._season;
        payload.episode_number = q._episode;
      }
      await api.post(`${base}/subtitles`, payload);
    }
    setModal(null);
    await load(false);
    toast("Subtitle attached");
  });

  const saveEpisode = withBusy(async () => {
    await api.patch(`${base}/episodes/${draft.season_number}/${draft.episode_number}`, {
      title: draft.title,
      episode_backdrop: draft.episode_backdrop,
    });
    setModal(null);
    await load(false);
    toast("Episode updated");
  });

  const addEpisode = withBusy(async () => {
    await api.post(`${base}/episodes`, {
      season_number: draft.season_number,
      episode_number: draft.episode_number,
      title: draft.title,
    });
    setModal(null);
    await load(false);
    toast("Episode added");
  });

  const deleteEpisode = withBusy(async (telegramToo) => {
    const res = await api.delete(`${base}/episodes/${draft.season_number}/${draft.episode_number}`, {
      ...(telegramToo ? { delete_telegram: "true" } : {}),
    });
    setModal(null);
    await load(false);
    toast(
      telegramToo
        ? `Episode deleted • Telegram ${res.telegram_deleted || 0}/${res.telegram_total || 0}`
        : "Episode removed from DB only"
    );
  });

  const deleteSeason = withBusy(async (telegramToo) => {
    const res = await api.delete(`${base}/seasons/${draft.season_number}`, {
      ...(telegramToo ? { delete_telegram: "true" } : {}),
    });
    setModal(null);
    await load(false);
    toast(
      telegramToo
        ? `Season deleted • ${res.episodes || 0} episodes • Telegram ${res.telegram_deleted || 0}/${res.telegram_total || 0}`
        : `Season removed from DB only • ${res.episodes || 0} episodes`
    );
  });

  const deleteMedia = withBusy(async (telegramToo) => {
    const res = await api.delete(base, telegramToo ? { delete_telegram: "true" } : undefined);
    toast(
      telegramToo
        ? `Media deleted • Telegram ${res.telegram_deleted || 0}/${res.telegram_total || 0}`
        : "Media deleted from the database only"
    );
    navigate("/admin/media");
  });

  if (loading)
    return (
      <div className="flex justify-center py-24">
        <Spinner className="w-6 h-6" />
      </div>
    );
  if (!media)
    return (
      <Panel>
        <EmptyState title="Title not found">It may have been deleted from another tab.</EmptyState>
      </Panel>
    );

  const subCount = qualities.reduce((n, q) => n + (q.subtitle_tracks || []).length, 0);
  const epCount = (media.seasons || []).reduce((n, s) => n + (s.episodes || []).length, 0);
  const sitePath = `${isTv ? "ser" : "mov"}/${media.tmdb_id}`;

  return (
    <div className="space-y-5">
      <Link
        to="/admin/media"
        className="inline-flex items-center gap-2 text-sm text-bone/50 hover:text-bone transition-colors"
      >
        <FiArrowLeft size={14} /> Back to library
      </Link>

      {/* Hero */}
      <section className="relative overflow-hidden rounded-lg border border-bone/8">
        <div className="absolute inset-0">
          <img src={form.backdrop || form.poster} alt="" className="w-full h-full object-cover opacity-35" />
          <div className="absolute inset-0 bg-gradient-to-t from-ink via-ink/85 to-ink/40" />
        </div>
        <div className="relative flex flex-col sm:flex-row gap-4 p-4 sm:p-6">
          <img
            src={form.poster || form.backdrop}
            alt=""
            className="w-24 sm:w-28 aspect-[2/3] object-cover rounded-md ring-1 ring-inset ring-bone/15 shrink-0 bg-carbon"
          />
          <div className="min-w-0 flex-1">
            <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">
              Editing · {media.type}
            </p>
            <h1 className="font-display text-2xl sm:text-3xl mt-1.5 leading-tight">
              {media.title || "Untitled"}
            </h1>
            <p className="text-sm text-bone/50 mt-1.5 line-clamp-2 max-w-2xl">{media.description}</p>
            <div className="flex flex-wrap items-center gap-2 mt-3.5">
              <Badge tone="neutral">{media.file_count || qualities.length} files</Badge>
              <Badge tone="neutral">{subCount} subs</Badge>
              {isTv && <Badge tone="neutral">{epCount} episodes</Badge>}
              <Badge>db {media.db_index}</Badge>
              <Badge>tmdb {media.tmdb_id}</Badge>
              <a
                href={`${window.location.origin}/${sitePath}`}
                target="_blank"
                rel="noreferrer"
                className="inline-flex items-center gap-1.5 timecode text-[10px] uppercase tracking-[0.14em] text-bone/50 hover:text-projector transition-colors ml-1"
              >
                <FiExternalLink size={12} /> Live page
              </a>
              {media.telegram_link && (
                <a
                  href={media.telegram_link}
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex items-center gap-1.5 timecode text-[10px] uppercase tracking-[0.14em] text-bone/50 hover:text-projector transition-colors"
                >
                  <FiExternalLink size={12} /> Telegram post
                </a>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* Tabs */}
      <div className="flex gap-1 flex-wrap border-b border-bone/8 pb-px">
        {TABS.filter((t) => !t.tvOnly || isTv).map((t) => (
          <button
            key={t.id}
            type="button"
            onClick={() => setTab(t.id)}
            className={cx(
              "relative px-4 py-2.5 text-sm transition-colors rounded-t-md",
              tab === t.id
                ? "text-bone font-semibold"
                : "text-bone/50 hover:text-bone/80",
              t.id === "danger" && tab !== t.id && "text-signal/60 hover:text-signal"
            )}
          >
            {t.label}
            {tab === t.id && (
              <span className="absolute left-2 right-2 -bottom-px h-[2px] rounded-full bg-projector" />
            )}
          </button>
        ))}
      </div>

      {tab === "details" && (
        <Panel
          title="Details"
          subtitle="Saved straight to MongoDB"
          actions={
            <>
              <Button variant="ghost" disabled={busy} onClick={() => refreshTmdb(false)}>
                <FiRefreshCw size={14} /> Pull from TMDB
              </Button>
              <Button variant="ghost" disabled={busy} onClick={() => refreshTmdb(true)}>
                Overwrite with TMDB
              </Button>
              <Button variant="primary" disabled={busy} onClick={saveDetails}>
                {busy ? <Spinner /> : <FiSave size={14} />} Save details
              </Button>
            </>
          }
        >
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="sm:col-span-2">
              <Label htmlFor="ed-title">Title</Label>
              <TextInput id="ed-title" value={form.title} onChange={set("title")} />
            </div>
            <Field label="Release year">
              <TextInput type="number" value={form.release_year} onChange={set("release_year")} />
            </Field>
            <Field label="Rating">
              <TextInput value={form.rating} onChange={set("rating")} placeholder="7.8" />
            </Field>
            <Field
              label={isTv ? "Seasons / episodes" : "Runtime"}
              hint={isTv ? "Read-only — recalculated when you edit episodes." : undefined}
            >
              <TextInput value={form.runtime} onChange={set("runtime")} readOnly={isTv} className={isTv ? "opacity-60" : ""} />
            </Field>
            <Field label="Rip tag">
              <TextInput value={form.rip} onChange={set("rip")} placeholder="WEB-DL • x264" />
            </Field>
            <Field label="Languages" hint="Comma separated">
              <TextInput value={form.languages} onChange={set("languages")} placeholder="Tamil, Telugu, Hindi" />
            </Field>
            <Field label="Genres" hint="Comma separated">
              <TextInput value={form.genres} onChange={set("genres")} placeholder="Action, Drama" />
            </Field>
            <div className="sm:col-span-2">
              <Label htmlFor="ed-desc">Description</Label>
              <TextArea id="ed-desc" value={form.description} onChange={set("description")} rows={5} />
            </div>
          </div>
        </Panel>
      )}

      {tab === "files" && (
        <Panel title="Video files" subtitle={`${qualities.length} qualities stored in Telegram`}>
          {qualities.length === 0 ? (
            <EmptyState title="No video files yet">
              Uploads still go through the Telegram bot — this list shows what was indexed.
            </EmptyState>
          ) : (
            <ul className="space-y-2">
              {qualities.map((q, i) => (
                <li
                  key={q.id || i}
                  className="flex items-center gap-3 rounded-md border border-bone/8 bg-ink/40 px-3.5 py-3 hover:border-bone/18 transition-colors"
                >
                  <span className="w-8 h-8 rounded-md bg-bone/5 flex items-center justify-center text-bone/50 shrink-0">
                    🎞
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium text-bone truncate">{q.name || "Untitled file"}</p>
                    <p className="timecode text-[10px] text-bone/60 mt-0.5 uppercase tracking-wider">
                      {q.quality || "—"} • {q.size || "?"}
                      {q.abyss ? " • abyss" : ""}
                      {q._season ? ` • S${q._season}E${q._episode}` : ""} • {(q.subtitle_tracks || []).length} subs
                    </p>
                  </div>
                  <Button
                    variant="ghost"
                    disabled={busy}
                    onClick={() => {
                      setDraft(q);
                      setModal("editFile");
                    }}
                  >
                    Edit
                  </Button>
                  <Button
                    variant="ghost"
                    disabled={busy}
                    title="Move this file to the correct title / episode"
                    onClick={() => openMove(q)}
                  >
                    <FiShuffle size={14} /> Move
                  </Button>
                  <Button
                    variant="danger"
                    disabled={busy}
                    onClick={() => {
                      setDraft(q);
                      setModal("deleteFile");
                    }}
                  >
                    <FiTrash2 size={14} />
                  </Button>
                </li>
              ))}
            </ul>
          )}
        </Panel>
      )}

      {tab === "subs" && (
        <Panel
          title="Subtitles"
          subtitle={`${subCount} tracks across all qualities`}
          actions={
            <Button
              variant="primary"
              disabled={busy || qualities.length === 0}
              onClick={() => {
                setDraft({ target: "all", id: "", name: "", language: "Tamil", format: "srt" });
                setModal("addSub");
              }}
            >
              Attach subtitle
            </Button>
          }
        >
          {subCount === 0 ? (
            <EmptyState title="No subtitles attached">Use “Attach subtitle” with a Telegram file id.</EmptyState>
          ) : (
            <ul className="space-y-2">
              {qualities.flatMap((q) =>
                (q.subtitle_tracks || []).map((s, i) => (
                  <li
                    key={`${q.id}-${s.id}-${i}`}
                    className="flex items-center gap-3 rounded-md border border-bone/8 bg-ink/40 px-3.5 py-3 hover:border-bone/18 transition-colors"
                  >
                    <span className="w-8 h-8 rounded-md bg-bone/5 flex items-center justify-center text-bone/50 shrink-0">
                      💬
                    </span>
                    <div className="min-w-0 flex-1">
                      <p className="text-sm font-medium text-bone truncate">{s.name || s.label || "Subtitle"}</p>
                      <p className="timecode text-[10px] text-bone/60 mt-0.5 uppercase tracking-wider">
                        {s.language || "Unknown"} • {(s.format || "srt").toUpperCase()} • on {q.quality || "file"}
                        {q._season ? ` S${q._season}E${q._episode}` : ""}
                      </p>
                    </div>
                    <Button
                      variant="ghost"
                      disabled={busy}
                      onClick={() => {
                        setDraft({ ...q, sub: s, fileId: q.id, language: s.language, format: s.format, name: s.name });
                        setModal("editSub");
                      }}
                    >
                      Edit
                    </Button>
                    <Button
                      variant="danger"
                      disabled={busy}
                      onClick={() => {
                        setDraft({ ...q, sub: s, fileId: q.id });
                        setModal("deleteSub");
                      }}
                    >
                      <FiTrash2 size={14} />
                    </Button>
                  </li>
                ))
              )}
            </ul>
          )}
        </Panel>
      )}

      {tab === "episodes" && isTv && (
        <Panel
          title="Episodes"
          subtitle={`${(media.seasons || []).length} seasons • ${epCount} episodes`}
          actions={
            <Button
              variant="primary"
              disabled={busy}
              onClick={() => {
                setDraft({ season_number: 1, episode_number: 1, title: "" });
                setModal("addEpisode");
              }}
            >
              Add episode
            </Button>
          }
        >
          {(media.seasons || []).length === 0 ? (
            <EmptyState title="No seasons yet">Add the first episode to create season 1.</EmptyState>
          ) : (
            <div className="space-y-5">
              {(media.seasons || []).map((s) => (
                <div key={s.season_number}>
                  <div className="flex items-center gap-2 mb-2">
                    <h3 className="section-title text-base text-bone">Season {s.season_number}</h3>
                    <span className="timecode text-[10px] text-bone/55 uppercase tracking-[0.14em]">
                      {(s.episodes || []).length} eps
                    </span>
                    <Button
                      variant="danger"
                      className="ml-auto"
                      disabled={busy}
                      onClick={() => {
                        setDraft({
                          season_number: s.season_number,
                          episodes: (s.episodes || []).length,
                        });
                        setModal("deleteSeason");
                      }}
                    >
                      <FiTrash2 size={14} /> Delete season
                    </Button>
                  </div>
                  <ul className="space-y-1.5">
                    {(s.episodes || []).map((ep) => (
                      <li
                        key={ep.episode_number}
                        className="flex items-center gap-3 rounded-md border border-bone/8 bg-ink/40 px-3.5 py-2.5"
                      >
                        <span className="timecode text-[11px] text-projector/80 shrink-0">
                          E{String(ep.episode_number).padStart(2, "0")}
                        </span>
                        <div className="min-w-0 flex-1">
                          <p className="text-sm text-bone truncate">{ep.title || "Untitled episode"}</p>
                          <p className="timecode text-[10px] text-bone/55 mt-0.5">
                            {(ep.telegram || []).length} files •{" "}
                            {(ep.telegram || []).reduce((n, q) => n + (q.subtitle_tracks || []).length, 0)} subs
                          </p>
                        </div>
                        <Button
                          variant="ghost"
                          disabled={busy}
                          onClick={() => {
                            setDraft({
                              season_number: s.season_number,
                              episode_number: ep.episode_number,
                              title: ep.title || "",
                              episode_backdrop: ep.episode_backdrop || "",
                            });
                            setModal("editEpisode");
                          }}
                        >
                          Edit
                        </Button>
                        <Button
                          variant="danger"
                          disabled={busy}
                          onClick={() => {
                            setDraft({ season_number: s.season_number, episode_number: ep.episode_number, title: ep.title });
                            setModal("deleteEpisode");
                          }}
                        >
                          <FiTrash2 size={14} />
                        </Button>
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </div>
          )}
        </Panel>
      )}

      {tab === "images" && (
        <Panel
          title="Images"
          actions={
            <Button variant="primary" disabled={busy} onClick={saveImages}>
              <FiSave size={14} /> Save images
            </Button>
          }
        >
          <div className="grid gap-4 sm:grid-cols-2">
            <div>
              <Label htmlFor="ed-poster">Poster URL</Label>
              <TextInput id="ed-poster" value={form.poster} onChange={set("poster")} />
              <img
                src={form.poster}
                alt="Poster preview"
                className="mt-3 w-28 aspect-[2/3] object-cover rounded-md ring-1 ring-inset ring-bone/12 bg-carbon"
              />
            </div>
            <div>
              <Label htmlFor="ed-backdrop">Backdrop URL</Label>
              <TextInput id="ed-backdrop" value={form.backdrop} onChange={set("backdrop")} />
              <img
                src={form.backdrop}
                alt="Backdrop preview"
                className="mt-3 w-full aspect-video object-cover rounded-md ring-1 ring-inset ring-bone/12 bg-carbon"
              />
            </div>
          </div>
        </Panel>
      )}

      {tab === "cast" && (
        <Panel
          title="Cast"
          subtitle="One per line — Name | Role | Image URL | TMDB id"
          actions={
            <Button variant="primary" disabled={busy} onClick={saveDetails}>
              <FiSave size={14} /> Save cast
            </Button>
          }
        >
          <TextArea value={form.cast} onChange={set("cast")} rows={14} className="font-mono text-[13px]" />
        </Panel>
      )}

      {tab === "danger" && (
        <Panel title="Danger zone" subtitle="Irreversible — Telegram deletion is permanent">
          <div className="rounded-lg border border-signal/30 bg-signal/6 p-4 sm:p-5 space-y-4">
            <p className="text-sm text-bone/70 leading-relaxed">
              Deleting removes <strong className="text-bone">{media.title}</strong> from the catalogue.{" "}
              <span className="text-bone/50">DB only</span> leaves the files on your Telegram channel;{" "}
              <span className="text-bone/50">Telegram + DB</span> also deletes every video message and its
              subtitles.
            </p>
            <div className="max-w-xs">
              <Label htmlFor="danger-word">Type DELETE to confirm</Label>
              <TextInput
                id="danger-word"
                value={deleteWord}
                onChange={(e) => setDeleteWord(e.target.value)}
                placeholder="DELETE"
                autoComplete="off"
              />
            </div>
            <div className="flex flex-wrap gap-2">
              <Button
                variant="danger"
                disabled={busy || deleteWord.trim().toUpperCase() !== "DELETE"}
                onClick={() => {
                  setDraft({ telegram: false });
                  setModal("deleteMedia");
                }}
              >
                <FiCheck size={14} /> Delete from DB only
              </Button>
              <Button
                variant="danger"
                disabled={busy || deleteWord.trim().toUpperCase() !== "DELETE"}
                onClick={() => {
                  setDraft({ telegram: true });
                  setModal("deleteMedia");
                }}
              >
                <FiTrash2 size={14} /> Delete Telegram + DB
              </Button>
            </div>
          </div>
        </Panel>
      )}

      {/* ── Modals ── */}
      <Modal open={modal === "editFile"} onClose={() => setModal(null)} title="Edit video file">
        {draft && (
          <div className="space-y-4">
            <p className="timecode text-[10px] text-bone/60 break-all">{draft.id}</p>
            <div className="grid sm:grid-cols-2 gap-4">
              <Field label="Quality">
                <TextInput
                  value={draft.quality || ""}
                  onChange={(e) => setDraft({ ...draft, quality: e.target.value })}
                />
              </Field>
              <Field label="Size">
                <TextInput value={draft.size || ""} onChange={(e) => setDraft({ ...draft, size: e.target.value })} />
              </Field>
            </div>
            <Field label="File name">
              <TextArea value={draft.name || ""} onChange={(e) => setDraft({ ...draft, name: e.target.value })} />
            </Field>
            <div className="flex justify-end gap-2">
              <Button variant="ghost" onClick={() => setModal(null)}>
                Cancel
              </Button>
              <Button variant="primary" disabled={busy} onClick={saveFile}>
                <FiSave size={14} /> Save file
              </Button>
            </div>
          </div>
        )}
      </Modal>

      <Modal open={modal === "deleteFile"} onClose={() => setModal(null)} title="Delete video file">
        {draft && (
          <div className="space-y-4">
            <p className="timecode text-[11px] text-bone/60 break-all">{draft.name}</p>
            <p className="text-sm text-bone/50 leading-relaxed">
              DB only keeps the Telegram channel post. Telegram + DB deletes the video message and its linked
              subtitle messages, then removes the quality from the document.
            </p>
            <div className="flex justify-end gap-2">
              <Button variant="ghost" onClick={() => setModal(null)}>
                Cancel
              </Button>
              <Button variant="danger" disabled={busy} onClick={() => deleteFile(false)}>
                DB only
              </Button>
              <Button variant="danger" disabled={busy} onClick={() => deleteFile(true)}>
                Telegram + DB
              </Button>
            </div>
          </div>
        )}
      </Modal>

      <Modal open={modal === "moveFile"} onClose={() => setModal(null)} title="Move file to another title">
        {draft && moveDraft && (
          <div className="space-y-4">
            <p className="text-[11px] text-bone/50 leading-relaxed break-all">
              Moving <span className="text-bone/80">{draft.name}</span> ({draft.quality || "—"}).
              The Telegram post and the stream link are untouched; only the library entry moves.
            </p>
            <Field
              label="Correct TMDB / IMDb reference"
              hint="tt0133093, an IMDb link, a TMDB id, or a themoviedb.org/movie|tv link"
            >
              <TextInput
                value={moveDraft.media_ref}
                onChange={setMove("media_ref")}
                placeholder="603 · imdb.com/title/tt0133093 · themoviedb.org/tv/1396"
                autoCapitalize="none"
                spellCheck={false}
                className="font-mono text-[12px]"
              />
            </Field>
            <div className="grid sm:grid-cols-2 gap-3">
              <Field label="Kind">
                <Select value={moveDraft.kind} onChange={setMove("kind")}>
                  <option value="">Auto</option>
                  <option value="movie">Movie</option>
                  <option value="tv">Series</option>
                </Select>
              </Field>
              <Field label="Quality (optional — blank keeps it)">
                <TextInput
                  value={moveDraft.quality}
                  onChange={setMove("quality")}
                  placeholder={draft.quality || "keep"}
                />
              </Field>
            </div>
            <div className="grid sm:grid-cols-2 gap-3">
              <Field label="Season (TV)">
                <TextInput
                  type="number"
                  min="1"
                  value={moveDraft.season}
                  onChange={setMove("season")}
                  placeholder="1"
                />
              </Field>
              <Field label="Episode (TV)">
                <TextInput
                  type="number"
                  min="1"
                  value={moveDraft.episode}
                  onChange={setMove("episode")}
                  placeholder="1"
                />
              </Field>
            </div>
            <div className="space-y-2">
              <label className="flex items-start gap-2.5 text-[12px] text-bone/65 cursor-pointer">
                <input
                  type="checkbox"
                  className="mt-0.5 accent-[#e9b872]"
                  checked={moveDraft.replace_existing_quality}
                  onChange={setMove("replace_existing_quality")}
                />
                <span>Replace a same-quality file already on the target</span>
              </label>
              <label className="flex items-start gap-2.5 text-[12px] text-bone/65 cursor-pointer">
                <input
                  type="checkbox"
                  className="mt-0.5 accent-[#e9b872]"
                  checked={moveDraft.remove_empty_title}
                  onChange={setMove("remove_empty_title")}
                />
                <span>Delete this title if it has no files left</span>
              </label>
            </div>
            <div className="flex justify-end gap-2 pt-1">
              <Button variant="ghost" onClick={() => setModal(null)}>Cancel</Button>
              <Button variant="primary" disabled={busy} onClick={moveFile}>
                <FiShuffle size={14} /> Move file
              </Button>
            </div>
          </div>
        )}
      </Modal>

      <Modal open={modal === "addSub"} onClose={() => setModal(null)} title="Attach subtitle">
        {draft && (
          <div className="space-y-4">
            <Field label="Target file">
              <Select value={draft.target} onChange={(e) => setDraft({ ...draft, target: e.target.value })}>
                <option value="all">All qualities{isTv ? " (all episodes)" : ""}</option>
                {qualities.map((q, i) => (
                  <option key={q.id || i} value={q.id}>
                    {q.quality} • {String(q.name || "").slice(0, 40)}
                    {q._season ? ` (S${q._season}E${q._episode})` : ""}
                  </option>
                ))}
              </Select>
            </Field>
            <Field label="Encoded subtitle id" hint="Telegram file id as stored by the bot.">
              <TextInput
                value={draft.id}
                onChange={(e) => setDraft({ ...draft, id: e.target.value })}
                placeholder="AgADBa4x…"
              />
            </Field>
            <Field label="File name">
              <TextInput
                value={draft.name}
                onChange={(e) => setDraft({ ...draft, name: e.target.value })}
                placeholder="movie_tamil.srt"
              />
            </Field>
            <div className="grid sm:grid-cols-2 gap-4">
              <Field label="Language">
                <TextInput value={draft.language} onChange={(e) => setDraft({ ...draft, language: e.target.value })} />
              </Field>
              <Field label="Format">
                <TextInput value={draft.format} onChange={(e) => setDraft({ ...draft, format: e.target.value })} />
              </Field>
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="ghost" onClick={() => setModal(null)}>
                Cancel
              </Button>
              <Button variant="primary" disabled={busy || !draft.id} onClick={addSub}>
                <FiCheck size={14} /> Attach
              </Button>
            </div>
          </div>
        )}
      </Modal>

      <Modal open={modal === "editSub"} onClose={() => setModal(null)} title="Edit subtitle">
        {draft && (
          <div className="space-y-4">
            <p className="timecode text-[10px] text-bone/60 break-all">{draft.sub?.id}</p>
            <div className="grid sm:grid-cols-2 gap-4">
              <Field label="Language">
                <TextInput value={draft.language || ""} onChange={(e) => setDraft({ ...draft, language: e.target.value })} />
              </Field>
              <Field label="Format">
                <TextInput value={draft.format || ""} onChange={(e) => setDraft({ ...draft, format: e.target.value })} />
              </Field>
            </div>
            <Field label="File name">
              <TextArea value={draft.name || ""} onChange={(e) => setDraft({ ...draft, name: e.target.value })} />
            </Field>
            <div className="flex justify-end gap-2">
              <Button variant="ghost" onClick={() => setModal(null)}>
                Cancel
              </Button>
              <Button variant="primary" disabled={busy} onClick={saveSub}>
                <FiSave size={14} /> Save subtitle
              </Button>
            </div>
          </div>
        )}
      </Modal>

      <Modal open={modal === "deleteSub"} onClose={() => setModal(null)} title="Delete subtitle">
        {draft && (
          <div className="space-y-4">
            <p className="timecode text-[11px] text-bone/60 break-all">{draft.sub?.name}</p>
            <p className="text-sm text-bone/50 leading-relaxed">
              DB only unlinks the track. Telegram + DB also deletes the original subtitle message from the channel.
            </p>
            <div className="flex justify-end gap-2">
              <Button variant="ghost" onClick={() => setModal(null)}>
                Cancel
              </Button>
              <Button variant="danger" disabled={busy} onClick={() => deleteSub(false)}>
                DB only
              </Button>
              <Button variant="danger" disabled={busy} onClick={() => deleteSub(true)}>
                Telegram + DB
              </Button>
            </div>
          </div>
        )}
      </Modal>

      <Modal open={modal === "addEpisode"} onClose={() => setModal(null)} title="Add episode">
        {draft && (
          <div className="space-y-4">
            <div className="grid sm:grid-cols-2 gap-4">
              <Field label="Season">
                <TextInput
                  type="number"
                  value={draft.season_number}
                  onChange={(e) => setDraft({ ...draft, season_number: e.target.value })}
                />
              </Field>
              <Field label="Episode">
                <TextInput
                  type="number"
                  value={draft.episode_number}
                  onChange={(e) => setDraft({ ...draft, episode_number: e.target.value })}
                />
              </Field>
            </div>
            <Field label="Title" hint="Leave blank to use “Episode N”.">
              <TextInput value={draft.title} onChange={(e) => setDraft({ ...draft, title: e.target.value })} />
            </Field>
            <div className="flex justify-end gap-2">
              <Button variant="ghost" onClick={() => setModal(null)}>
                Cancel
              </Button>
              <Button variant="primary" disabled={busy} onClick={addEpisode}>
                <FiCheck size={14} /> Add episode
              </Button>
            </div>
          </div>
        )}
      </Modal>

      <Modal open={modal === "editEpisode"} onClose={() => setModal(null)} title="Edit episode">
        {draft && (
          <div className="space-y-4">
            <p className="timecode text-[10px] text-bone/60">
              S{draft.season_number} • E{draft.episode_number}
            </p>
            <Field label="Title">
              <TextInput value={draft.title || ""} onChange={(e) => setDraft({ ...draft, title: e.target.value })} />
            </Field>
            <Field label="Episode backdrop URL">
              <TextInput
                value={draft.episode_backdrop || ""}
                onChange={(e) => setDraft({ ...draft, episode_backdrop: e.target.value })}
              />
            </Field>
            <div className="flex justify-end gap-2">
              <Button variant="ghost" onClick={() => setModal(null)}>
                Cancel
              </Button>
              <Button variant="primary" disabled={busy} onClick={saveEpisode}>
                <FiSave size={14} /> Save episode
              </Button>
            </div>
          </div>
        )}
      </Modal>

      <Modal open={modal === "deleteEpisode"} onClose={() => setModal(null)} title="Delete episode">
        {draft && (
          <div className="space-y-4">
            <p className="text-sm text-bone/70">
              S{draft.season_number} • E{draft.episode_number} — {draft.title || "Untitled"}
            </p>
            <p className="text-sm text-bone/50 leading-relaxed">
              The episode is removed and empty seasons are pruned afterwards. DB only leaves its video and
              subtitle messages on the Telegram channel; Telegram + DB deletes them too.
            </p>
            <div className="flex justify-end gap-2">
              <Button variant="ghost" onClick={() => setModal(null)}>
                Cancel
              </Button>
              <Button variant="danger" disabled={busy} onClick={() => deleteEpisode(false)}>
                DB only
              </Button>
              <Button variant="danger" disabled={busy} onClick={() => deleteEpisode(true)}>
                Telegram + DB
              </Button>
            </div>
          </div>
        )}
      </Modal>

      <Modal open={modal === "deleteSeason"} onClose={() => setModal(null)} title="Delete whole season">
        {draft && (
          <div className="space-y-4">
            <p className="text-sm text-bone/70">
              Season {draft.season_number} — {draft.episodes} episode(s)
            </p>
            <p className="text-sm text-bone/50 leading-relaxed">
              Every episode and quality file in this season is removed from the document. DB only keeps the
              Telegram posts (they become orphans and still use cluster quota); Telegram + DB deletes each
              episode&rsquo;s video and subtitle messages first.
            </p>
            <div className="flex justify-end gap-2">
              <Button variant="ghost" onClick={() => setModal(null)}>
                Cancel
              </Button>
              <Button variant="danger" disabled={busy} onClick={() => deleteSeason(false)}>
                DB only
              </Button>
              <Button variant="danger" disabled={busy} onClick={() => deleteSeason(true)}>
                Telegram + DB
              </Button>
            </div>
          </div>
        )}
      </Modal>

      <ConfirmModal
        open={modal === "deleteMedia"}
        onClose={() => setModal(null)}
        busy={busy}
        title={draft?.telegram ? "Delete from Telegram and the database" : "Delete from the database"}
        confirmWord="DELETE"
        confirmLabel={draft?.telegram ? "Delete everything" : "Delete from DB"}
        onConfirm={() => deleteMedia(!!draft?.telegram)}
      />
    </div>
  );
}

import React, { useEffect, useMemo, useRef, useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { FiCheck, FiRefreshCw, FiSearch, FiTrash2, FiX } from "react-icons/fi";
import { api } from "./api";
import {
  Badge,
  Button,
  ConfirmModal,
  EmptyState,
  Label,
  Panel,
  Select,
  TextInput,
  cx,
  toast,
} from "./ui";

const TYPES = [
  { id: "movie", label: "Movies" },
  { id: "tv", label: "Series" },
  { id: "anime", label: "Anime" },
  { id: "all", label: "Everything" },
];

const FLAGS = [
  { id: "", label: "No quality filter" },
  { id: "no_files", label: "Missing video files" },
  { id: "no_subs", label: "Files but no subtitles" },
  { id: "has_subs", label: "Has subtitles" },
  { id: "no_poster", label: "Missing poster" },
  { id: "no_backdrop", label: "Missing backdrop" },
  { id: "no_description", label: "Missing description" },
  { id: "no_genres", label: "Missing genres" },
  { id: "no_cast", label: "Missing cast" },
  { id: "no_episodes", label: "Series with no episodes" },
];

const SORTS = [
  { id: "updated:desc", label: "Recently updated" },
  { id: "year:desc", label: "Newest release year" },
  { id: "rating:desc", label: "Highest rated" },
  { id: "title:asc", label: "Title A–Z" },
  { id: "files:desc", label: "Most files" },
];

const PAGE_SIZE = 24;

export default function MediaLibraryPage() {
  const [params, setParams] = useSearchParams();
  const [rows, setRows] = useState([]);
  const [total, setTotal] = useState(0);
  const [pages, setPages] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selected, setSelected] = useState(() => new Set());
  const [confirm, setConfirm] = useState(null);
  const [bulkBusy, setBulkBusy] = useState(false);
  const [nonce, setNonce] = useState(0);
  const page = Math.max(1, Number(params.get("page") || 1));
  const type = params.get("type") || "movie";
  const searchInput = useRef(null);

  const filters = useMemo(
    () => ({
      media_type: type,
      query: params.get("q") || "",
      language: params.get("language") || "",
      genre: params.get("genre") || "",
      flag: params.get("flag") || "",
      sort: params.get("sort") || "updated:desc",
      page,
      page_size: PAGE_SIZE,
    }),
    [params, type, page]
  );

  useEffect(() => {
    let alive = true;
    setLoading(true);
    setError("");
    api
      .get("/admin/api/media", filters)
      .then((d) => {
        if (!alive) return;
        setRows(d.items || []);
        setTotal(d.total_count || 0);
        setPages(Math.max(1, Math.ceil((d.total_count || 0) / PAGE_SIZE)));
      })
      .catch((e) => alive && setError(e.message))
      .finally(() => alive && setLoading(false));
    return () => {
      alive = false;
    };
  }, [filters, nonce]);

  useEffect(() => setSelected(new Set()), [filters]);

  const setParam = (key, value) => {
    const next = new URLSearchParams(params);
    if (value) next.set(key, String(value));
    else next.delete(key);
    if (key !== "page") next.delete("page");
    setParams(next, { replace: true });
  };

  const key = (m) => `${m.type}/${m.db_index}/${m.tmdb_id}`;
  const toggle = (m) =>
    setSelected((prev) => {
      const next = new Set(prev);
      const k = key(m);
      if (next.has(k)) next.delete(k);
      else next.add(k);
      return next;
    });

  const selectedRows = rows.filter((m) => selected.has(key(m)));

  const runBulk = async (action, extra = {}) => {
    setBulkBusy(true);
    try {
      const items = selectedRows.map((m) => ({
        type: m.collection || m.type,
        db_index: m.db_index,
        tmdb_id: m.tmdb_id,
      }));
      const res = await api.post("/admin/api/media/bulk", { action, items, ...extra });
      toast(`${res.succeeded}/${res.attempted} done${res.failed ? ` • ${res.failed} failed` : ""}`);
      if (res.errors?.length) toast(res.errors[0], "info");
      setConfirm(null);
      setSelected(new Set());
      setNonce((n) => n + 1);
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setBulkBusy(false);
    }
  };

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-end gap-3">
        <div className="mr-auto">
          <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Catalogue</p>
          <h1 className="font-display text-3xl mt-1.5">Media library</h1>
          <p className="text-sm text-bone/60 mt-1">
            {loading ? "Scanning clusters…" : `${total.toLocaleString()} titles match your filters`}
          </p>
        </div>
        <div className="flex gap-1 p-1 rounded-md bg-bone/4 border border-bone/8">
          {TYPES.map((t) => (
            <button
              key={t.id}
              type="button"
              onClick={() => setParam("type", t.id === "movie" ? "" : t.id)}
              className={cx(
                "px-3 py-1.5 rounded-[4px] text-sm transition-colors",
                type === t.id ? "bg-projector text-ink font-semibold" : "text-bone/55 hover:text-bone"
              )}
            >
              {t.label}
            </button>
          ))}
        </div>
      </header>

      <Panel>
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          <div className="lg:col-span-2">
            <Label htmlFor="lib-q">Search</Label>
            <div className="relative">
              <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-bone/55" size={15} />
              <TextInput
                id="lib-q"
                ref={searchInput}
                defaultValue={params.get("q") || ""}
                placeholder="Title or file name…"
                className="pl-9"
                onKeyDown={(e) => e.key === "Enter" && setParam("q", e.currentTarget.value.trim())}
              />
            </div>
          </div>
          <div>
            <Label htmlFor="lib-flag">Quality filter</Label>
            <Select id="lib-flag" value={params.get("flag") || ""} onChange={(e) => setParam("flag", e.target.value)}>
              {FLAGS.map((f) => (
                <option key={f.id || "none"} value={f.id}>
                  {f.label}
                </option>
              ))}
            </Select>
          </div>
          <div>
            <Label htmlFor="lib-sort">Sort by</Label>
            <Select
              id="lib-sort"
              value={params.get("sort") || "updated:desc"}
              onChange={(e) => setParam("sort", e.target.value)}
            >
              {SORTS.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.label}
                </option>
              ))}
            </Select>
          </div>
          <div>
            <Label htmlFor="lib-lang">Language</Label>
            <TextInput
              id="lib-lang"
              defaultValue={params.get("language") || ""}
              placeholder="tamil"
              onKeyDown={(e) => e.key === "Enter" && setParam("language", e.currentTarget.value.trim())}
            />
          </div>
          <div>
            <Label htmlFor="lib-genre">Genre</Label>
            <TextInput
              id="lib-genre"
              defaultValue={params.get("genre") || ""}
              placeholder="action"
              onKeyDown={(e) => e.key === "Enter" && setParam("genre", e.currentTarget.value.trim())}
            />
          </div>
          <div className="flex items-end gap-2 sm:col-span-2">
            <Button variant="primary" onClick={() => setParam("q", searchInput.current?.value.trim() || "")}>
              <FiSearch size={14} /> Apply
            </Button>
            {params.size > 0 && (
              <Button variant="quiet" onClick={() => setParams({}, { replace: true })}>
                <FiX size={14} /> Clear filters
              </Button>
            )}
          </div>
        </div>
      </Panel>

      {selected.size > 0 && (
        <div className="sticky top-0 z-30 glass-dark rounded-lg px-4 py-3 flex flex-wrap items-center gap-2 shadow-xl">
          <Badge tone="good">{selected.size} selected</Badge>
          <span className="mr-auto timecode text-[10px] uppercase tracking-[0.16em] text-bone/60">
            Bulk actions apply to the selected titles on this page
          </span>
          <Button variant="ghost" disabled={bulkBusy} onClick={() => runBulk("refresh")}>
            <FiRefreshCw size={14} /> Refresh TMDB
          </Button>
          <Button variant="danger" disabled={bulkBusy} onClick={() => setConfirm("telegram")}>
            <FiTrash2 size={14} /> Telegram + DB
          </Button>
          <Button variant="danger" disabled={bulkBusy} onClick={() => setConfirm("delete")}>
            <FiTrash2 size={14} /> DB only
          </Button>
        </div>
      )}

      <Panel>
        {error ? (
          <EmptyState icon={<FiX />} title="Could not load media">
            {error}
          </EmptyState>
        ) : loading ? (
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-3">
            {Array.from({ length: 12 }).map((_, i) => (
              <div key={i} className="animate-pulse">
                <div className="aspect-[2/3] rounded-[4px] bg-bone/6" />
                <div className="h-3 rounded bg-bone/6 mt-2.5" />
              </div>
            ))}
          </div>
        ) : rows.length === 0 ? (
          <EmptyState title="No titles found">Loosen the filters or try a different search.</EmptyState>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-3">
            {rows.map((m) => {
              const isSel = selected.has(key(m));
              return (
                <div
                  key={key(m)}
                  className={cx(
                    "group relative rounded-md border transition-colors overflow-hidden",
                    isSel ? "border-projector/70 bg-projector/6" : "border-bone/8 bg-ink/40 hover:border-bone/20"
                  )}
                >
                  <Link
                    to={`/admin/media/${m.collection || m.type}/${m.db_index}/${m.tmdb_id}`}
                    className="block focus:outline-none focus-visible:ring-2 focus-visible:ring-projector/70"
                  >
                    <div className="relative aspect-[2/3] bg-carbon">
                      {m.poster ? (
                        <img
                          src={m.poster}
                          alt=""
                          loading="lazy"
                          className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-[1.03]"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-bone/50 text-[10px] timecode uppercase">
                          no poster
                        </div>
                      )}
                      <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-ink via-ink/70 to-transparent pt-8 pb-2 px-2">
                        <p className="text-[11px] font-semibold text-bone leading-snug line-clamp-2">{m.title}</p>
                        <p className="timecode text-[9px] text-bone/50 mt-1 uppercase tracking-wider">
                          {m.release_year || "—"} • {m.file_count || 0}f • {m.subtitle_count || 0}s
                        </p>
                      </div>
                      {m.file_count === 0 && (
                        <span className="absolute top-1.5 left-1.5">
                          <Badge tone="bad">0 files</Badge>
                        </span>
                      )}
                    </div>
                  </Link>
                  <button
                    type="button"
                    aria-label={isSel ? "Deselect" : "Select"}
                    onClick={() => toggle(m)}
                    className={cx(
                      "absolute top-1.5 right-1.5 w-6 h-6 rounded-[4px] border flex items-center justify-center transition-all",
                      isSel
                        ? "bg-projector border-projector text-ink"
                        : "border-bone/25 bg-ink/70 text-transparent opacity-0 group-hover:opacity-100 hover:border-bone/60"
                    )}
                  >
                    <FiCheck size={13} />
                  </button>
                </div>
              );
            })}
          </div>
        )}

        {pages > 1 && (
          <nav className="mt-5 pt-4 border-t border-bone/6 flex items-center justify-center gap-2">
            <Button variant="ghost" disabled={page <= 1 || loading} onClick={() => setParam("page", page - 1)}>
              Previous
            </Button>
            <span className="timecode text-[11px] text-bone/50 px-2">
              page {page} / {pages}
            </span>
            <Button variant="ghost" disabled={page >= pages || loading} onClick={() => setParam("page", page + 1)}>
              Next
            </Button>
          </nav>
        )}
      </Panel>

      <ConfirmModal
        open={confirm === "delete"}
        onClose={() => setConfirm(null)}
        busy={bulkBusy}
        title={`Delete ${selected.size} titles from the database`}
        confirmWord="DELETE"
        confirmLabel="Delete from DB"
        onConfirm={() => runBulk("delete")}
      />
      <ConfirmModal
        open={confirm === "telegram"}
        onClose={() => setConfirm(null)}
        busy={bulkBusy}
        title="Delete from Telegram and the database"
        confirmWord="DELETE"
        confirmLabel="Delete everything"
        onConfirm={() => runBulk("delete_telegram")}
      />
    </div>
  );
}

import React, { useCallback, useEffect, useState } from "react";
import { FiChevronLeft, FiChevronRight, FiRefreshCw, FiUpload } from "react-icons/fi";
import { api } from "./api";
import { AdminErrorState, Badge, Button, EmptyState, Label, Panel, Select, Spinner, TextInput, cx, toast } from "./ui";
import { useChannels } from "./channels";

/* Orphan file report: video posts the channel has but the library does not.
   The recovery path is the ordinary link path — "queue these" re-uses it. */
export default function OrphansPage() {
  const { channels } = useChannels();
  const [data, setData] = useState(null);
  const [jobs, setJobs] = useState(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [channel, setChannel] = useState("");
  const [page, setPage] = useState(1);
  const [selected, setSelected] = useState(new Set());

  const load = useCallback(async () => {
    try {
      const d = await api.get("/admin/api/orphans", {
        channel,
        include_resolved: false,
        page,
      });
      setData(d);
      setError("");
    } catch (e) {
      setError(e.message);
    }
  }, [channel, page]);

  const loadJobs = useCallback(async () => {
    try {
      setJobs(await api.get("/admin/api/jobs"));
    } catch (e) {
      /* secondary panel */
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);
  useEffect(() => {
    loadJobs();
  }, [loadJobs]);

  const act = async (label, fn) => {
    setBusy(true);
    try {
      await fn();
      toast(label);
      await load();
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setBusy(false);
    }
  };

  const toggle = (id) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  if (error && !data)
    return (
      <Panel>
        <AdminErrorState title="Orphan report unavailable" error={error} />
      </Panel>
    );
  if (!data)
    return (
      <div className="flex justify-center py-24">
        <Spinner className="w-6 h-6" />
      </div>
    );

  const items = data.items || [];
  const total = data.total_count || 0;
  const pageSize = data.page_size || 50;
  const pages = Math.max(1, Math.ceil(total / pageSize));
  const scanEnabled = jobs?.switches?.orphan_scan;
  // The report filter uses the bare id ("1234567890"), but the scan job needs
  // the full "-100…" chat id to open the channel through the bot client.
  const selectedChannel = channels.find((c) => c.clean_id === channel);
  const scanChannelId = selectedChannel ? selectedChannel.id : channel;
  const scanChannelIds = scanChannelId
    ? [scanChannelId]
    : channels.map((c) => c.id);

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-end gap-3">
        <div className="mr-auto">
          <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Gaps</p>
          <h1 className="font-display text-3xl mt-1.5">Orphan files</h1>
          <p className="text-sm text-bone/60 mt-1">
            {total.toLocaleString()} video posts with no library match
          </p>
        </div>
        {scanEnabled ? <Badge tone="ok">Scan enabled</Badge> : <Badge tone="warn">Scan disabled</Badge>}
        <Button variant="ghost" onClick={load} disabled={busy}>
          <FiRefreshCw size={14} /> Refresh
        </Button>
      </header>

      <Panel
        title="Filter"
        subtitle="Rows older than the newest completed scan of their channel are treated as resolved"
      >
        <div className="flex flex-wrap items-end gap-3">
          <div className="min-w-[220px]">
            <Label htmlFor="orphan-channel">Channel</Label>
            {channels.length > 0 ? (
              <Select
                id="orphan-channel"
                value={channel}
                onChange={(e) => {
                  setPage(1);
                  setChannel(e.target.value);
                }}
              >
                <option value="">All channels</option>
                {channels.map((c) => (
                  <option key={c.index} value={c.clean_id}>
                    {c.label}
                  </option>
                ))}
              </Select>
            ) : (
              <TextInput
                id="orphan-channel"
                value={channel}
                placeholder="e.g. 1234567890"
                onChange={(e) => {
                  setPage(1);
                  setChannel(e.target.value);
                }}
              />
            )}
          </div>
          <Button variant="primary" onClick={load} disabled={busy}>
            Apply
          </Button>
          {scanEnabled ? (
            <Button
              variant="ghost"
              disabled={busy || scanChannelIds.length === 0}
              onClick={() =>
                act("Orphan scan started", () =>
                  api.post("/admin/api/jobs/start", {
                    kind: "orphan_scan",
                    params: { channels: scanChannelIds },
                  })
                )
              }
            >
              {channel ? "Scan this channel" : "Scan all channels"}
            </Button>
          ) : (
            <span className="text-[11px] text-bone/55">
              Set ORPHAN_SCAN=true on the server to scan for orphans.
            </span>
          )}
        </div>
      </Panel>

      <Panel
        title="Orphans"
        subtitle="Select the posts you want back in the library"
        actions={
          <Button
            variant="primary"
            disabled={busy || selected.size === 0}
            onClick={() =>
              act(
                "Orphans queued",
                async () => {
                  await api.post("/admin/api/orphans/queue", { ids: Array.from(selected) });
                  setSelected(new Set());
                }
              )
            }
          >
            <FiUpload size={14} /> Queue {selected.size || ""} selected
          </Button>
        }
      >
        {items.length === 0 ? (
          <EmptyState title="No orphan posts">
            Every video post in the scanned channels is already in the library.
          </EmptyState>
        ) : (
          <div className="overflow-x-auto -mx-1 px-1">
            <table className="w-full text-sm min-w-[680px]">
              <thead>
                <tr className="text-left">
                  {["", "Channel", "Message", "Title", "Scanned", ""].map((h, i) => (
                    <th
                      key={`${h}-${i}`}
                      className="timecode text-[10px] uppercase tracking-[0.14em] text-bone/60 pb-2 pr-3 font-normal"
                    >
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {items.map((row) => {
                  const isSelected = selected.has(row.id);
                  return (
                    <tr
                      key={row.id}
                      className={cx("border-t border-bone/6", isSelected && "bg-projector/5")}
                    >
                      <td className="py-2.5 pr-3">
                        <input
                          type="checkbox"
                          aria-label={`Select message ${row.message_id}`}
                          checked={isSelected}
                          onChange={() => toggle(row.id)}
                          className="accent-[#e9b872] w-4 h-4"
                        />
                      </td>
                      <td className="py-2.5 pr-3 timecode text-[11px] text-bone/60">
                        {row.channel}
                      </td>
                      <td className="py-2.5 pr-3 timecode text-[11px] text-bone/60 tabular-nums">
                        {row.message_id}
                      </td>
                      <td className="py-2.5 pr-3">
                        <p className="text-bone truncate max-w-[280px]">
                          {row.title || "Untitled"}
                        </p>
                        {row.size ? (
                          <p className="timecode text-[10px] text-bone/55">
                            {row.size} bytes
                          </p>
                        ) : null}
                      </td>
                      <td className="py-2.5 pr-3 timecode text-[11px] text-bone/50">
                        {row.scanned_at ? new Date(row.scanned_at).toLocaleString() : "—"}
                      </td>
                      <td className="py-2.5 text-right">
                        <a
                          href={`https://t.me/c/${String(row.channel).replace(/^-/, "")}/${row.message_id}`}
                          target="_blank"
                          rel="noreferrer"
                          className="timecode text-[11px] text-projector hover:underline"
                        >
                          open
                        </a>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
        {items.length > 0 ? (
          <div className="mt-4 pt-4 border-t border-bone/6 flex items-center justify-between">
            <p className="timecode text-[10px] text-bone/60">
              page {data.page || page} of {pages} · {total.toLocaleString()} rows
            </p>
            <div className="flex items-center gap-2">
              <Button
                variant="ghost"
                disabled={busy || page <= 1}
                onClick={() => setPage((p) => Math.max(1, p - 1))}
              >
                <FiChevronLeft size={14} /> Newer
              </Button>
              <Button
                variant="ghost"
                disabled={busy || page >= pages}
                onClick={() => setPage((p) => p + 1)}
              >
                Older <FiChevronRight size={14} />
              </Button>
            </div>
          </div>
        ) : null}
      </Panel>
    </div>
  );
}

import React, { useCallback, useEffect, useState } from "react";
import { FiRefreshCw, FiRotateCcw, FiSave } from "react-icons/fi";
import { api } from "./api";
import { AdminErrorState, Badge, Button, Label, Panel, Spinner, TextInput, cx, toast } from "./ui";

/* Live runtime knobs. An override survives a restart; clearing it falls back
   to the value the environment defines. */
export default function SettingsPage() {
  const [knobs, setKnobs] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [drafts, setDrafts] = useState({});

  const load = useCallback(async () => {
    try {
      const data = await api.get("/admin/api/config");
      const rows = data.knobs || [];
      setKnobs(rows);
      setDrafts(
        rows.reduce((acc, row) => {
          acc[row.key] = row.type === "bool" ? String(row.value) : String(row.value ?? "");
          return acc;
        }, {})
      );
      setError("");
      setLoaded(true);
    } catch (e) {
      setError(e.message);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const save = async (row) => {
    const raw = drafts[row.key];

    /*
     * Coerce before sending. The old line was
     *   row.type === "int" ? Number(raw) : Number(raw)
     * — both branches identical — so every non-bool knob went through
     * `Number(raw)`. Clearing a field produced Number("") === 0, which is a
     * valid in-range integer for most knobs, so emptying an input and pressing
     * Save silently wrote 0 instead of complaining. Non-numeric text produced
     * NaN, which JSON-serialises to null and came back as a confusing
     * "'key' expects an integer".
     */
    let value;
    if (row.type === "bool") {
      value = raw === "true";
    } else {
      const trimmed = String(raw ?? "").trim();
      if (trimmed === "") {
        toast(`${row.label} needs a value`, "error");
        return;
      }
      value = Number(trimmed);
      if (!Number.isFinite(value)) {
        toast(`${row.label} must be a number`, "error");
        return;
      }
      if (row.type === "int" && !Number.isInteger(value)) {
        toast(`${row.label} must be a whole number`, "error");
        return;
      }
      if (row.min != null && value < row.min) {
        toast(`${row.label} must be at least ${row.min}`, "error");
        return;
      }
      if (row.max != null && value > row.max) {
        toast(`${row.label} must be at most ${row.max}`, "error");
        return;
      }
    }

    setBusy(true);
    try {
      await api.patch("/admin/api/config", { key: row.key, value });
      toast(`${row.label} saved`);
      await load();
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setBusy(false);
    }
  };

  const reset = async (row) => {
    setBusy(true);
    try {
      await api.patch("/admin/api/config", { key: row.key, reset: true });
      toast(`${row.label} reset to the environment default`);
      await load();
    } catch (e) {
      toast(e.message, "error");
    } finally {
      setBusy(false);
    }
  };

  if (error && !loaded)
    return (
      <Panel>
        <AdminErrorState title="Settings unavailable" error={error} />
      </Panel>
    );
  if (!loaded)
    return (
      <div className="flex justify-center py-24">
        <Spinner className="w-6 h-6" />
      </div>
    );

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-end gap-3">
        <div className="mr-auto">
          <p className="timecode text-[10px] uppercase tracking-[0.26em] text-projector/80">Operations</p>
          <h1 className="font-display text-3xl mt-1.5">Runtime settings</h1>
          <p className="text-sm text-bone/60 mt-1">
            Live queue and index knobs. Every change is audited.
          </p>
        </div>
        <Button variant="ghost" onClick={load} disabled={busy}>
          <FiRefreshCw size={14} /> Refresh
        </Button>
      </header>

      <Panel title="Knobs" subtitle="Overrides are stored in app_settings and survive a restart">
        <div className="space-y-3">
          {knobs.map((row) => (
            <div
              key={row.key}
              className="grid gap-3 sm:grid-cols-[minmax(0,1fr)_auto] items-end rounded-md border border-bone/8 bg-ink/40 px-4 py-3.5"
            >
              <div className="min-w-0">
                <div className="flex flex-wrap items-center gap-2">
                  <p className="text-sm font-medium text-bone">{row.label}</p>
                  {row.overridden ? (
                    <Badge tone="good">Overridden</Badge>
                  ) : (
                    <Badge>Default</Badge>
                  )}
                  {row.restart_only ? <Badge tone="warn">Restart only</Badge> : null}
                </div>
                <p className="timecode text-[10px] text-bone/60 mt-1">
                  {row.key} · {row.live}
                </p>
                <p className="timecode text-[10px] text-bone/55 mt-0.5">
                  env default: {String(row.default)}
                  {row.min != null && row.max != null ? ` · range ${row.min}–${row.max}` : ""}
                </p>
              </div>
              <div className="flex items-center gap-2">
                {row.type === "bool" ? (
                  <select
                    aria-label={row.label}
                    value={drafts[row.key] ?? "false"}
                    disabled={busy}
                    onChange={(e) => setDrafts((d) => ({ ...d, [row.key]: e.target.value }))}
                    className="rounded-md bg-ink/60 border border-bone/12 px-3 py-2 text-sm text-bone focus:outline-none focus:border-projector/60"
                  >
                    <option value="true">Enabled</option>
                    <option value="false">Disabled</option>
                  </select>
                ) : (
                  <TextInput
                    aria-label={row.label}
                    type="number"
                    step={row.type === "float" ? "0.1" : "1"}
                    min={row.min ?? undefined}
                    max={row.max ?? undefined}
                    value={drafts[row.key] ?? ""}
                    disabled={busy}
                    onChange={(e) => setDrafts((d) => ({ ...d, [row.key]: e.target.value }))}
                    className="w-32 text-right tabular-nums"
                  />
                )}
                <Button variant="primary" disabled={busy} onClick={() => save(row)}>
                  <FiSave size={14} /> Save
                </Button>
                <Button
                  variant="ghost"
                  disabled={busy || !row.overridden}
                  onClick={() => reset(row)}
                  title="Drop the override and fall back to the environment default"
                >
                  <FiRotateCcw size={14} />
                </Button>
              </div>
            </div>
          ))}
        </div>
      </Panel>

      <p className={cx("text-[11px] text-bone/55")}>
        A knob left at its default reproduces the behaviour the bot had before
        this page existed. “Restart only” means the value is applied when the
        process starts, not while it runs.
      </p>
    </div>
  );
}

import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api } from "./api";
import { Badge, EmptyState, Panel, Spinner, cx, toast } from "./ui";

const RANGES = [7, 14, 30];

export default function ViewsPanel() {
  const [days, setDays] = useState(7);
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let alive = true;
    setLoading(true);
    api
      .get("/admin/api/views-analytics", { days, limit: 8 })
      .then((d) => alive && setData(d))
      .catch((e) => alive && toast(e.message, "error"))
      .finally(() => alive && setLoading(false));
    return () => {
      alive = false;
    };
  }, [days]);

  const daily = data?.daily || [];
  const peak = Math.max(1, ...daily.map((d) => d.count || 0));
  const totals = data?.totals || {};

  return (
    <Panel
      title="Views"
      subtitle={`${(totals.today ?? 0).toLocaleString()} today • ${(totals.all_time ?? 0).toLocaleString()} all time`}
      actions={
        <div className="flex gap-1 p-1 rounded-md bg-bone/4 border border-bone/8">
          {RANGES.map((r) => (
            <button
              key={r}
              type="button"
              onClick={() => setDays(r)}
              className={cx(
                "px-2.5 py-1 rounded-[4px] timecode text-[10px] uppercase tracking-wider transition-colors",
                days === r ? "bg-projector text-ink font-semibold" : "text-bone/50 hover:text-bone"
              )}
            >
              {r}d
            </button>
          ))}
        </div>
      }
    >
      {loading ? (
        <div className="flex justify-center py-10">
          <Spinner />
        </div>
      ) : daily.length === 0 ? (
        <EmptyState title="No view data yet">Play counts appear once viewers start watching.</EmptyState>
      ) : (
        <>
          <div className="flex items-end gap-1 h-24 mb-1">
            {daily.map((d) => (
              <div
                key={d.date}
                title={`${d.date}: ${d.count} views`}
                className="flex-1 rounded-t-[2px] bg-gradient-to-t from-projector/40 to-projector/85 hover:from-projector/60 hover:to-projector transition-all"
                style={{ height: `${Math.max(4, (d.count / peak) * 100)}%` }}
              />
            ))}
          </div>
          <div className="flex justify-between timecode text-[9px] text-bone/55 mb-4">
            <span>{daily[0]?.date?.slice(5)}</span>
            <span>{daily[daily.length - 1]?.date?.slice(5)}</span>
          </div>
          <p className="timecode text-[10px] uppercase tracking-[0.16em] text-bone/60 mb-2">Most watched</p>
          <ol className="space-y-1.5">
            {(data.top || []).map((t, i) => (
              <li key={`${t.media_type}-${t.tmdb_id}`}>
                <Link
                  to={`/admin/media/${t.media_type}/1/${t.tmdb_id}`}
                  className="group flex items-center gap-3 rounded-md px-2 py-1.5 hover:bg-bone/5 transition-colors"
                >
                  <span className="timecode text-[11px] text-projector/70 w-4 shrink-0">{i + 1}</span>
                  <span className="text-sm text-bone/80 truncate group-hover:text-projector transition-colors mr-auto">
                    {t.title}
                  </span>
                  <Badge tone="neutral">{(t.views || 0).toLocaleString()}</Badge>
                </Link>
              </li>
            ))}
          </ol>
        </>
      )}
    </Panel>
  );
}

/* Shared UI primitives for the admin console — same film-noir language as the site. */
import React, { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { FiX, FiCheck, FiAlertTriangle, FiInfo } from "react-icons/fi";
import { clearToken, isStaleBackendError } from "./api";

export const cx = (...parts) => parts.filter(Boolean).join(" ");

export function formatEta(seconds) {
  const s = Number(seconds);
  if (!Number.isFinite(s) || s <= 0) return "—";
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  if (h) return `${h}h ${m}m`;
  const sec = Math.floor(s % 60);
  return m ? `${m}m ${sec}s` : `${sec}s`;
}

/* ── Toasts ─────────────────────────────────────────────────────────────── */
const toastListeners = new Set();
let toastSeq = 0;

export function toast(message, kind = "success") {
  toastListeners.forEach((fn) => fn({ id: ++toastSeq, message, kind }));
}

export function Toaster() {
  const [items, setItems] = useState([]);
  useEffect(() => {
    const add = (item) => {
      setItems((prev) => [...prev, item]);
      setTimeout(() => setItems((prev) => prev.filter((t) => t.id !== item.id)), 3200);
    };
    toastListeners.add(add);
    return () => toastListeners.delete(add);
  }, []);
  if (!items.length) return null;
  return createPortal(
    <div className="fixed top-4 right-4 z-[80] flex flex-col gap-2 max-w-sm">
      {items.map((t) => (
        <div
          key={t.id}
          role="status"
          className={cx(
            "glass-dark flex items-start gap-2.5 rounded-md px-4 py-3 text-sm shadow-[0_16px_40px_-16px_rgba(0,0,0,0.9)]",
            t.kind === "error" ? "text-signal" : t.kind === "info" ? "text-bone/80" : "text-projector"
          )}
        >
          <span className="mt-0.5 shrink-0">
            {t.kind === "error" ? <FiAlertTriangle /> : t.kind === "info" ? <FiInfo /> : <FiCheck />}
          </span>
          <span className="leading-snug text-bone/90">{t.message}</span>
        </div>
      ))}
    </div>,
    document.body
  );
}

/* ── Building blocks ────────────────────────────────────────────────────── */
export function Panel({ title, subtitle, actions, children, className }) {
  return (
    <section className={cx("glass-card rounded-lg p-4 sm:p-5", className)}>
      {(title || actions) && (
        <header className="flex flex-wrap items-center gap-3 mb-4">
          <div className="min-w-0 mr-auto">
            {title && <h2 className="section-title text-lg text-bone">{title}</h2>}
            {subtitle && (
              <p className="timecode text-[10px] uppercase tracking-[0.16em] text-bone/50 mt-0.5">
                {subtitle}
              </p>
            )}
          </div>
          {actions && <div className="flex items-center gap-2 shrink-0">{actions}</div>}
        </header>
      )}
      {children}
    </section>
  );
}

export function Label({ children, htmlFor }) {
  return (
    <label
      htmlFor={htmlFor}
      className="block timecode text-[10px] uppercase tracking-[0.16em] text-bone/50 mb-1.5"
    >
      {children}
    </label>
  );
}

const inputBase =
  "w-full rounded-md bg-ink/60 border border-bone/12 px-3 py-2.5 text-sm text-bone placeholder:text-bone/50 focus:outline-none focus:border-projector/60 focus:ring-1 focus:ring-projector/30 transition-colors";

export const TextInput = React.forwardRef(function TextInput(props, ref) {
  return <input ref={ref} {...props} className={cx(inputBase, props.className)} />;
});

export function TextArea(props) {
  return <textarea {...props} className={cx(inputBase, "min-h-[90px] leading-relaxed", props.className)} />;
}

export function Select({ children, ...props }) {
  return (
    <select {...props} className={cx(inputBase, "appearance-none", props.className)}>
      {children}
    </select>
  );
}

export function Field({ label, hint, children }) {
  return (
    <div>
      <Label>{label}</Label>
      {children}
      {hint && <p className="text-[11px] text-bone/60 mt-1">{hint}</p>}
    </div>
  );
}

export function Button({ variant = "ghost", className, children, ...props }) {
  const styles = {
    primary:
      "bg-projector text-ink font-semibold hover:bg-projector/85 active:scale-[0.98] shadow-[0_10px_24px_-12px_rgba(233,184,114,0.8)]",
    ghost:
      "bg-bone/5 text-bone/85 border border-bone/12 hover:bg-bone/10 hover:text-bone active:scale-[0.98]",
    danger:
      "bg-signal/12 text-signal border border-signal/40 hover:bg-signal/20 active:scale-[0.98]",
    quiet: "text-bone/55 hover:text-bone",
  }[variant];
  return (
    <button
      {...props}
      type={props.type || "button"}
      className={cx(
        "inline-flex items-center justify-center gap-2 rounded-md px-3.5 py-2 text-sm transition-all duration-150 disabled:opacity-40 disabled:pointer-events-none",
        styles,
        className
      )}
    >
      {children}
    </button>
  );
}

export function Badge({ tone = "neutral", children }) {
  const tones = {
    neutral: "border-bone/15 text-bone/60",
    good: "border-projector/40 text-projector",
    ok: "border-emerald-400/35 text-emerald-300",
    warn: "border-amber-300/35 text-amber-200",
    bad: "border-signal/45 text-signal",
  };
  return (
    <span
      className={cx(
        "inline-flex items-center gap-1 timecode text-[10px] uppercase tracking-[0.12em] px-2 py-0.5 rounded-[2px] border bg-ink/50",
        tones[tone]
      )}
    >
      {children}
    </span>
  );
}

export function Spinner({ className }) {
  return (
    <span
      role="status"
      aria-label="Loading"
      className={cx(
        "inline-block w-4 h-4 rounded-full border-2 border-bone/20 border-t-projector animate-spin align-middle",
        className
      )}
    />
  );
}

export function EmptyState({ icon, title, children }) {
  return (
    <div className="text-center py-10 px-4">
      {icon && <div className="text-3xl text-bone/50 mb-3 flex justify-center">{icon}</div>}
      <p className="section-title text-bone/60 text-base">{title}</p>
      {children && <p className="text-sm text-bone/55 mt-1 max-w-sm mx-auto">{children}</p>}
    </div>
  );
}

/* One shared error state for every admin page. A 404 from /admin/api/* is not a
   broken page: the running backend predates those routes (or the console is
   pointed at the frontend). Explain the real fix once, with actions, instead of
   showing "Not Found" on six separate pages. */
export function AdminErrorState({ title, error }) {
  const message =
    typeof error === "string" ? error : (error && error.message) || String(error || "");
  if (!isStaleBackendError(error)) {
    return <EmptyState title={title}>{message}</EmptyState>;
  }
  return (
    <div className="text-left py-7 px-2 max-w-2xl mx-auto">
      <Badge tone="bad">Backend out of date</Badge>
      <p className="section-title text-bone/80 text-lg mt-3">
        {title} — the running backend is an older build
      </p>
      <p className="text-sm text-bone/55 mt-2 leading-relaxed">
        The console asked for an admin route and got <code>404 Not Found</code>.
        Manual add, multi-channel indexing, the skip-count prompt, hero,
        indexing, orphans, curation, settings and audit all exist in the current
        source — they are missing here only because the backend was not
        redeployed.
      </p>
      <ol className="text-sm text-bone/55 mt-3 list-decimal pl-5 space-y-1.5 leading-relaxed">
        <li>
          Deploy or restart the current <code>filmsclub-backend</code> (a
          frontend-only redeploy cannot add backend routes).
        </li>
        <li>
          If it is already current, check the backend URL — the console may be
          talking to the frontend or a different host.
        </li>
      </ol>
      <div className="flex flex-wrap gap-2 mt-5">
        <Button variant="primary" onClick={() => window.location.reload()}>
          Recheck
        </Button>
        <Button
          onClick={() => {
            clearToken();
            window.location.href = `${window.location.pathname}?conn=1`;
          }}
        >
          Backend connection
        </Button>
      </div>
      {message ? (
        <details className="mt-5">
          <summary className="text-[12px] text-bone/55 cursor-pointer select-none">
            Technical detail
          </summary>
          <p className="timecode text-[10px] text-bone/55 mt-2 break-all leading-relaxed">
            {message}
          </p>
        </details>
      ) : null}
    </div>
  );
}

export function Modal({ open, onClose, title, children, width = "max-w-lg" }) {
  useEffect(() => {
    if (!open) return undefined;
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);
  if (!open) return null;
  return createPortal(
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-ink/80 backdrop-blur-sm"
      onMouseDown={(e) => e.target === e.currentTarget && onClose()}
    >
      <div role="dialog" aria-modal="true" className={cx("glass-dark w-full rounded-lg shadow-2xl max-h-[86vh] flex flex-col", width)}>
        <header className="flex items-center gap-3 px-5 py-4 border-b border-bone/8 shrink-0">
          <h3 className="section-title text-lg text-bone mr-auto">{title}</h3>
          <button
            type="button"
            aria-label="Close"
            onClick={onClose}
            className="text-bone/50 hover:text-bone transition-colors"
          >
            <FiX size={18} />
          </button>
        </header>
        <div className="overflow-y-auto px-5 py-4">{children}</div>
      </div>
    </div>,
    document.body
  );
}

export function ConfirmModal({ open, onClose, title, confirmWord, onConfirm, confirmLabel = "Confirm", busy }) {
  const [word, setWord] = useState("");
  useEffect(() => {
    if (open) setWord("");
  }, [open]);
  const ready = !confirmWord || word.trim().toUpperCase() === confirmWord;
  return (
    <Modal open={open} onClose={onClose} title={title} width="max-w-md">
      {confirmWord && (
        <div className="mb-4">
          <Label>Type “{confirmWord}” to confirm</Label>
          <TextInput value={word} onChange={(e) => setWord(e.target.value)} placeholder={confirmWord} autoFocus />
        </div>
      )}
      <div className="flex justify-end gap-2">
        <Button variant="ghost" onClick={onClose}>
          Cancel
        </Button>
        <Button
          variant="danger"
          disabled={!ready || busy}
          onClick={() => onConfirm()}
        >
          {busy ? <Spinner /> : null}
          {confirmLabel}
        </Button>
      </div>
    </Modal>
  );
}

import React from "react";
import { motion } from "framer-motion";
import { HiSpeakerWave } from "react-icons/hi2";
import { HiVolumeUp } from "react-icons/hi";

const LANG_MAP = {
  te: "Telugu", telugu: "Telugu",
  ta: "Tamil", tamil: "Tamil",
  hi: "Hindi", hindi: "Hindi",
  en: "English", english: "English",
  ml: "Malayalam", malayalam: "Malayalam",
  kn: "Kannada", kannada: "Kannada",
  bn: "Bengali", bengali: "Bengali",
  mr: "Marathi", marathi: "Marathi",
  pa: "Punjabi", punjabi: "Punjabi",
  ur: "Urdu", urdu: "Urdu",
  es: "Spanish", spanish: "Spanish",
  ja: "Japanese", japanese: "Japanese",
  ko: "Korean", korean: "Korean",
};

export default function AudioTracks({ audioTracks = [] }) {
  const rawTracks = Array.isArray(audioTracks) ? audioTracks : [];
  
  if (!rawTracks.length) return null;

  // Format tracks cleanly
  const tracks = rawTracks.map((track, idx) => {
    if (typeof track === "string") {
      const code = track.toLowerCase().trim();
      const langName = LANG_MAP[code] || (track.charAt(0).toUpperCase() + track.slice(1));
      return {
        title: langName,
        language: langName,
        is_default: idx === 0,
      };
    }
    const rawLang = track.language || track.title || `Track ${idx + 1}`;
    const code = rawLang.toLowerCase().trim();
    const langName = LANG_MAP[code] || (rawLang.charAt(0).toUpperCase() + rawLang.slice(1));
    return {
      ...track,
      title: track.title || langName,
      language: langName,
      is_default: track.is_default || idx === 0,
    };
  });

  return (
    <motion.section
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3 }}
      className="mt-4 mb-2 p-3.5 sm:p-4 rounded-[4px] bg-bone/[0.03] border border-bone/10 backdrop-blur-md space-y-2.5"
    >
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="p-1.5 rounded-[3px] bg-projector/10 border border-projector/25 text-projector">
            <HiSpeakerWave className="text-sm" />
          </div>
          <h3 className="text-xs sm:text-sm font-bold text-bone tracking-wide">
            Audio Tracks
          </h3>
        </div>
        <span className="px-2 py-0.5 rounded-[2px] bg-projector/10 border border-projector/25 text-projector text-[10px] font-bold timecode">
          {tracks.length} available
        </span>
      </div>

      <div className="flex flex-wrap gap-2 pt-0.5">
        {tracks.map((track, index) => (
          <motion.div
            key={index}
            initial={{ opacity: 0, scale: 0.92 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ delay: index * 0.04 }}
            className={`
              flex items-center gap-2 px-3 py-1.5 rounded-[3px] border text-xs transition-colors duration-200
              ${track.is_default
                ? "bg-projector/12 border-projector/40 text-bone shadow-[0_2px_8px_rgba(233,184,114,0.18)]"
                : "bg-bone/[0.05] border-bone/10 text-bone/80 hover:bg-bone/[0.08] hover:border-bone/20"
              }
            `}
          >
            <HiVolumeUp className={track.is_default ? "text-projector text-xs" : "text-bone/60 text-xs"} />
            <span className="font-semibold tracking-wide">{track.title || track.language}</span>
            {track.codec && (
              <span className="px-1.5 py-0.5 rounded-[2px] bg-ink/50 text-bone/50 text-[10px] uppercase font-mono">
                {track.codec}
              </span>
            )}
            {track.channels && (
              <span className="px-1.5 py-0.5 rounded-[2px] bg-ink/50 text-bone/50 text-[10px] font-mono">
                {track.channels === 6 ? "5.1ch" : track.channels === 8 ? "7.1ch" : `${track.channels}ch`}
              </span>
            )}
            {track.is_default && (
              <span className="px-1.5 py-0.5 rounded-[2px] bg-projector text-ink text-[10px] font-extrabold tracking-wider">
                DEFAULT
              </span>
            )}
          </motion.div>
        ))}
      </div>
    </motion.section>
  );
}

import React, { useState, useEffect } from "react";
import { BASE_URL as BASE } from "../config";
import { Select, SelectItem } from "@nextui-org/select";
import { Popover, PopoverTrigger, PopoverContent } from "@nextui-org/popover";
import { Button } from "@nextui-org/button";
import { FaCloudDownloadAlt, FaPlay, FaDesktop } from "react-icons/fa";
import Spinner from "./svg/Spinner";

const DownloadButton = ({ movieData, btnType }) => {

  const [selectedSeason, setSelectedSeason] = useState("");
  const [selectedEpisode, setSelectedEpisode] = useState("");
  const [selectedQuality, setSelectedQuality] = useState("");
  const [episodes, setEpisodes] = useState([]);
  const [qualities, setQualities] = useState([]);
  const [loading, setLoading] = useState({});

  useEffect(() => {
    if (selectedSeason) {
      const season = (movieData.seasons || []).find(
        (s) => s.season_number === parseInt(selectedSeason)
      );
      if (season) {
        setEpisodes(season.episodes || []);
        setSelectedEpisode("");
        setQualities([]);
      }
    }
  }, [selectedSeason, movieData.seasons]);

  useEffect(() => {
    if (selectedEpisode) {
      const episode = episodes.find(
        (e) => e.episode_number === parseInt(selectedEpisode)
      );
      if (episode) {
        setQualities(episode.sources);
        setSelectedQuality("");
      }
    }
  }, [selectedEpisode, episodes]);

  const generateUrl = (id, name) => {
    const downloadUrl = `${BASE}/dl/${id}/${encodeURIComponent(name)}`;
    if (btnType === "Download") return downloadUrl;
    if (btnType === "PC Player") return downloadUrl;
    return `intent:${downloadUrl}#Intent;type=video/x-matroska;action=android.intent.action.VIEW;end;`;
  };

  const handleButtonClick = (id, name, quality) => {
    const rawUrl = generateUrl(id, name);
    window.open(rawUrl, "_blank", "noopener noreferrer");
  };

  const handleM3UDownload = (id, name) => {
    const isMobile = /Android|iPhone|iPad/i.test(navigator.userAgent);
    const streamUrl = `${BASE}/dl/${id}/${encodeURIComponent(name)}`;
    const safeName = name.replace(/[^a-zA-Z0-9]/g, "_");

    if (isMobile) {
      // Mobile: direct download intent
      const a = document.createElement("a");
      a.href = streamUrl;
      a.download = name;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      return;
    }

    // DESKTOP: Always generate M3U file (most reliable — works with VLC, MPC, mpv, etc.)
    // The M3U playlist contains the raw streaming URL so VLC can parse it correctly.
    generateAndDownloadM3U(streamUrl, safeName);

    // Also try the vlc:// protocol handler (opens VLC directly without file download).
    // We pass the raw URL — NOT encoded again — so VLC can open the MRL correctly.
    // This runs alongside the M3U download; one of the two will always work.
    try {
      const vlcDirectUrl = `vlc://${streamUrl}`;
      const a = document.createElement("a");
      a.href = vlcDirectUrl;
      a.style.display = "none";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    } catch (_) {
      // Silently ignore — M3U file already downloaded above
    }
  };

  const generateAndDownloadM3U = (videoUrl, fileName) => {
    try {
      const m3uContent = `#EXTM3U\n#EXTINF:-1,${fileName}\n${videoUrl}`;
      const blob = new Blob([m3uContent], { type: "audio/x-mpegurl" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${fileName}.m3u`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 100);
    } catch (error) {
      console.error("M3U generation failed:", error);
      // Fallback: direct download
      const a = document.createElement("a");
      a.href = videoUrl;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }
  };

  const handleMP4Download = async (id, name, quality) => {
    setLoading((prev) => ({ ...prev, [quality]: true }));
    try {
      const streamUrl = `${BASE}/dl/${id}/${encodeURIComponent(name)}`;
      const headRes = await fetch(streamUrl, { method: "HEAD" });
      const totalBytes = parseInt(headRes.headers.get("content-length") || "0");
      const chunkSize = 5 * 1024 * 1024;
      const chunks = [];
      let start = 0;
      while (start < totalBytes) {
        const end = Math.min(start + chunkSize - 1, totalBytes - 1);
        const res = await fetch(streamUrl, { headers: { Range: `bytes=${start}-${end}` } });
        const chunk = await res.arrayBuffer();
        chunks.push(chunk);
        start = end + 1;
      }
      const totalLength = chunks.reduce((sum, c) => sum + c.byteLength, 0);
      const combined = new Uint8Array(totalLength);
      let offset = 0;
      for (const chunk of chunks) {
        combined.set(new Uint8Array(chunk), offset);
        offset += chunk.byteLength;
      }
      const blob = new Blob([combined.buffer], { type: "video/mp4" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = name;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (error) {
      console.error("MP4 download failed:", error);
      const streamUrl = `${BASE}/dl/${id}/${encodeURIComponent(name)}`;
      const a = document.createElement("a");
      a.href = streamUrl;
      a.download = name;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }
    setLoading((prev) => ({ ...prev, [quality]: false }));
  };

  // Sort qualities by number of languages (prefer more languages)
  const sortQualitiesByLanguages = (qualities) => {
    if (!qualities) return [];
    return [...qualities].sort((a, b) => {
      const aLanguages = a.languages?.length || 0;
      const bLanguages = b.languages?.length || 0;
      return bLanguages - aLanguages; // Descending order (more languages first)
    });
  };

  // Format file size for display
  const formatFileSize = (bytes) => {
    if (!bytes) return '';
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    if (bytes < 1024 * 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
    return (bytes / (1024 * 1024 * 1024)).toFixed(1) + ' GB';
  };

  // Enhanced quality info component
  const QualityInfo = ({ quality }) => {
    const info = [];
    if (quality.codec) info.push(quality.codec.toUpperCase());
    if (quality.quality) info.push(quality.quality);
    if (quality.audio) info.push(quality.audio);
    if (quality.size) info.push(formatFileSize(quality.size));
    return info.join(' • ');
  };

  const renderMovieButtons = () =>
    sortQualitiesByLanguages(movieData.sources).map((q, i) => (
      <div key={i} className="flex flex-col gap-1">
        <Button
          onClick={() => handleButtonClick(q.id, q.name, q.quality)}
          size="sm"
          className="bg-projector text-ink rounded-[3px] font-semibold"
          isLoading={loading[q.quality]}
          spinner={<Spinner />}
        >
          {q.quality}
        </Button>
        <div className="font-mono text-[10px] text-bone/50 text-center">
          <QualityInfo quality={q} />
        </div>
      </div>
    ));

  const renderPCPlayerButtons = () =>
    sortQualitiesByLanguages(movieData.sources).map((q, i) => (
      <div key={i} className="flex flex-col gap-1 items-center">
        <span className="font-mono text-[10px] text-bone/60">{q.quality}</span>
        <div className="font-mono text-[10px] text-bone/60 text-center max-w-[4rem]">
          <QualityInfo quality={q} />
        </div>
        <div className="flex gap-1">
          <Button
            onClick={() => handleM3UDownload(q.id, q.name)}
            size="sm"
            className="bg-projector text-ink rounded-[3px] font-semibold min-w-[3.5rem]"
          >
            M3U
          </Button>
          <Button
            onClick={() => handleMP4Download(q.id, q.name, q.quality)}
            size="sm"
            className="bg-bone/[0.06] text-bone border border-bone/15 rounded-[3px] min-w-[3.5rem]"
            isLoading={loading[q.quality]}
            spinner={<Spinner />}
          >
            MP4
          </Button>
        </div>
      </div>
    ));

  const renderShowSelectors = () => (
    <div className="px-1 py-2 flex flex-col gap-2">
      <Select
        isRequired
        variant="bordered"
        aria-label="Select season"
        placeholder="Select season"
        className="w-40 mb-2"
        onChange={(e) => setSelectedSeason(e.target.value)}
        value={selectedSeason}
      >
        {(movieData.seasons || [])
          .sort((a, b) => a.season_number - b.season_number)
          .map((s) => (
            <SelectItem key={s.season_number} value={s.season_number}>
              Season {s.season_number}
            </SelectItem>
          ))}
      </Select>
      <Select
        isRequired
        variant="bordered"
        aria-label="Select episode"
        placeholder="Select episode"
        className="w-40 mb-2"
        onChange={(e) => setSelectedEpisode(e.target.value)}
        value={selectedEpisode}
        disabled={!selectedSeason}
      >
        {episodes
          .sort((a, b) => a.episode_number - b.episode_number)
          .map((e) => (
            <SelectItem key={e.episode_number} value={e.episode_number}>
              Episode {e.episode_number}
            </SelectItem>
          ))}
      </Select>
      <Select
        isRequired
        variant="bordered"
        aria-label="Select quality"
        placeholder="Select quality"
        className="w-40 mb-2"
        onChange={(e) => setSelectedQuality(e.target.value)}
        value={selectedQuality}
        disabled={!selectedEpisode}
      >
        {sortQualitiesByLanguages(qualities).map((q) => (
          <SelectItem key={q.quality} value={q.quality}>
            {q.quality}
          </SelectItem>
        ))}
      </Select>
      <Button
        onClick={() => {
          const q = qualities.find((q) => q.quality === selectedQuality);
          if (q) handleButtonClick(q.id, q.name, q.quality);
        }}
        size="sm"
        className="bg-primaryBtn rounded-full"
        disabled={!selectedQuality}
        isLoading={loading[selectedQuality]}
        spinner={<Spinner />}
      >
        {btnType === "Download" ? "Download" : btnType === "PC Player" ? "Open in PC Player" : "Open in Player"}
      </Button>
      {btnType === "PC Player" && selectedQuality && (
        <>
          <Button
            onClick={() => {
              const q = qualities.find((q) => q.quality === selectedQuality);
              if (q) handleM3UDownload(q.id, q.name);
            }}
            size="sm"
            className="bg-bone/[0.06] text-bone border border-bone/15 rounded-[3px]"
          >
            Get M3U
          </Button>
          <Button
            onClick={() => {
              const q = qualities.find((q) => q.quality === selectedQuality);
              if (q) handleMP4Download(q.id, q.name, q.quality);
            }}
            size="sm"
            className="bg-bone/[0.06] text-bone border border-bone/15 rounded-[3px]"
            isLoading={loading[selectedQuality]}
            spinner={<Spinner />}
          >
            Download MP4
          </Button>
        </>
      )}
    </div>
  );

  return (
    <Popover placement="bottom" showArrow={true}>
      <PopoverTrigger>
        <button className="flex justify-center items-center gap-2 text-projector hover:text-[#F0CA98] max-w-full grow text-xs font-bold rounded-[3px] border border-projector/45 hover:border-projector/70 hover:bg-projector/[0.06] transition-colors py-2 px-3 min-h-[44px] lg:text-sm sm:px-5 sm:max-w-[15rem]">
          {btnType === "Download" ? (
            <>
              <FaCloudDownloadAlt className="text-lg" /> Download
            </>
          ) : btnType === "PC Player" ? (
            <>
              <FaDesktop className="text-lg" /> PC Player
            </>
          ) : (
            <>
