}

export default function MoviesAndSeriesDetailsSections(props) {
  const [isWatchMoviePopupOpen, setIsWatchMoviePopupOpen] = useState(false);
  const [activeEpisode, setActiveEpisode] = useState(null);
  const [expandedAction, setExpandedAction] = useState({ episode: null, type: null });
  const playerWrapperRef = useRef(null);
  const moviePlayerRef = useRef(null);
  const episodeListRef = useRef(null);

  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedQuality, setSelectedQuality] = useState("");
  const episodesPerPage = 50;

  const isAnime = props.movieData.is_anime || false;
  const totalEpisodes = props.episodes?.length || 0;

  // Unique qualities from episodes.
  //
  // This previously skipped 480p/720p/1080p for series, so a season whose files
  // were all 1080p produced an empty quality list. QualityTab returns null when
  // that list is empty, which silently removed the entire download / Telegram /
  // subtitle block for most seasons. Series now surface every quality, ordered.
  const qualities = useMemo(() => {
    const qualitySet = new Set();
    const season = props.movieData.seasons?.find(
      (s) => s.season_number === props.seasonNumber
    );

    const addFrom = (sources) => {
      sources?.forEach((q) => {
        if (q?.quality) qualitySet.add(q.quality);
      });
    };

    props.episodes?.forEach((ep) => {
      const fullEps = season?.episodes?.find(
        (e) => e.episode_number === ep.episode_number
      );
      addFrom(fullEps?.sources);
    });

    // Movies (and series where the episode list is empty) read files directly
    // off the media document rather than per-episode sources.
    if (qualitySet.size === 0) {
      addFrom(props.movieData?.telegram);
    }

    return Array.from(qualitySet).sort((a, b) => {
      const order = { "480p": 1, "720p": 2, "1080p": 3, "2160p": 4 };
      return (order[a] || 99) - (order[b] || 99);
    });
  }, [props.episodes, props.movieData.seasons, props.movieData.telegram, props.seasonNumber]);

  const telegramByQuality = useMemo(() => {
    const grouped = {};
    qualities.forEach((q) => (grouped[q] = []));
    const season = props.movieData.seasons?.find((s) => s.season_number === props.seasonNumber);

    if (season?.episodes) {
      season.episodes.forEach((ep) => {
        ep.sources?.forEach((file) => {
          if (grouped[file.quality]) {
            grouped[file.quality].push({ ...file, episode_number: ep.episode_number, episode_title: ep.title || ep.name });
          }
        });
      });
    }

    // Movies keep their files on the media document, not on episodes.
    const hasFiles = Object.values(grouped).some((list) => list.length > 0);
    if (!hasFiles) {
      (props.movieData?.telegram || []).forEach((file) => {
        const quality = file?.quality;
        if (quality && grouped[quality]) grouped[quality].push({ ...file });
      });
    }

    return grouped;
  }, [qualities, props.movieData.seasons, props.movieData.telegram, props.seasonNumber]);

  const filteredEpisodes = useMemo(() => {
    if (!searchQuery) return props.episodes || [];
    const q = searchQuery.toLowerCase();
    return (props.episodes || []).filter(
      (ep) => (ep.title || "").toLowerCase().includes(q) || (ep.description || "").toLowerCase().includes(q) || ep.episode_number.toString().includes(q)
    );
  }, [props.episodes, searchQuery]);

  const paginatedEpisodes = useMemo(() => {
    const start = (currentPage - 1) * episodesPerPage;
    return filteredEpisodes.slice(start, start + episodesPerPage);
  }, [filteredEpisodes, currentPage, episodesPerPage]);

  const totalPages = Math.ceil(filteredEpisodes.length / episodesPerPage);

  const movieAudioTracks = useMemo(() => {
    if (props.movieData.sources?.[0]?.audio_tracks?.length > 0) {
      return props.movieData.sources[0].audio_tracks;
    }
    if (props.movieData.audio_tracks?.length > 0) {
      return props.movieData.audio_tracks;
    }
    if (props.movieData.languages?.length > 0) {
      return props.movieData.languages;
    }
    return [];
  }, [props.movieData]);

  const seriesAudioTracks = useMemo(() => {
    if (activeEpisode?.sources?.[0]?.audio_tracks?.length > 0) {
      return activeEpisode.sources[0].audio_tracks;
    }
    if (activeEpisode?.audio_tracks?.length > 0) {
      return activeEpisode.audio_tracks;
    }
    if (props.movieData.languages?.length > 0) {
      return props.movieData.languages;
    }
    return [];
  }, [activeEpisode, props.movieData.languages]);

  const handlePlayEpisode = useCallback((eps) => {
    const season = props.movieData.seasons?.find((s) => s.season_number === props.seasonNumber);
    const fullEpisode = season?.episodes?.find((ep) => ep.episode_number === eps.episode_number);
    setActiveEpisode(fullEpisode || eps);
    props.setEpisodeNumber(eps.episode_number);
    setTimeout(() => {
      playerWrapperRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 50);
  }, [props]);

  const handleSeasonChange = useCallback((sn) => {
    props.setSeasonNumber(sn);
    setActiveEpisode(null);
    setExpandedAction({ episode: null, type: null });
    setCurrentPage(1);
    setSearchQuery("");
  }, [props]);

  const toggleAction = useCallback((epNum, type) => {
    setExpandedAction((prev) =>
      prev.episode === epNum && prev.type === type ? { episode: null, type: null } : { episode: epNum, type }
    );
  }, []);

  const handleDownload = useCallback((q) => {
    const url = `${BASE}/dl/${q.id}/${encodeURIComponent(q.name)}`;
    const a = document.createElement("a");
    a.href = url; a.download = q.name;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
  }, []);

  const handleTelegram = useCallback((tmdbId, seasonNum, quality) => {
    window.open(`https://t.me/${USERNAME}?start=file_${tmdbId}_${seasonNum}_${quality}`, "_blank", "noopener noreferrer");
  }, []);

  const handleMxPlayer = useCallback((q) => {
    const url = `${BASE}/dl/${q.id}/${encodeURIComponent(q.name)}`;
    window.open(`intent:${url}#Intent;type=video/x-matroska;action=android.intent.action.VIEW;end;`, "_blank", "noopener,noreferrer");
  }, []);

  const handlePcPlayerM3U = useCallback((q) => {
    const isMobile = /Android|iPhone|iPad/i.test(navigator.userAgent);
    const streamUrl = `${BASE}/dl/${q.id}/${encodeURIComponent(q.name)}`;
    const safeName = q.name.replace(/[^a-zA-Z0-9]/g, "_");
    if (isMobile) {
      const a = document.createElement("a"); a.href = streamUrl; a.download = q.name;
      document.body.appendChild(a); a.click(); document.body.removeChild(a); return;
    }
    try {
      window.location.href = `vlc://${encodeURIComponent(streamUrl)}`;
      setTimeout(() => {
        if (document.hasFocus()) {
          const m3u = `#EXTM3U\n#EXTINF:-1,${safeName}\n${streamUrl}`;
          const blob = new Blob([m3u], { type: "audio/x-mpegurl" });
          const url = URL.createObjectURL(blob);
          const a = document.createElement("a"); a.href = url; a.download = `${safeName}.m3u`;
          document.body.appendChild(a); a.click(); document.body.removeChild(a);
          setTimeout(() => URL.revokeObjectURL(url), 100);
        }
      }, 1000);
    } catch {
      const m3u = `#EXTM3U\n#EXTINF:-1,${safeName}\n${streamUrl}`;
      const blob = new Blob([m3u], { type: "audio/x-mpegurl" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a"); a.href = url; a.download = `${safeName}.m3u`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 100);
    }
  }, []);

  const playerSources = activeEpisode?.sources?.length > 0
    ? activeEpisode.sources.map((q) => ({ src: mediaUrl(q), type: "video/mp4", size: parseQuality(q.quality) }))
    : [];
  const playerPoster = activeEpisode?.episode_backdrop || props.movieData?.backdrop || "";
  const playerFileId = activeEpisode?.sources?.[0]?.id || "";
  const playerFileName = activeEpisode?.sources?.[0]?.name || "";

  const hasPlayableSource =
    props.detailType === "movie"
      ? props.movieData.sources?.length > 0
      : totalEpisodes > 0;

  const mobileBarMeta =
    props.detailType === "movie"
      ? [
          props.movieData.release_year || props.movieData.year,
          props.movieData.runtime && `${props.movieData.runtime} min`,
          props.movieData.rip || props.movieData.quality,
        ]
          .filter(Boolean)
          .join(" · ")
      : activeEpisode
        ? `S${props.seasonNumber} · E${String(activeEpisode.episode_number).padStart(2, "0")}${
            activeEpisode.title ? ` · ${activeEpisode.title}` : ""
          }`
        : [
            props.movieData.total_seasons && `${props.movieData.total_seasons} seasons`,
            props.movieData.total_episodes && `${props.movieData.total_episodes} episodes`,
          ]
            .filter(Boolean)
            .join(" · ");

  const handleMobilePlay = () => {
    const target =
      props.detailType === "movie"
        ? moviePlayerRef
        : activeEpisode
          ? playerWrapperRef
          : episodeListRef;
    target.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  // ── RENDER ────────────────────────────────────────────────────────
  if (props.isMovieDataLoading) {
    return (
      <div className="mt-4">
        <DetailSkeleton />
      </div>
    );
  }

  return (
    <NextUIProvider>
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.4 }}
      className="mt-4 space-y-6"
    >
      {/* ── VIDEO PLAYER (SERIES) ───────────────────────────── */}
      {props.detailType === "series" && (
        <div
          ref={playerWrapperRef}
          id="cx-player"
          data-cx-player
          className="w-full scroll-mt-24"
        >
          {playerSources.length > 0 ? (
            <InlinePlayer
              key={playerFileId || "no-episode"}
              sources={playerSources}
              poster={playerPoster}
              fileId={playerFileId}
              fileName={playerFileName}
            />
          ) : (
            <div className="aspect-video w-full relative flex items-center justify-center bg-carbon rounded-[4px] overflow-hidden border border-bone/10">
              {props.movieData.backdrop && (
                <LazyLoadImage
                  src={backdropUrl(props.movieData.backdrop, 640)}
                  effect="black-and-white"
                  alt={props.movieData.title}
                  className="absolute inset-0 w-full h-full object-cover opacity-20 grayscale"
                />
              )}
              <div className="absolute inset-0 bg-gradient-to-t from-ink via-ink/40 to-transparent" />
              <div className="relative z-10 flex flex-col items-center text-center px-6">
                <span className="eyebrow mb-3">Screen one</span>
                <p className="font-display text-xl sm:text-2xl text-bone/90">
                  Pick an episode to start the screening
                </p>
                <p className="mt-2 max-w-sm text-[12px] sm:text-[13px] text-bone/50">
                  Episodes are listed below. Choose a season, then press play.
                </p>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ── VIDEO PLAYER (MOVIE) ────────────────────────────── */}
      {props.detailType === "movie" && (
        <div className="w-full scroll-mt-24" ref={moviePlayerRef}>
          {props.movieData.sources?.length > 0 ? (
            <InlinePlayer
              key={props.movieData.tmdb_id}
              sources={props.movieData.sources.map((q) => ({
                src: mediaUrl(q),
                type: "video/mp4",
                size: parseQuality(q.quality),
              }))}
              poster={props.movieData.backdrop || ""}
              fileId={props.movieData.sources[0]?.id || ""}
              fileName={props.movieData.sources[0]?.name || ""}
            />
          ) : (
            <div className="aspect-video w-full relative flex items-center justify-center bg-carbon rounded-[4px] overflow-hidden border border-bone/10">
              {props.movieData.backdrop && (
                <LazyLoadImage
                  src={backdropUrl(props.movieData.backdrop, 640)}
                  effect="black-and-white"
                  alt={props.movieData.title}
                  className="absolute inset-0 w-full h-full object-cover opacity-15 grayscale"
                />
              )}
              <div className="absolute inset-0 bg-gradient-to-t from-ink via-ink/40 to-transparent" />
              <div className="relative z-10 flex flex-col items-center text-center px-6">
                <span className="eyebrow mb-3">No print available</span>
                <p className="font-display text-xl sm:text-2xl text-bone/90">
                  This title hasn&rsquo;t been screened yet
                </p>
                <p className="mt-2 max-w-sm text-[12px] sm:text-[13px] text-bone/50">
                  The print is still being prepared. Join our Telegram channel and
                  we&rsquo;ll announce it the moment it&rsquo;s ready.
                </p>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ── MOVIE METADATA ──────────────────────────────────── */}
      {props.detailType === "movie" && (
        <motion.div
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.15 }}
          className="space-y-4"
        >
          {/* Genres */}
          {props.movieData.genres?.length > 0 && (
            <div className="flex flex-wrap gap-1.5">
              {props.movieData.genres.slice(0, 4).map((genre, i) => (
                <span key={i} className="genre-badge">{genre}</span>
              ))}
            </div>
          )}

          {/* Title */}
          <h1 className="font-display text-3xl sm:text-4xl md:text-5xl font-medium text-bone leading-[1.05] tracking-tight">
            {props.movieData.title}
          </h1>

          {/* Meta row */}
          <div className="flex flex-wrap items-center gap-1.5">
            {(props.movieData.rating || props.movieData.rate) && (
              <div className="rating-badge">
                <PiStarFill className="text-[10px] text-projector" />
                {Number(props.movieData.rating || props.movieData.rate).toFixed(1)}
              </div>
            )}
            {(props.movieData.release_year || props.movieData.year) && (
              <MetaBadge>{props.movieData.release_year || props.movieData.year}</MetaBadge>
            )}
            {props.movieData.runtime && (
              <MetaBadge><BiTime className="text-xs text-bone/50" />{props.movieData.runtime} min</MetaBadge>
            )}
            {(props.movieData.rip || props.movieData.quality) && (
              <MetaBadge className="!border-projector/30 !text-projector font-semibold">
                {props.movieData.rip || props.movieData.quality}
              </MetaBadge>
            )}
            {props.movieData.languages?.length > 0 && (
              <MetaBadge className="!bg-bone/8 !border-bone/15 !text-bone/85">
                <LuLanguages className="text-xs text-projector" />
                {props.movieData.languages.map(formatLangShort).join(" / ")}
              </MetaBadge>
            )}
          </div>

          {/* Description */}
          {props.movieData.description && (
            <p className="text-bone/65 text-sm md:text-base leading-relaxed max-w-3xl line-clamp-4">
              {props.movieData.description}
            </p>
          )}

          {/* Action buttons */}
          <div className="flex flex-wrap gap-2 pt-1">
            <TelegramButton movieData={props.movieData} />
            <DownloadButton movieData={props.movieData} btnType="Download" />
            <WatchlistButton
              item={{ ...props.movieData, media_type: "movie" }}
              variant="detail"
            />
            {props.movieData.sources?.length > 0 && (
              <>
                <button
                  onClick={() => handleMxPlayer(props.movieData.sources[0])}
                  className="flex items-center gap-2 px-4 py-2 bg-bone/5 border border-bone/10 rounded-[3px] text-bone/60 text-xs font-semibold hover:bg-bone/10 hover:text-bone transition-colors duration-200"
                >
                  <FaPlay className="text-xs" /> Player
                </button>
                <button
                  onClick={() => handlePcPlayerM3U(props.movieData.sources[0])}
                  className="flex items-center gap-2 px-4 py-2 bg-bone/5 border border-bone/10 rounded-[3px] text-bone/60 text-xs font-semibold hover:bg-bone/10 hover:text-bone transition-colors duration-200"
                >
                  <FaDesktop className="text-xs" /> PC Player
                </button>
              </>
            )}
          </div>

          {/* Cast */}
          {(props.movieData.cast?.length > 0 || props.movieData.crew?.length > 0) && (
            <CastSection cast={props.movieData.cast} crew={props.movieData.crew} />
          )}

          {/* Streaming Tip */}
          <div className="px-4 py-3.5 bg-projector/[0.06] border-l-2 border-projector/60 rounded-r-[3px] flex items-start gap-3">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-projector/80 flex-shrink-0 mt-0.5">
              <circle cx="12" cy="12" r="10" />
              <line x1="12" y1="16" x2="12" y2="12" />
              <line x1="12" y1="8" x2="12.01" y2="8" />
            </svg>
            <p className="text-[12px] md:text-[13px] text-bone/55 leading-relaxed">
              <span className="timecode text-[10px] uppercase tracking-[0.14em] text-projector mr-1.5">Streaming tip</span>
              If you can&rsquo;t stream smoothly or want to switch audio/subtitle tracks, use the{" "}
              <span className="text-bone/85 font-medium">Mobile Player</span> or{" "}
              <span className="text-bone/85 font-medium">PC Player</span> buttons for better performance and more options.
            </p>
          </div>
        </motion.div>
      )}

      {/* ── SERIES METADATA ─────────────────────────────────── */}
      {props.detailType === "series" && (
        <motion.div
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.15 }}
          className="space-y-3"
        >
          {/* Genres */}
          {props.movieData.genres?.length > 0 && (
            <div className="flex flex-wrap gap-1.5">
              {props.movieData.genres.map((g, i) => <span key={i} className="genre-badge">{g}</span>)}
            </div>
          )}
          {/* Title */}
          <h1 className="font-display text-3xl sm:text-4xl font-medium text-bone tracking-tight leading-[1.05]">
            {props.movieData.title}
          </h1>
          {/* Status + meta */}
          <div className="flex flex-wrap items-center gap-1.5">
            {props.movieData.status && (
              <span className="px-2 py-1 rounded-[2px] timecode text-[10px] uppercase tracking-[0.12em] font-semibold bg-projector/10 border border-projector/25 text-projector">
                {props.movieData.status}
              </span>
            )}
            {(props.movieData.rating || props.movieData.rate) && (
              <div className="rating-badge">
                <PiStarFill className="text-[10px] text-projector" />
                {Number(props.movieData.rating || props.movieData.rate).toFixed(1)}
              </div>
            )}
            {(props.movieData.release_year || props.movieData.year) && (
              <MetaBadge>{props.movieData.release_year || props.movieData.year}</MetaBadge>
            )}
            {props.movieData.total_seasons && (
              <MetaBadge><BsListStars className="text-xs text-bone/50" />{props.movieData.total_seasons} Seasons</MetaBadge>
            )}
            {props.movieData.total_episodes && (
              <MetaBadge>{props.movieData.total_episodes} Episodes</MetaBadge>
            )}
            {(props.movieData.rip || props.movieData.quality) && (
              <MetaBadge className="!border-projector/30 !text-projector font-semibold">
                {props.movieData.rip || props.movieData.quality}
              </MetaBadge>
            )}
            {props.movieData.languages?.length > 0 && (
              <MetaBadge className="!bg-bone/8 !border-bone/15 !text-bone/85">
                <LuLanguages className="text-xs text-projector" />
                {props.movieData.languages.map(formatLangShort).join(" / ")}
              </MetaBadge>
            )}
          </div>
          {/* Description */}
          {props.movieData.description && (
            <p className="text-bone/65 text-sm md:text-base leading-relaxed max-w-3xl line-clamp-3">
              {props.movieData.description}
            </p>
          )}
          {/* My List */}
          <div className="flex flex-wrap gap-2 pt-1">
            <WatchlistButton
              item={{ ...props.movieData, media_type: "tv" }}
              variant="detail"
            />
          </div>
        </motion.div>
      )}

      {/* ── SEASON TABS ─────────────────────────────────────── */}
      {props.detailType === "series" && props.movieData.seasons?.length > 0 && (
        <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">
          {props.movieData.seasons
            .filter((s) => s.season_number !== 0)
            .sort((a, b) => a.season_number - b.season_number)
            .map((season) => {
              const isActive = props.seasonNumber === season.season_number;
              return (
                <button
                  key={season.season_number}
                  onClick={() => handleSeasonChange(season.season_number)}
                  className={`
                    flex-shrink-0 px-3.5 py-2 rounded-[3px] timecode text-[10px] uppercase tracking-[0.1em] font-semibold
                    whitespace-nowrap transition-colors duration-200 border
                    ${isActive
                      ? "bg-projector border-projector text-ink"
                      : "bg-bone/5 border-bone/10 text-bone/55 hover:bg-bone/10 hover:text-bone"
                    }
                  `}
                >
                  Season {season.season_number}
                  {season.episode_count && <span className={`ml-1.5 ${isActive ? "text-ink/60" : "text-bone/55"}`}>({season.episode_count})</span>}
                </button>
              );
            })}
        </div>
      )}

      {/* ── EPISODE SEARCH ──────────────────────────────────── */}
      {props.detailType === "series" && totalEpisodes > 10 && (
        <div className="relative">
          <FiSearch className="absolute left-3.5 top-1/2 -translate-y-1/2 text-bone/60 text-sm z-10" />
          <input
            type="text"
            placeholder="Search episodes by title or number…"
            value={searchQuery}
            onChange={(e) => { setSearchQuery(e.target.value); setCurrentPage(1); }}
            className="w-full sm:w-80 pl-10 pr-4 py-2.5 rounded-[3px] border border-bone/10 text-bone text-sm placeholder-bone/35 focus:outline-none focus:border-projector/60 transition-colors duration-200"
            autoComplete="off"
          />
        </div>
      )}

      {/* ── QUALITY TABS (SERIES) ────────────────────────────── */}
      {props.detailType === "series" && qualities.length > 0 && (
        <QualityTab
          qualities={qualities}
          selectedQuality={selectedQuality}
          setSelectedQuality={setSelectedQuality}
          telegramByQuality={telegramByQuality}
          tmdbId={props.movieData.tmdb_id}
          seasonNumber={props.seasonNumber}
          episodeNumber={activeEpisode?.episode_number}
          db_index={props.movieData.db_index}
        />
      )}

      {/* ── UPCOMING EPISODE ────────────────────────────────── */}
      {props.detailType === "series" && props.movieData.next_episode_to_air && (
        <UpcomingEpisodeCard episode={props.movieData.next_episode_to_air} />
      )}

      {/* ── CAST (SERIES) ───────────────────────────────────── */}
      {props.detailType === "series" &&
        (props.movieData.cast?.length > 0 || props.movieData.crew?.length > 0) && (
          <CastSection cast={props.movieData.cast} crew={props.movieData.crew} />
        )}

      {/* ── STREAMING TIP (SERIES) ──────────────────────────── */}
      {props.detailType === "series" && (
        <div className="px-4 py-3.5 bg-projector/[0.06] border-l-2 border-projector/60 rounded-r-[3px] flex items-start gap-3">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-projector/80 flex-shrink-0 mt-0.5">
            <circle cx="12" cy="12" r="10" />
            <line x1="12" y1="16" x2="12" y2="12" />
            <line x1="12" y1="8" x2="12.01" y2="8" />
          </svg>
          <p className="text-[12px] md:text-[13px] text-bone/55 leading-relaxed">
            <span className="timecode text-[10px] uppercase tracking-[0.14em] text-projector mr-1.5">Streaming tip</span>
            If you can&rsquo;t stream smoothly or want to switch audio/subtitle tracks, use the{" "}
            <span className="text-bone/85 font-medium">Mobile Player</span> or{" "}
            <span className="text-bone/85 font-medium">PC Player</span> buttons for better performance and more options.
          </p>
        </div>
      )}


      {/* ── EPISODE LIST ────────────────────────────────────── */}
      {props.detailType === "series" && (
        <div className="space-y-2 scroll-mt-24" ref={episodeListRef}>
          {/* List header */}
          <div className="flex items-end justify-between gap-4 border-b border-bone/10 pb-3 mb-4">
            <div>
              <span className="eyebrow mb-2">Programme</span>
              <h2 className="section-title text-xl md:text-2xl leading-none">Episodes</h2>
            </div>
            {filteredEpisodes.length > 0 && (
              <span className="timecode text-[10px] text-bone/60">
                {filteredEpisodes.length} total
              </span>
            )}
          </div>

          {props.isEpisodesLoading ? (
            <div className="flex justify-center py-16">
              <div className="loader-episode" />
            </div>
          ) : paginatedEpisodes.length === 0 ? (
            <div className="py-12 text-center">
              <p className="text-bone/60 text-sm">No episodes found{searchQuery ? ` for "${searchQuery}"` : ""}.</p>
            </div>
          ) : (
            paginatedEpisodes
              .sort((a, b) => a.episode_number - b.episode_number)
              .map((eps) => {
                const isActive = activeEpisode?.episode_number === eps.episode_number;
                const isDownloadOpen = expandedAction.episode === eps.episode_number && expandedAction.type === "download";
                const isTelegramOpen = expandedAction.episode === eps.episode_number && expandedAction.type === "telegram";
                const isMxPlayerOpen = expandedAction.episode === eps.episode_number && expandedAction.type === "mxplayer";
                const isPcPlayerOpen = expandedAction.episode === eps.episode_number && expandedAction.type === "pcplayer";
                const season = props.movieData.seasons?.find((s) => s.season_number === props.seasonNumber);
                const fullEps = season?.episodes?.find((ep) => ep.episode_number === eps.episode_number) || eps;
                const hasVideo = fullEps.sources?.length > 0;

                return (
                  <div key={eps.episode_number}>
                    <motion.div
                      initial={{ opacity: 0, y: 4 }}
                      animate={{ opacity: 1, y: 0 }}
                      className={`
                        flex items-start gap-3 p-3 sm:p-4 rounded-[4px] border transition-colors duration-200 cursor-default
                        ${isActive
                          ? "bg-projector/[0.07] border-projector/25"
                          : "bg-bone/[0.03] border-bone/8 hover:bg-bone/[0.06] hover:border-bone/15"
                        }
                      `}
                    >
                      {/* Thumbnail / Episode number */}
                      <div className="flex-shrink-0 relative w-20 h-12 sm:w-28 sm:h-16 rounded-[3px] overflow-hidden bg-carbon flex items-center justify-center">
                        {eps.episode_backdrop ? (
                          <>
                            <img src={eps.episode_backdrop} alt={eps.title} className="w-full h-full object-cover" />
                            {isActive && (
                              <div className="absolute inset-0 bg-ink/55 flex items-center justify-center">
                                <BsPlayFill className="text-projector text-xl" />
                              </div>
                            )}
                          </>
                        ) : (
                          <span className="timecode text-xl sm:text-2xl font-black text-bone/50">
                            {String(eps.episode_number).padStart(2, "0")}
                          </span>
                        )}
                        {!hasVideo && (
                          <div className="absolute top-1 right-1 w-1.5 h-1.5 rounded-full bg-bone/25" title="No video" />
                        )}
                      </div>

                      {/* Info + Actions */}
                      <div className="flex-1 min-w-0 space-y-1.5">
                        <div className="flex items-start justify-between gap-2">
                          <div className="min-w-0">
                            <h3 className="text-bone text-xs sm:text-sm font-semibold line-clamp-1">
                              <span className="timecode text-bone/55 mr-1.5">E{String(eps.episode_number).padStart(2, "0")}</span>
                              {eps.title}
                            </h3>
                            {(eps.description || eps.overview) && (
                              <p className="text-bone/60 text-xs line-clamp-2 mt-0.5 hidden sm:block leading-relaxed">
                                {eps.description || eps.overview}
                              </p>
                            )}
                          </div>
                        </div>

                        {/* Action buttons */}
                        <div className="flex flex-wrap items-center gap-1.5">
                          <EpisodeActionBtn
                            icon={BsPlayFill}
                            label="Play"
                            onClick={() => handlePlayEpisode(eps)}
                            active={isActive}
                            className="bg-projector border-projector !text-ink hover:bg-[#F0CA98] hover:border-[#F0CA98]"
                          />
                          {hasVideo && (
                            <>
                              <EpisodeActionBtn icon={FaCloudDownloadAlt} label="Download" active={isDownloadOpen} onClick={() => toggleAction(eps.episode_number, "download")} />
                              <EpisodeActionBtn icon={PiTelegramLogo} label="Telegram" active={isTelegramOpen} onClick={() => toggleAction(eps.episode_number, "telegram")} />
                              <EpisodeActionBtn icon={FaPlay} label="Player" active={isMxPlayerOpen} onClick={() => toggleAction(eps.episode_number, "mxplayer")} />
                              <EpisodeActionBtn icon={FaDesktop} label="PC" active={isPcPlayerOpen} onClick={() => toggleAction(eps.episode_number, "pcplayer")} />
                            </>
                          )}
                        </div>
                      </div>
                    </motion.div>

                    {/* Expanded quality row */}
                    <AnimatePresence>
                      {(isDownloadOpen || isTelegramOpen || isMxPlayerOpen || isPcPlayerOpen) && fullEps.sources?.length > 0 && (
                        <motion.div
                          initial={{ height: 0, opacity: 0 }}
                          animate={{ height: "auto", opacity: 1 }}
                          exit={{ height: 0, opacity: 0 }}
                          transition={{ duration: 0.2 }}
                          className="overflow-hidden"
                        >
                          <div className="flex flex-wrap gap-2 px-4 py-3 bg-bone/[0.03] rounded-b-[4px] border-x border-b border-bone/8 -mt-1">
                            {fullEps.sources.map((q, idx) => {
                              if (isPcPlayerOpen) {
                                return (
                                  <div key={idx} className="flex items-center gap-1.5">
                                    <span className="timecode text-[10px] text-bone/60 font-medium">{q.quality}</span>
                                    <button onClick={() => handlePcPlayerM3U(q)} className="px-2.5 py-1 rounded-[2px] bg-projector text-ink text-[10px] font-bold hover:bg-[#F0CA98] transition-colors">M3U</button>
                                  </div>
                                );
                              }
                              return (
                                <QualityPill
                                  key={idx}
                                  quality={q.quality}
                                  onClick={() => {
                                    if (isDownloadOpen) handleDownload(q);
                                    else if (isTelegramOpen) handleTelegram(props.movieData.tmdb_id, props.seasonNumber, q.quality);
                                    else if (isMxPlayerOpen) handleMxPlayer(q);
                                  }}
                                />
                              );
                            })}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                );
              })
          )}

          {/* Episode pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-center gap-2 mt-4 pt-4 border-t border-bone/8">
              <button
                onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="flex items-center gap-1 px-3 py-1.5 rounded-[3px] bg-bone/5 border border-bone/10 text-bone/60 text-xs font-semibold disabled:opacity-30 hover:bg-bone/10 hover:text-bone transition-colors duration-200 disabled:cursor-not-allowed"
              >
                <HiChevronLeft className="text-sm" /> Prev
              </button>
              <span className="timecode text-[10px] text-bone/60">Page {currentPage} / {totalPages}</span>
              <button
                onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="flex items-center gap-1 px-3 py-1.5 rounded-[3px] bg-bone/5 border border-bone/10 text-bone/60 text-xs font-semibold disabled:opacity-30 hover:bg-bone/10 hover:text-bone transition-colors duration-200 disabled:cursor-not-allowed"
              >
                Next <HiChevronRight className="text-sm" />
              </button>
            </div>
          )}
        </div>
      )}

      {/* Watch Movie Popup */}
      {props.detailType === "movie" && (
        <Watch
          isWatchMoviePopupOpen={isWatchMoviePopupOpen}
          id={props.movieData}
          setIsWatchMoviePopupOpen={setIsWatchMoviePopupOpen}
          popUpType="movie"
        />
      )}

      {!props.isMovieDataLoading && hasPlayableSource && (
        <MobilePlayBar
          title={props.movieData.title || "Now screening"}
          meta={mobileBarMeta}
          label={
            props.detailType === "movie"
              ? "Play"
              : activeEpisode
                ? "Play episode"
                : "Pick episode"
          }
          onPlay={handleMobilePlay}
        />
      )}
    </motion.div>
    </NextUIProvider>
  );
}

import React from "react";
import { motion } from "framer-motion";
import MovieCard from "./MovieCard";
import MovieCardSkeleton from "./MovieCardSkeleton";
import EmptyState, { RetryButton } from "./EmptyState";
import useOnlineStatus from "../hooks/useOnlineStatus";
import { HiOutlineAdjustmentsHorizontal } from "react-icons/hi2";
import { FiFilm, FiWifiOff } from "react-icons/fi";

const FILTER_OPTIONS = [
  { name: "Latest", value: "updated_on" },
  { name: "Top Rated", value: "rating" },
  { name: "Newest", value: "release_year" },
];

export default function MoviesAndSeriesSections(props) {
  const online = useOnlineStatus();
  const items = props.movieData || [];

  return (
    <div>
      {/* Section Header + Filters */}
      <div className="mt-8 mb-6">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          {/* Title */}
          <div className="flex items-center gap-3">
            <div className="w-px h-7 bg-projector shrink-0" />
            <h1 className="section-title text-lg sm:text-xl md:text-2xl tracking-tight capitalize">
              {props.sectionTitle}
            </h1>
          </div>

          {/* Filters */}
          {(props.dataType === "movies" || props.dataType === "series") && (
            <div className="flex items-center gap-2">
              <HiOutlineAdjustmentsHorizontal className="text-bone/60 text-lg shrink-0" />
              <div className="flex items-center gap-1.5 bg-bone/5 border border-bone/10 rounded-[3px] p-1">
                {FILTER_OPTIONS.map((item) => {
                  const isActive = item.value === props.movieFilterVal;
                  return (
                    <button
                      key={item.value}
                      onClick={() => {
                        props.setMovieFilterVal(item.value);
                        props.setMovieFilter(item.value);
                      }}
                      className={`
                        relative px-3 sm:px-4 py-1.5 rounded-[3px] text-xs sm:text-sm font-semibold
                        transition-all duration-200 whitespace-nowrap
                        ${isActive
                          ? "text-ink"
                          : "text-bone/50 hover:text-bone/80"
                        }
                      `}
                    >
                      {isActive && (
                        <motion.div
                          layoutId="filterPill"
                          className="absolute inset-0 bg-projector rounded-[3px]"
                          style={{ zIndex: -1 }}
                          transition={{ type: "spring", stiffness: 500, damping: 40 }}
                        />
                      )}
                      {item.name}
                    </button>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* Divider */}
        <div className="mt-4 h-px bg-gradient-to-r from-projector/20 via-bone/5 to-transparent" />
      </div>

      {/* Grid of cards */}
      {!props.isMovieDataLoading ? (
        items.length === 0 ? (
          <EmptyState
            icon={online ? FiFilm : FiWifiOff}
            eyebrow={
              !online ? "Signal lost" : props.error ? "Projection interrupted" : "House lights"
            }
            title={
              !online
                ? "You're offline"
                : props.error
                  ? "We lost the feed"
                  : "This shelf is still being stocked"
            }
            description={
              !online
                ? "This shelf hasn't been cached yet. Reconnect to load the latest arrivals."
                : props.error
                  ? "The archive didn't answer in time. Give it another reel."
                  : "Nothing is screening here yet — check back after the next reel is loaded."
            }
            action={
              !online ? (
                <RetryButton
                  onClick={() => window.location.reload()}
                  label="Reload shelf"
                />
              ) : props.error && props.onRetry ? (
                <RetryButton onClick={props.onRetry} label="Retry shelf" />
              ) : null
            }
          />
        ) : (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
            className="grid gap-x-2 sm:gap-x-3 gap-y-6 grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-7"
          >
            {items.map((movie, index) => (
              <motion.div
                /* Index keys made React reuse the wrong card when the filter or
                   page changed — poster and links briefly belonged to a
                   different title. Key on identity instead. */
                key={`${movie.media_type ?? "m"}:${movie.tmdb_id ?? movie._id ?? index}`}
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: Math.min(index * 0.03, 0.5) }}
              >
                <MovieCard movie={movie} />
              </motion.div>
            ))}
          </motion.div>
        )
      ) : (
        <MovieCardSkeleton count={20} />
      )}
    </div>
  );
}

import React, { useEffect, useState, useRef, useCallback } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { LazyLoadImage } from "react-lazy-load-image-component";
import "react-lazy-load-image-component/src/effects/black-and-white.css";
import { BASE_URL as BASE, SITENAME } from "../config";

import { FiSearch, FiX, FiTrendingUp, FiClock } from "react-icons/fi";
import { BiStar } from "react-icons/bi";
import { PiTelevisionSimple, PiHeartStraight, PiHouseSimple, PiFilmStrip, PiSparkle } from "react-icons/pi";
import posterPlaceholder from "../assets/images/poster-placeholder.png";
import { posterUrl } from "../utils/imageUrl";
import useHapticFeedback from "../hooks/useHapticFeedback";
import { getWatchlist, subscribeWatchlist } from "../utils/watchlist";
import MobileDock from "./MobileDock";

/*
 * One icon family for the whole dock.
 *
 * These five previously came from four different libraries — BiHomeAlt2
 * (Bootstrap, filled), TbMovie (Tabler), PiTelevisionSimple (Phosphor),
 * MdLocalFireDepartment (Material, filled) and PiHeartStraight (Phosphor).
 * Mixing filled and outline glyphs at the same px size means the optical
 * weights can never match: the filled ones read heavy and the outline ones read
 * thin, which is what made the bar look amateur regardless of spacing.
 *
 * All five are now Phosphor, matched to a single 1.5 stroke weight. The glyphs
 * also carry more meaning than before: a film strip for Movies, a screen for
 * Series, a sparkle for Anime, and a simple house for Home (PiHouseSimple is
 * lighter than the old filled BiHomeAlt2, so it sits with the rest).
 */
const NAV_ITEMS = [
  { icon: PiHouseSimple, name: "Home", path: "/" },
  { icon: PiFilmStrip, name: "Movies", path: "/Movies" },
  { icon: PiTelevisionSimple, name: "Series", path: "/Series" },
  { icon: PiSparkle, name: "Anime", path: "/anime" },
  { icon: PiHeartStraight, name: "K-Drama", path: "/k-drama" },
];

const TRENDING_SUGGESTIONS = ["Oppenheimer", "Dune", "The Bear", "Spider-Man", "Barbie"];

/**
 * Ratings arrive from the API as either a number or a string depending on the
 * document ("8.4" vs 8.4). Calling `rating.toFixed(1)` on the string threw
 * `TypeError`, and because the throw happened inside the search-results render
 * it took down the whole app — no error boundary existed at the time.
 */
function formatRating(rating) {
  if (rating === null || rating === undefined || rating === "") return null;
  const value = Number(rating);
  if (!Number.isFinite(value)) return null;
  return value.toFixed(1);
}

// ─── Stable components defined OUTSIDE Nav so React doesn't remount them ──────

const DesktopResultItem = React.memo(({ result, onClickResult }) => (
  <button
    type="button"
    onMouseDown={(e) => e.preventDefault()} // prevent input blur / outside-click handler
    onClick={() => onClickResult(result)}
    className="flex items-center w-full gap-3 transition-colors duration-150 hover:bg-bone/5 active:bg-bone/10 py-2.5 px-4 border-b border-bone/5 last:border-0 group cursor-pointer text-left"
  >
    <div className="flex-shrink-0 w-11 h-16 rounded-[3px] overflow-hidden bg-bone/10">
      <LazyLoadImage
        alt={result.title}
        src={posterUrl(result.poster || posterPlaceholder, 44)}
        effect="black-and-white"
        className="object-cover w-full h-full"
      />
    </div>
    <div className="flex-1 min-w-0">
      <p className="line-clamp-1 text-sm font-semibold text-bone group-hover:text-projector transition-colors">
        {result.title}
      </p>
      <div className="flex items-center gap-2 mt-1 flex-wrap">
        <span className="timecode text-[10px] uppercase tracking-[0.12em] px-1.5 py-0.5 rounded-[2px] bg-bone/8 text-bone/55">
          {result.media_type === "tv" ? "Series" : "Movie"}
        </span>
        {formatRating(result.rating) && (
          <span className="flex items-center gap-0.5 text-[10px] text-projector font-medium timecode">
            <BiStar />
            {formatRating(result.rating)}
          </span>
        )}
        {result.release_year && (
          <span className="text-bone-subtle text-[10px] timecode">{result.release_year}</span>
        )}
      </div>
    </div>
    <svg
      width="10"
      height="10"
      viewBox="0 0 10 10"
      fill="none"
      className="text-bone/50 group-hover:text-projector/70 transition-colors shrink-0"
    >
      <path
        d="M2 5h6M5 2l3 3-3 3"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  </button>
));

const MobileResultItem = React.memo(({ result, onClickResult }) => (
  <button
    type="button"
    onClick={() => onClickResult(result)}
    className="flex items-center w-full gap-3 p-3 bg-bone/5 rounded-[4px] border border-bone/8 hover:bg-bone/8 hover:border-bone/15 active:scale-[0.99] transition-all duration-150 cursor-pointer text-left"
  >
    <div className="flex-shrink-0 w-14 h-20 rounded-[3px] overflow-hidden bg-bone/10">
      <LazyLoadImage
        alt={result.title}
        src={result.poster || posterPlaceholder}
        effect="black-and-white"
        className="object-cover w-full h-full"
      />
    </div>
    <div className="flex-1 min-w-0">
      <p className="line-clamp-2 text-sm font-semibold text-bone leading-tight">
        {result.title}
      </p>
      <div className="flex items-center gap-2 mt-1.5 flex-wrap">
        <span className="timecode text-[10px] uppercase tracking-[0.12em] px-1.5 py-0.5 rounded-[2px] bg-bone/8 text-bone/55">
          {result.media_type === "tv" ? "Series" : "Movie"}
        </span>
        {formatRating(result.rating) && (
          <span className="flex items-center gap-0.5 text-[10px] text-projector font-medium timecode">
            <BiStar />
            {formatRating(result.rating)}
          </span>
        )}
        {result.release_year && (
          <span className="text-bone-subtle text-[10px] timecode">{result.release_year}</span>
        )}
      </div>
      {result.overview && (
        <p className="text-[11px] text-bone/55 line-clamp-1 mt-1">{result.overview}</p>
      )}
    </div>
  </button>
));

// ─────────────────────────────────────────────────────────────────────────────

export default function Nav() {
  const [query, setQuery] = useState("");
  const [debouncedVal, setDebouncedVal] = useState("");
  const [searchResult, setSearchResult] = useState([]);
  const [scrolled, setScrolled] = useState(false);
  const [isMobileSearchOpen, setIsMobileSearchOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [searchError, setSearchError] = useState(false);
  const [navStatus, setNavStatus] = useState("Home");
  const [recentSearches, setRecentSearches] = useState([]);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [watchlistCount, setWatchlistCount] = useState(0);

  const location = useLocation();
  const navigate = useNavigate();
  // `navigation` haptics moved into MobileDock along with the dock markup.
  const { selection: hapticSelection } = useHapticFeedback();
  const searchRef = useRef(null);
  const mobileInputRef = useRef(null);
  const mobileOverlayRef = useRef(null);
  // Track mobile-search state in a ref so the pointerdown handler (which closes
  // on stale closures) can read the current value without re-registering.
  const isMobileSearchOpenRef = useRef(false);

  useEffect(() => {
    isMobileSearchOpenRef.current = isMobileSearchOpen;
  }, [isMobileSearchOpen]);

  // Load recent searches
  useEffect(() => {
    try {
      const saved = localStorage.getItem("fc_recent_searches");
      if (saved) setRecentSearches(JSON.parse(saved));
    } catch (e) {}
  }, []);

  // Keep the My List badge in sync with hearts anywhere on the page
  useEffect(() => {
    const sync = () => setWatchlistCount(getWatchlist().length);
    sync();
    return subscribeWatchlist(sync);
  }, []);

  const saveRecentSearch = useCallback((term) => {
    if (!term.trim()) return;
    setRecentSearches((prev) => {
      const updated = [term, ...prev.filter((s) => s !== term)].slice(0, 6);
      try { localStorage.setItem("fc_recent_searches", JSON.stringify(updated)); } catch (e) {}
      return updated;
    });
  }, []);

  // Scroll effect
  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // Active nav tracking.
  //
  // The old version tested `path.startsWith("/ser")`, which also matches
  // `/search/...` — so the Series tab lit up on search results. It also missed
  // /top-rated-*, /most-viewed, /genre/*, /my-list and /Cast/* entirely, which
  // left the dock with no active item on those pages. Use an explicit,
  // longest-match-first prefix map instead.
  useEffect(() => {
    const path = location.pathname;
    const ROUTE_TAB = [
      ["/mov/", "Movies"],
      ["/Movies", "Movies"],
      ["/top-rated-movies", "Movies"],
      ["/most-viewed", "Movies"],
      ["/genre/movie", "Movies"],
      ["/similarMov/", "Movies"],
      ["/ser/", "Series"],
      ["/Series", "Series"],
      ["/top-rated-series", "Series"],
      ["/genre/tv", "Series"],
      ["/similarSeries/", "Series"],
      ["/anime", "Anime"],
      ["/k-drama", "K-Drama"],
    ];
    if (path === "/") {
      setNavStatus("Home");
      return;
    }
    const hit = ROUTE_TAB.find(
      ([prefix]) => path === prefix || path.startsWith(prefix)
    );
    setNavStatus(hit ? hit[1] : "");
  }, [location.pathname]);

  // Fetch search results
  useEffect(() => {
    // Clearing the query mid-flight used to leave `isLoading` true forever,
    // which showed an endless "Searching…" spinner.
    if (!debouncedVal) {
      setSearchResult([]);
      setIsLoading(false);
      setSearchError(false);
      return undefined;
    }
    const ctrl = new AbortController();
    setIsLoading(true);
    setSearchError(false);
    fetch(`${BASE}/api/search/?query=${encodeURIComponent(debouncedVal)}&page=1`, {
      signal: ctrl.signal,
    })
      .then((r) => {
        if (!r.ok) throw new Error(`Search failed (${r.status})`);
        return r.json();
      })
      .then((data) => {
        setSearchResult(data.results || []);
        setIsLoading(false);
      })
      .catch((err) => {
        if (err.name === "AbortError") return;
        // Surface the failure instead of showing "No results", which used to
        // make a backend outage look like an empty catalogue.
        setSearchResult([]);
        setSearchError(true);
        setIsLoading(false);
      });
    return () => ctrl.abort();
  }, [debouncedVal]);

  // Debounce
  useEffect(() => {
    const t = setTimeout(() => setDebouncedVal(query), 250);
    return () => clearTimeout(t);
  }, [query]);

  // Outside-click closes the DESKTOP dropdown only.
  // IMPORTANT: skip completely when the mobile search overlay is open so we
  // don't accidentally clear results when the user taps a result card.
  useEffect(() => {
    const handler = (e) => {
      // If mobile search is open, never interfere — the mobile overlay handles itself.
      if (isMobileSearchOpenRef.current) return;
      if (searchRef.current && !searchRef.current.contains(e.target)) {
        setDropdownOpen(false);
        setDebouncedVal("");
        setSearchResult([]);
        setQuery("");
      }
    };
    document.addEventListener("pointerdown", handler);
    return () => document.removeEventListener("pointerdown", handler);
  }, []);

  // Auto-focus mobile input
  useEffect(() => {
    if (isMobileSearchOpen && mobileInputRef.current) {
      setTimeout(() => mobileInputRef.current?.focus(), 120);
    }
  }, [isMobileSearchOpen]);

  /*
   * Mobile search overlay: scroll lock + dialog keyboard behaviour.
   *
   * Two bugs lived here.
   * 1. The lock wrote `document.body.style.overflow = "hidden"` and only undid it
   *    in the effect cleanup. The overlay is also hidden by a `hidden` utility
   *    above md, so when a phone-width overlay was open and the viewport was
   *    widened past md, the overlay disappeared from the layout *without*
   *    `isMobileSearchOpen` changing — the lock stayed applied and the page
   *    could never scroll again. The lock is now released whenever the overlay
   *    is not actually on screen, and re-checked on resize.
   * 2. It was not a dialog: no role, no aria-modal, no Escape, no focus trap,
   *    so keyboard and screen-reader users could tab straight out of the
   *    "modal" into the page behind it.
   */
  useEffect(() => {
    if (!isMobileSearchOpen) return undefined;

    const overlay = mobileOverlayRef.current;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    const releaseIfOffscreen = () => {
      // Once the overlay is display:none (>= md, or closed), the lock must go.
      const visible = overlay && overlay.offsetParent !== null;
      if (!visible) document.body.style.overflow = previousOverflow || "";
    };
    window.addEventListener("resize", releaseIfOffscreen);
    releaseIfOffscreen();

    return () => {
      window.removeEventListener("resize", releaseIfOffscreen);
      document.body.style.overflow = previousOverflow || "";
    };
  }, [isMobileSearchOpen]);

  // Escape closes the overlay; Tab is trapped inside it while open.
  useEffect(() => {
    if (!isMobileSearchOpen) return undefined;

    const onKeyDown = (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        setIsMobileSearchOpen(false);
        return;
      }
      if (e.key !== "Tab") return;

      const root = mobileOverlayRef.current;
      if (!root) return;
      const focusables = root.querySelectorAll(
        'a[href], button:not([disabled]), input, textarea, select, [tabindex]:not([tabindex="-1"])'
      );
      if (focusables.length === 0) return;
      const first = focusables[0];
      const last = focusables[focusables.length - 1];

      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    };

    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [isMobileSearchOpen]);

  const clearSearch = useCallback(() => {
    setQuery("");
    setDebouncedVal("");
    setSearchResult([]);
    setDropdownOpen(false);
  }, []);

  // ── Desktop result click ──────────────────────────────────────────────────
  const handleDesktopResultClick = useCallback((result) => {
    const path = result.media_type === "movie"
      ? `/mov/${result.tmdb_id}`
      : `/ser/${result.tmdb_id}`;
    saveRecentSearch(result.title);
    // Navigate FIRST, then clean up — avoids race with dropdown closing
    navigate(path);
    clearSearch();
  }, [navigate, clearSearch, saveRecentSearch]);

  // ── Mobile result click ───────────────────────────────────────────────────
  const handleMobileResultClick = useCallback((result) => {
    const path = result.media_type === "movie"
      ? `/mov/${result.tmdb_id}`
      : `/ser/${result.tmdb_id}`;
    saveRecentSearch(result.title);
    // Navigate FIRST so it isn't swallowed by unmount
    navigate(path);
    // Close overlay after navigation is queued
    setIsMobileSearchOpen(false);
    clearSearch();
  }, [navigate, clearSearch, saveRecentSearch]);

  const handleSeeAll = useCallback(() => {
    const term = debouncedVal;
    navigate(`/search/${term}`);
    clearSearch();
  }, [debouncedVal, navigate, clearSearch]);

  const handleMobileSeeAll = useCallback(() => {
    const term = debouncedVal;
    navigate(`/search/${term}`);
    setIsMobileSearchOpen(false);
    clearSearch();
  }, [debouncedVal, navigate, clearSearch]);

  return (
    <>
      {/* ── TOP NAV BAR ── */}
      <div
        className={`
          fixed top-0 left-0 right-0 z-50
          flex items-center justify-between gap-3
          pt-[calc(var(--safe-top)+0.75rem)] pb-3 px-4
          md:pt-[calc(var(--safe-top)+1rem)] md:pb-4 md:px-8 lg:px-12
          text-bone transition-all duration-300 ease-in-out
          ${scrolled
            ? "bg-ink/95 backdrop-blur-xl shadow-[0_4px_30px_rgba(0,0,0,0.6)] border-b border-bone/8"
            : "cx-nav-scrim"
          }
        `}
      >
        {/* Logo */}
        <Link
          to="/"
          className="flex items-center gap-2 shrink-0 hover:opacity-90 transition-opacity duration-200"
          onClick={() => setNavStatus("Home")}
        >
          {/* CloudXMovies brand mark */}
          <svg width="26" height="26" viewBox="0 0 26 26" fill="none" xmlns="http://www.w3.org/2000/svg" className="shrink-0">
            <defs>
              <linearGradient id="navBrand" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#F0CA98" />
                <stop offset="100%" stopColor="#D9A65C" />
              </linearGradient>
            </defs>
            <path d="M5,9 C5,5.5 7.5,3 11,3.5 C12.5,2 15,1.5 17,3 C19.5,3 21,5 21,7.5 C23,8.5 24,10.5 23,13 C22,15.5 19.5,16 17,16 L9,16 C6.5,16 4,14 4,11.5 C4,10 4.5,9.2 5,9 Z" fill="url(#navBrand)" opacity="0.95"/>
            <path d="M8,19 L18,19 M10,22 L16,22" stroke="url(#navBrand)" strokeWidth="2" strokeLinecap="round" opacity="0.7"/>
          </svg>
          <span className="font-extrabold text-lg md:text-xl tracking-tight">
            <span style={{ background: 'linear-gradient(135deg, #F0CA98, #D9A65C)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text' }}>CloudX</span><span className="text-bone">Movies</span>
          </span>
        </Link>

        {/* Desktop nav links.
            Gated on `navlg` (990px), not `md` (700px): the full desktop header
            needs ~990px for the logo + five icon+label links + My List + the
            search field, so switching at 700px squeezed the nav into the input
            anywhere from 700–990px. `navlg` is a dedicated breakpoint so none of
            the app's other `md:` utilities reflow. */}
        <nav className="hidden navlg:flex items-center gap-1">
          {NAV_ITEMS.map((item) => {
            const isActive = navStatus === item.name;
            return (
              <Link
                key={item.name}
                to={item.path}
                onClick={() => setNavStatus(item.name)}
                className={`
                  relative flex items-center gap-2 px-3 py-2
                  text-[13px] font-semibold tracking-wide transition-colors duration-200
                  ${isActive
                    ? "text-bone"
                    : "text-bone/55 hover:text-bone"
                  }
                `}
              >
                <item.icon className={`text-base ${isActive ? "text-projector" : "text-bone/60"}`} />
                <span>{item.name}</span>
                {isActive && (
                  /* Active underline. Previously a framer `layoutId` pill that
                     slid between links; the sliding needed the library in the
                     eager bundle, so it is now a plain span that fades in under
                     the active item. */
                  <span
                    aria-hidden="true"
                    className="absolute left-2 right-2 -bottom-[7px] h-px bg-projector nav-active-pill"
                  />
                )}
              </Link>
            );
          })}
        </nav>

        {/* Right side */}
        <div className="flex items-center gap-2">
          {/* My List */}
          <Link
            to="/my-list"
            aria-label={watchlistCount > 0 ? `My List, ${watchlistCount} saved` : "My List"}
            title="My List"
            className="relative flex items-center justify-center w-10 h-10 rounded-full border border-bone/10 bg-bone/[0.06] backdrop-blur-xl shadow-[inset_0_1px_0_rgba(242,237,227,0.06)] transition-all duration-200 hover:border-projector/30 hover:bg-bone/10 active:scale-95"
          >
            <PiHeartStraight className={`text-[17px] ${watchlistCount > 0 ? "text-projector" : "text-bone/80"}`} />
            {watchlistCount > 0 && (
              <span className="absolute -top-1 -right-1 min-w-[16px] h-4 px-1 rounded-full bg-projector text-ink timecode text-[9px] font-bold leading-none flex items-center justify-center">
                {watchlistCount > 99 ? "99+" : watchlistCount}
              </span>
            )}
          </Link>

          {/* Mobile search icon */}
          <button
            onClick={() => {
              hapticSelection();
              setIsMobileSearchOpen(true);
            }}
            className="navlg:hidden flex items-center justify-center w-10 h-10 rounded-full border border-bone/10 bg-bone/[0.06] backdrop-blur-xl shadow-[inset_0_1px_0_rgba(242,237,227,0.06)] transition-all duration-200 hover:border-projector/30 hover:bg-bone/10 active:scale-95"
            aria-label="Open Search"
          >
            <FiSearch className="text-[17px] text-bone/80" />
          </button>

          {/* Desktop search */}
          <form
            onSubmit={(e) => { e.preventDefault(); if (debouncedVal) handleSeeAll(); }}
            className="hidden navlg:block relative"
            ref={searchRef}
          >
            <div className="relative group flex items-center">
              <FiSearch className="absolute left-3.5 text-bone/50 group-focus-within:text-projector transition-colors duration-200 z-10 text-sm" />
              <input
                type="text"
                name="search"
                value={query}
                onChange={(e) => { setQuery(e.target.value); setDropdownOpen(true); }}
                onFocus={() => setDropdownOpen(true)}
                placeholder="Search movies, series, anime…"
                className="
                  w-52 lg:w-72 xl:w-80
                  py-2.5 pl-10 pr-10
                  outline-none text-sm
                  border border-bone/12
                  rounded-[3px]
                  placeholder-bone/40
                  focus:border-projector/60
                  focus:w-64 lg:focus:w-80 xl:focus:w-96
                  transition-all duration-300 font-medium
                "
                autoComplete="off"
              />
              {query && (
                <button
                  type="button"
                  onClick={clearSearch}
                  className="absolute right-3.5 top-1/2 -translate-y-1/2 text-bone/60 hover:text-bone transition-colors z-10"
                >
                  <FiX className="text-sm" />
                </button>
              )}
            </div>

            {/* Desktop dropdown.
                The framer enter/exit tween (opacity 0→1, y -6→0, scale .98→1)
                is now a CSS entrance animation, `nav-dropdown-in`. Exit is not
                animated: the node unmounts immediately, which is imperceptible
                at this 150ms scale and avoids keeping a stale dropdown mounted
                over the page. */}
            {dropdownOpen && (query || recentSearches.length > 0) && (
              <div className="absolute top-[calc(100%+10px)] right-0 z-50 w-[400px] nav-dropdown-in">
                <div className="bg-carbon/95 backdrop-blur-2xl border border-bone/10 rounded-[4px] overflow-hidden shadow-[0_24px_60px_rgba(0,0,0,0.8)]">
                    {isLoading ? (
                      <div className="p-6 flex flex-col items-center gap-3">
                        <div className="w-8 h-8 border-2 border-projector border-t-transparent rounded-full animate-spin" />
                        <p className="text-bone/50 text-xs">Searching…</p>
                      </div>
                    ) : searchError ? (
                      <div className="p-8 text-center" role="alert">
                        <div className="w-12 h-12 rounded-full bg-signal/10 flex items-center justify-center mx-auto mb-3">
                          <FiSearch className="text-signal/70 text-xl" />
                        </div>
                        <p className="text-bone/70 text-sm font-medium">
                          Search is unavailable
                        </p>
                        <p className="text-bone/50 text-xs mt-1">
                          We couldn&apos;t reach the library. Try again in a moment.
                        </p>
                      </div>
                    ) : searchResult.length > 0 ? (
                      <>
                        <div className="px-4 pt-3 pb-1">
                          <p className="timecode text-[10px] uppercase tracking-[0.18em] text-bone/60">
                            Results for "{debouncedVal}"
                          </p>
                        </div>
                        <div className="max-h-[60dvh] overflow-y-auto">
                          {searchResult.slice(0, 8).map((result) => (
                            <DesktopResultItem
                              key={result.tmdb_id}
                              result={result}
                              onClickResult={handleDesktopResultClick}
                            />
                          ))}
                        </div>
                        {searchResult.length > 5 && (
                          <div className="p-3 border-t border-bone/8">
                            <button
                              type="button"
                              onMouseDown={(e) => e.preventDefault()}
                              onClick={handleSeeAll}
                              className="flex items-center justify-center gap-2 w-full py-2.5 bg-projector hover:bg-projector-bright text-ink font-bold rounded-[3px] transition-colors duration-200 text-sm"
                            >
                              <FiSearch className="text-sm" />
                              See all {searchResult.length}+ results
                            </button>
                          </div>
                        )}
                      </>
                    ) : debouncedVal ? (
                      <div className="p-8 text-center">
                        <div className="w-12 h-12 rounded-full bg-bone/5 flex items-center justify-center mx-auto mb-3">
                          <FiSearch className="text-bone/55 text-xl" />
                        </div>
                        <p className="text-bone/55 text-sm">
                          No results for{" "}
                          <span className="text-bone font-medium">"{debouncedVal}"</span>
                        </p>
                      </div>
                    ) : recentSearches.length > 0 ? (
                      <div className="py-2">
                        <div className="px-4 py-2">
                          <p className="timecode text-[10px] uppercase tracking-[0.18em] text-bone/55 flex items-center gap-1.5">
                            <FiClock className="text-xs" /> Recent
                          </p>
                        </div>
                        {recentSearches.slice(0, 5).map((s, i) => (
                          <button
                            key={i}
                            type="button"
                            onMouseDown={(e) => e.preventDefault()}
                            onClick={() => { setQuery(s); setDebouncedVal(s); setDropdownOpen(true); }}
                            className="flex items-center gap-3 w-full px-4 py-2.5 hover:bg-bone/5 transition-colors text-sm text-bone/70 hover:text-bone"
                          >
                            <FiClock className="text-bone/50 shrink-0 text-xs" />
                            {s}
                          </button>
                        ))}
                      </div>
                    ) : null}
                </div>
              </div>
            )}
          </form>
        </div>
      </div>

      {/* ── MOBILE FULL-SCREEN SEARCH ── */}
      {isMobileSearchOpen && (
        <div
          ref={mobileOverlayRef}
          role="dialog"
          aria-modal="true"
          aria-label="Search"
          className="fixed inset-0 z-[60] navlg:hidden flex flex-col nav-overlay-in"
          style={{ background: "#08090B" }}
        >
            {/* Header */}
            <div
              className="flex items-center gap-3 px-4 border-b border-bone/8"
              style={{
                paddingTop: "calc(env(safe-area-inset-top, 0px) + 14px)",
                paddingBottom: "14px",
              }}
            >
              <button
                onClick={() => { setIsMobileSearchOpen(false); clearSearch(); }}
                aria-label="Close search"
                className="flex items-center justify-center w-10 h-10 rounded-full bg-bone/[0.06] hover:bg-bone/10 border border-bone/10 backdrop-blur-xl transition-all active:scale-95 shrink-0 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-projector/70"
              >
                <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
                  <path
                    d="M11 4L6 9l5 5"
                    stroke="#F2EDE3"
                    strokeWidth="1.8"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </button>

              <div className="relative flex-1">
                <FiSearch className="absolute left-3.5 top-1/2 -translate-y-1/2 text-bone/60 text-base pointer-events-none" />
                <input
                  ref={mobileInputRef}
                  type="text"
                  name="mobile-search"
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  placeholder="Search movies, series, anime…"
                  className="w-full py-3 pl-10 pr-10 outline-none text-sm rounded-[3px] border border-bone/10 focus:border-projector/60 transition-all"
                  style={{
                    color: "#F2EDE3",
                    caretColor: "#E9B872",
                    WebkitTextFillColor: "#F2EDE3",
                    backgroundColor: "rgba(255,255,255,0.05)",
                  }}
                  autoComplete="off"
                />
                {query && (
                  <button
                    type="button"
                    onClick={() => setQuery("")}
                    className="absolute right-3 top-1/2 -translate-y-1/2 w-6 h-6 rounded-full bg-bone/12 flex items-center justify-center hover:bg-bone/20 transition-colors"
                  >
                    <FiX className="text-bone/70 text-xs" />
                  </button>
                )}
              </div>
            </div>

            {/* Results / Empty states */}
            <div className="flex-1 overflow-y-auto pb-32">
              {isLoading ? (
                <div className="flex flex-col items-center justify-center py-20 gap-4">
                  <div className="w-10 h-10 border-2 border-projector border-t-transparent rounded-full animate-spin" />
                  <p className="text-bone/50 text-sm">Searching…</p>
                </div>
              ) : searchError ? (
                <div
                  role="alert"
                  className="flex flex-col items-center justify-center py-20 gap-4 px-8 text-center"
                >
                  <div className="w-20 h-20 bg-signal/10 rounded-full flex items-center justify-center">
                    <FiSearch className="text-3xl text-signal/70" />
                  </div>
                  <div>
                    <p className="text-bone/75 text-base font-medium">
                      Search is unavailable
                    </p>
                    <p className="text-bone/50 text-sm mt-1">
                      We couldn&apos;t reach the library. Try again in a moment.
                    </p>
                  </div>
                </div>
              ) : searchResult.length > 0 ? (
                <div className="p-4 space-y-2">
                  <p className="timecode text-[10px] uppercase tracking-[0.18em] text-bone/60 px-1 mb-3">
                    Results for "{debouncedVal}"
                  </p>
                  {searchResult.slice(0, 12).map((result) => (
                    <MobileResultItem
                      key={result.tmdb_id}
                      result={result}
                      onClickResult={handleMobileResultClick}
                    />
                  ))}
                  {searchResult.length > 5 && (
                    <button
                      type="button"
                      onClick={handleMobileSeeAll}
                      className="flex items-center justify-center gap-2 w-full mt-3 py-3.5 bg-projector text-ink font-bold rounded-[3px] text-sm active:scale-[0.99] transition-all"
                    >
                      <FiSearch />
                      See all {searchResult.length}+ results
                    </button>
                  )}
                </div>
              ) : debouncedVal ? (
                <div className="flex flex-col items-center justify-center py-20 gap-4 px-8 text-center">
                  <div className="w-20 h-20 bg-bone/5 rounded-full flex items-center justify-center">
                    <FiSearch className="text-3xl text-bone/55" />
                  </div>
                  <div>
                    <p className="text-bone/70 text-base font-medium">No results found</p>
                    <p className="text-bone/50 text-sm mt-1">Try a different search term</p>
                  </div>
                </div>
              ) : (
                <div className="p-4 space-y-6">
                  {recentSearches.length > 0 && (
                    <div>
                      <div className="flex items-center justify-between mb-3 px-1">
                        <p className="timecode text-[10px] uppercase tracking-[0.18em] text-bone/55 flex items-center gap-1.5">
                          <FiClock className="text-xs" /> Recent
                        </p>
                        <button
                          onClick={() => {
                            setRecentSearches([]);
                            localStorage.removeItem("fc_recent_searches");
                          }}
                          className="timecode text-[10px] uppercase tracking-[0.14em] text-projector/70 hover:text-projector font-medium transition-colors"
                        >
                          Clear all
                        </button>
                      </div>
                      <div className="flex flex-wrap gap-2">
                        {recentSearches.map((s, i) => (
                          <button
                            key={i}
                            onClick={() => setQuery(s)}
                            className="flex items-center gap-2 px-3.5 py-2 bg-bone/5 border border-bone/10 rounded-[3px] text-sm text-bone/70 hover:bg-bone/10 hover:text-bone transition-all active:scale-95"
                          >
                            <FiClock className="text-[10px] text-bone/55" />
                            {s}
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                  <div>
                    <p className="timecode text-[10px] uppercase tracking-[0.18em] text-bone/55 px-1 mb-3 flex items-center gap-1.5">
                      <FiTrendingUp className="text-xs" /> Trending
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {TRENDING_SUGGESTIONS.map((s, i) => (
                        <button
                          key={i}
                          onClick={() => setQuery(s)}
                          className="px-4 py-2 bg-bone/5 border border-bone/10 rounded-[3px] text-sm text-bone/70 hover:text-bone hover:border-projector/40 transition-all active:scale-95 font-medium"
                        >
                          {s}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
      )}

      {/* ── MOBILE BOTTOM NAVIGATION — floating glass dock ──
          Extracted to MobileDock.jsx. It shares NAV_ITEMS, navStatus and the
          routes with the desktop header, so this is a presentation change only.
          Hidden at the same `navlg` breakpoint as the desktop header, so the
          two chrome modes swap at exactly one viewport width. */}
      <MobileDock
        items={NAV_ITEMS}
        activeName={navStatus}
        onNavigate={setNavStatus}
      />
    </>
  );
}

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { BiCheck, BiX, BiInfoCircle, BiError, BiErrorAlt } from 'react-icons/bi';
import { useHapticFeedback } from '../hooks/useHapticFeedback';

const NotificationSystem = () => {
  const [notifications, setNotifications] = useState([]);
  const { success, error, warning } = useHapticFeedback();

  const addNotification = (notification) => {
    const id = Date.now();
    const newNotification = {
      id,
      type: notification.type || 'info',
      title: notification.title || '',
      message: notification.message || '',
      duration: notification.duration || 5000,
      ...notification,
    };

    setNotifications(prev => [newNotification, ...prev]);

    // Trigger haptic feedback based on type
    switch (newNotification.type) {
      case 'success':
        success();
        break;
      case 'error':
        error();
        break;
      case 'warning':
        warning();
        break;
      default:
        break;
    }

    // Auto dismiss after duration
    if (newNotification.duration > 0) {
      setTimeout(() => {
        removeNotification(id);
      }, newNotification.duration);
    }

    return id;
  };

  const removeNotification = (id) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  // Expose addNotification to window for global access
  useEffect(() => {
    window.showNotification = addNotification;
    return () => {
      delete window.showNotification;
    };
  }, []);

  const getIcon = (type) => {
    switch (type) {
      case 'success':
        return <BiCheck className="text-xl" />;
      case 'error':
        return <BiError className="text-xl" />;
      case 'warning':
        return <BiErrorAlt className="text-xl" />;
      case 'info':
      default:
        return <BiInfoCircle className="text-xl" />;
    }
  };

  const getColors = (type) => {
    switch (type) {
      case 'success':
        return {
          bg: 'bg-green-500/10',
          border: 'border-green-500/30',
          icon: 'text-green-500',
          title: 'text-green-400',
        };
      case 'error':
        return {
          bg: 'bg-red-500/10',
          border: 'border-red-500/30',
          icon: 'text-red-500',
          title: 'text-red-400',
        };
      case 'warning':
        return {
          bg: 'bg-yellow-500/10',
          border: 'border-yellow-500/30',
          icon: 'text-yellow-500',
          title: 'text-yellow-400',
        };
      case 'info':
      default:
        return {
          bg: 'bg-projector/10',
          border: 'border-projector/30',
          icon: 'text-projector',
          title: 'text-projector',
        };
    }
  };

  return (
    <div className="fixed top-4 right-4 z-[100] flex flex-col gap-2 pointer-events-none">
      <AnimatePresence>
        {notifications.map((notification) => {
          const colors = getColors(notification.type);

          return (
            <motion.div
              key={notification.id}
              initial={{ opacity: 0, x: 100, scale: 0.9 }}
              animate={{ opacity: 1, x: 0, scale: 1 }}
              exit={{ opacity: 0, x: 100, scale: 0.9 }}
              transition={{ type: 'spring', stiffness: 300, damping: 30 }}
              className="pointer-events-auto"
            >
              <div
                className={`relative overflow-hidden rounded-[4px] border ${colors.border} ${colors.bg} backdrop-blur-md shadow-lg min-w-[300px] max-w-sm`}
              >
                <div className="flex items-start gap-3 p-4">
                  {/* Icon */}
                  <div className={`flex-shrink-0 w-8 h-8 rounded-[3px] ${colors.icon} bg-opacity-20 flex items-center justify-center ${colors.bg}`}>
                    {getIcon(notification.type)}
                  </div>

                  {/* Content */}
                  <div className="flex-1 min-w-0">
                    {notification.title && (
                      <h4 className={`text-sm font-semibold ${colors.title} mb-1`}>
                        {notification.title}
                      </h4>
                    )}
                    <p className="text-sm text-[var(--text-secondary)]">
                      {notification.message}
                    </p>
                  </div>

                  {/* Close button */}
                  <button
                    onClick={() => removeNotification(notification.id)}
                    className="flex-shrink-0 p-1 text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors"
                  >
                    <BiX className="text-lg" />
                  </button>
                </div>

                {/* Progress bar for auto-dismiss */}
                {notification.duration > 0 && (
                  <motion.div
                    initial={{ width: '100%' }}
                    animate={{ width: '0%' }}
                    transition={{ duration: notification.duration / 1000, ease: 'linear' }}
                    className={`absolute bottom-0 left-0 h-0.5 ${colors.icon} bg-opacity-50`}
                  />
                )}
              </div>
            </motion.div>
          );
        })}
      </AnimatePresence>
    </div>
  );
};

export default NotificationSystem;

import React, { useCallback, useEffect, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
  FiDownload,
  FiPlusSquare,
  FiRefreshCw,
  FiShare,
  FiSmartphone,
  FiWifiOff,
  FiX,
} from "react-icons/fi";
import { MdOutlineOfflineBolt } from "react-icons/md";
import { SITENAME } from "../config";
import { trackEvent } from "../utils/analytics";

const DISMISS_KEY = "pwa-install-dismissed-at";
const DISMISS_WINDOW_MS = 14 * 24 * 60 * 60 * 1000;

const isStandalone = () =>
  window.matchMedia?.("(display-mode: standalone)")?.matches ||
  window.navigator.standalone === true;

const isIos = () => {
  const ua = window.navigator.userAgent;
  return (
    /iphone|ipad|ipod/i.test(ua) ||
    (window.navigator.platform === "MacIntel" && window.navigator.maxTouchPoints > 1)
  );
};

const installDismissedRecently = () => {
  try {
    const at = Number(localStorage.getItem(DISMISS_KEY) || 0);
    return Date.now() - at < DISMISS_WINDOW_MS;
  } catch {
    return false;
  }
};

const notifyInstallable = (canInstall) => {
  window.__pwaInstallable = canInstall;
  window.dispatchEvent(
    new CustomEvent("pwa:installability", { detail: canInstall })
  );
};

export default function PWAInstallPrompt() {
  const [deferredPrompt, setDeferredPrompt] = useState(null);
  const [installOpen, setInstallOpen] = useState(false);
  const [iosOpen, setIosOpen] = useState(false);
  const [installing, setInstalling] = useState(false);
  const [updateReady, setUpdateReady] = useState(() => Boolean(window.__pwaUpdateReady));
  const [online, setOnline] = useState(() => window.navigator.onLine !== false);
  const deferredPromptRef = useRef(null);

  useEffect(() => {
    const goOnline = () => {
      setOnline(true);
      trackEvent("pwa_online");
    };
    const goOffline = () => {
      setOnline(false);
      trackEvent("pwa_offline");
    };
    window.addEventListener("online", goOnline);
    window.addEventListener("offline", goOffline);
    return () => {
      window.removeEventListener("online", goOnline);
      window.removeEventListener("offline", goOffline);
    };
  }, []);

  useEffect(() => {
    const onUpdate = () => setUpdateReady(true);
    window.addEventListener("pwa:update-available", onUpdate);
    return () => window.removeEventListener("pwa:update-available", onUpdate);
  }, []);

  useEffect(() => {
    if (isStandalone()) return undefined;
    let timer;
    const dismissed = installDismissedRecently();

    /*
     * The sheet is a floating card anchored above the dock, so on a phone it
     * lands in the middle of the first screen. Measured at 320x568 it covered
     * 43% of the viewport and overlapped the hero's primary "Watch now" CTA —
     * an install prompt nobody asked for, sitting on the one action the page
     * exists for. Auto-opening is therefore gated on the hero being out of the
     * way: the prompt appears only once the visitor has scrolled past the first
     * screen. The footer's "Install the app" button (pwa:install-request) still
     * opens it on demand at any time, so nothing is lost by waiting.
     */
    const HERO_CLEAR_FRACTION = 0.6;
    const FIRST_CHECK_MS = 4500;
    const POLL_MS = 2500;
    const MAX_POLLS = 12; // ~35s of grace, after which the footer owns it
    const heroIsClear = () =>
      (window.scrollY || 0) >= window.innerHeight * HERO_CLEAR_FRACTION;

    const scheduleAutoOpen = (open) => {
      let polls = 0;
      const attempt = () => {
        if (heroIsClear()) {
          open();
          return;
        }
        // Still on the hero: wait for the visitor to scroll past it, but stop
        // re-checking eventually rather than holding a timer open forever.
        if (polls >= MAX_POLLS) return;
        polls += 1;
        timer = window.setTimeout(attempt, POLL_MS);
      };
      timer = window.setTimeout(attempt, FIRST_CHECK_MS);
    };

    const onBeforeInstall = (event) => {
      event.preventDefault();
      setDeferredPrompt(event);
      deferredPromptRef.current = event;
      notifyInstallable(true);
      if (!dismissed) {
        scheduleAutoOpen(() => {
          setInstallOpen(true);
          trackEvent("pwa_install_prompt", { method: "browser" });
        });
      }
    };
    const onInstalled = () => {
      setInstallOpen(false);
      setIosOpen(false);
      setDeferredPrompt(null);
      deferredPromptRef.current = null;
      notifyInstallable(false);
      trackEvent("pwa_installed");
    };
    const onInstallRequest = () => {
      if (deferredPromptRef.current) {
        setIosOpen(false);
        setInstallOpen(true);
        trackEvent("pwa_install_prompt", { method: "footer" });
      } else if (isIos()) {
        setInstallOpen(false);
        setIosOpen(true);
        trackEvent("pwa_install_prompt", { method: "ios" });
      }
    };

    window.addEventListener("beforeinstallprompt", onBeforeInstall);
    window.addEventListener("appinstalled", onInstalled);
    window.addEventListener("pwa:install-request", onInstallRequest);

    if (isIos()) {
      notifyInstallable(true);
      if (!dismissed) {
        // Same scroll gate as the Chromium path above.
        scheduleAutoOpen(() => {
          setIosOpen(true);
          trackEvent("pwa_install_prompt", { method: "ios" });
        });
      }
    }

    return () => {
      window.clearTimeout(timer);
      window.removeEventListener("beforeinstallprompt", onBeforeInstall);
      window.removeEventListener("appinstalled", onInstalled);
      window.removeEventListener("pwa:install-request", onInstallRequest);
    };
  }, []);

  const dismissInstall = useCallback((reason = "manual") => {
    setInstallOpen(false);
    setIosOpen(false);
    try {
      localStorage.setItem(DISMISS_KEY, String(Date.now()));
    } catch {
      // Storage can be unavailable in private mode; dismissing still works.
    }
    trackEvent("pwa_install_dismissed", { reason });
  }, []);

  const handleInstall = useCallback(async () => {
    if (!deferredPrompt) {
      setIosOpen(true);
      return;
    }
    setInstalling(true);
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    setInstalling(false);
    setDeferredPrompt(null);
    deferredPromptRef.current = null;
    if (outcome === "accepted") {
      setInstallOpen(false);
      trackEvent("pwa_install_accepted", { method: "browser" });
    } else {
      dismissInstall("native_decline");
    }
  }, [deferredPrompt, dismissInstall]);

  const applyUpdate = useCallback(() => {
    window.__pwaUpdateReady = false;
    setUpdateReady(false);
    trackEvent("pwa_update_applied");
    window.dispatchEvent(new Event("pwa:apply-update"));
  }, []);

  const installSheetOpen = installOpen || iosOpen;

  return (
    <>
      {/* Update + offline status, pinned below the top bar */}
      <div className="pointer-events-none fixed inset-x-3 top-[calc(var(--safe-top)+4.25rem)] z-[55] mx-auto flex max-w-md flex-col items-center gap-2 md:top-24">
        <AnimatePresence>
          {!online && (
            <motion.div
              role="status"
              initial={{ opacity: 0, y: -8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -8 }}
              transition={{ duration: 0.2 }}
              className="pointer-events-auto flex items-center gap-2 rounded-full border border-projector/20 bg-carbon/90 px-3.5 py-2 shadow-[0_10px_30px_rgba(0,0,0,0.55)] backdrop-blur-xl"
            >
              <span className="relative flex h-1.5 w-1.5">
                <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-projector/60" />
                <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-projector" />
              </span>
              <FiWifiOff className="text-[11px] text-projector" />
              <span className="timecode text-[9px] font-medium uppercase tracking-[0.16em] text-bone/60">
                Offline · cached view
              </span>
            </motion.div>
          )}
        </AnimatePresence>

        <AnimatePresence>
          {updateReady && (
            <motion.div
              role="status"
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
              className="pointer-events-auto w-full overflow-hidden rounded-[8px] border border-projector/25 bg-carbon/95 shadow-[0_18px_44px_rgba(0,0,0,0.65)] backdrop-blur-2xl"
            >
              <div className="flex items-center gap-3 p-2.5 pl-3">
                <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-[5px] bg-projector/12 text-projector">
                  <FiRefreshCw className="text-[15px]" />
                </div>
                <div className="min-w-0 flex-1">
                  <p className="timecode text-[9px] uppercase tracking-[0.18em] text-projector/70">
                    New cut
                  </p>
                  <p className="mt-0.5 text-[13px] font-semibold leading-tight text-bone">
                    A fresh version is ready
                  </p>
                </div>
                <button
                  type="button"
                  onClick={applyUpdate}
                  className="shrink-0 rounded-[4px] bg-projector px-3 py-2 text-[11px] font-bold text-ink transition-all hover:bg-[#F0CA98] active:scale-95"
                >
                  Reload
                </button>
                <button
                  type="button"
                  onClick={() => setUpdateReady(false)}
                  aria-label="Dismiss update"
                  className="flex h-7 w-7 shrink-0 items-center justify-center rounded-[4px] text-bone/55 transition-colors hover:bg-bone/[0.06] hover:text-bone/70"
                >
                  <FiX className="text-sm" />
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Install sheet, floating above the mobile dock */}
      <AnimatePresence>
        {installSheetOpen && (
          <motion.div
            role="dialog"
            aria-label={`Install ${SITENAME}`}
            initial={{ y: 120, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: 120, opacity: 0 }}
            transition={{ type: "spring", stiffness: 300, damping: 30 }}
            className="fixed inset-x-3 bottom-[calc(var(--safe-bottom)+var(--mob-dock-footprint,73px)+4.5rem)] z-[55] md:inset-x-auto md:bottom-6 md:right-6 md:w-[360px]"          >
            <div className="relative overflow-hidden rounded-[8px] border border-bone/10 bg-carbon/95 shadow-[0_26px_64px_rgba(0,0,0,0.72)] backdrop-blur-2xl">
              <div
                aria-hidden
                className="absolute inset-x-0 top-0 h-px"
                style={{
                  background:
                    "linear-gradient(90deg, transparent, rgba(233,184,114,0.6), transparent)",
                }}
              />

              <button
                type="button"
                onClick={() => dismissInstall("close")}
                aria-label="Dismiss install prompt"
                className="absolute right-3 top-3 z-10 flex h-7 w-7 items-center justify-center rounded-[4px] text-bone/55 transition-colors hover:bg-bone/[0.06] hover:text-bone/70"
              >
                <FiX className="text-sm" />
              </button>

              <div className="p-4 pr-10">
                <div className="mb-3 flex items-center gap-3">
                  <img
                    src="/icons/icon-192x192.png"
                    alt=""
                    width="44"
                    height="44"
                    className="h-11 w-11 shrink-0 rounded-[10px] ring-1 ring-bone/10"
                  />
                  <div className="min-w-0 flex-1">
                    <h3 className="text-sm font-bold leading-tight text-bone">
                      {iosOpen ? "Add to Home Screen" : `Install ${SITENAME}`}
                    </h3>
                    <p className="mt-0.5 text-[11px] text-bone/60">
                      {iosOpen
                        ? "Two taps in Safari — no app store."
                        : "Full-screen playback, one tap away."}
                    </p>
                  </div>
                </div>

                {iosOpen ? (
                  <>
                    <ol className="mb-4 space-y-2.5 px-1">
                      {[
                        {
                          step: "01",
                          icon: FiShare,
                          copy: "Tap Share in Safari's toolbar.",
                        },
                        {
                          step: "02",
                          icon: FiPlusSquare,
                          copy: 'Choose "Add to Home Screen".',
                        },
                        {
                          step: "03",
                          icon: FiSmartphone,
                          copy: "Tap Add — the app lands on your home screen.",
                        },
                      ].map(({ step, icon: Icon, copy }) => (
                        <li key={step} className="flex items-center gap-3">
                          <span className="timecode text-[9px] font-medium tracking-[0.12em] text-projector/70">
                            {step}
                          </span>
                          <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-[4px] bg-bone/[0.05] text-bone/60">
                            <Icon className="text-[11px]" />
                          </span>
                          <span className="text-[11.5px] leading-snug text-bone/55">{copy}</span>
                        </li>
                      ))}
                    </ol>
                    <button
                      type="button"
                      onClick={() => dismissInstall("ios_guide_ack")}
                      className="w-full rounded-[4px] bg-projector py-2.5 text-xs font-bold text-ink shadow-[0_4px_14px_rgba(233,184,114,0.25)] transition-all hover:bg-[#F0CA98] active:scale-[0.98]"
                    >
                      Got it
                    </button>
                  </>
                ) : (
                  <>
                    <div className="mb-4 flex items-center gap-3 px-1">
                      <div className="flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-wider text-bone/60">
                        <MdOutlineOfflineBolt className="text-sm text-projector" />
                        Offline shell
                      </div>
                      <div className="h-3 w-px bg-bone/10" />
                      <div className="flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-wider text-bone/60">
                        <FiSmartphone className="text-xs text-projector" />
                        Full-screen
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button
                        type="button"
                        onClick={() => dismissInstall("not_now")}
                        className="flex-1 rounded-[4px] border border-bone/10 bg-bone/[0.03] py-2.5 text-xs font-semibold text-bone/50 transition-colors hover:border-bone/20 hover:bg-bone/[0.06] hover:text-bone/80"
                      >
                        Not now
                      </button>
                      <button
                        type="button"
                        onClick={handleInstall}
                        disabled={installing}
                        className="flex-1 rounded-[4px] bg-projector py-2.5 text-xs font-bold text-ink shadow-[0_4px_14px_rgba(233,184,114,0.25)] transition-all hover:bg-[#F0CA98] active:scale-[0.97] disabled:opacity-60"
                      >
                        {installing ? (
                          <div className="mx-auto h-3.5 w-3.5 animate-spin rounded-full border-2 border-ink/30 border-t-ink" />
                        ) : (
                          <span className="flex items-center justify-center gap-1.5">
                            <FiDownload className="text-sm" />
                            Install
                          </span>
                        )}
                      </button>
                    </div>
                  </>
                )}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

import React from "react";
import { motion } from "framer-motion";
import {
  HiChevronLeft,
  HiChevronRight,
  HiChevronDoubleLeft,
  HiChevronDoubleRight,
} from "react-icons/hi2";

const range = (start, end) =>
  [...Array(end - start).keys()].map((el) => el + start);

const getPagesCut = ({ pagesCount, pagesCutCount, currentPage }) => {
  const ceiling = Math.ceil(pagesCutCount / 2);
  const floor = Math.floor(pagesCutCount / 2);
  if (pagesCount <= pagesCutCount) return { start: 1, end: pagesCount + 1 };
  if (currentPage <= ceiling) return { start: 1, end: pagesCutCount + 1 };
  if (currentPage + floor >= pagesCount) return { start: pagesCount - pagesCutCount + 1, end: pagesCount + 1 };
  return { start: currentPage - ceiling + 1, end: currentPage + floor + 1 };
};

const NavBtn = ({ icon: Icon, onClick, disabled, label }) => (
  <button
    onClick={onClick}
    disabled={disabled}
    aria-label={label}
    className={`
      flex items-center justify-center w-9 h-9 rounded-[3px]
      transition-all duration-200
      ${disabled
        ? "text-bone/50 cursor-not-allowed bg-transparent"
        : "text-bone/60 hover:text-bone hover:bg-bone/10 active:scale-95 cursor-pointer"
      }
    `}
  >
    <Icon className="text-base" />
  </button>
);

const Pagination = ({ currentPage, total, limit, onPageChange }) => {
  const pagesCount = Math.ceil(total / limit);
  if (pagesCount <= 1) return null;

  const pagesCut = getPagesCut({ pagesCount, pagesCutCount: 5, currentPage });
  const pages = range(pagesCut.start, pagesCut.end);
  const isFirstPage = Number(currentPage) === 1;
  const isLastPage = Number(currentPage) === pagesCount;

  return (
    <div className="flex items-center justify-center gap-1 mt-8 mb-4 flex-wrap">
      <NavBtn
        icon={HiChevronDoubleLeft}
        onClick={() => onPageChange(1)}
        disabled={isFirstPage}
        label="First page"
      />
      <NavBtn
        icon={HiChevronLeft}
        onClick={() => onPageChange(Number(currentPage) - 1)}
        disabled={isFirstPage}
        label="Previous page"
      />

      {/* Show dots if not starting from 1 */}
      {pagesCut.start > 1 && (
        <span className="w-9 h-9 flex items-center justify-center text-bone/55 text-sm">…</span>
      )}

      {pages.map((page) => {
        const isActive = page === Number(currentPage);
        return (
          <button
            key={page}
            onClick={() => onPageChange(page)}
            className={`
              relative w-9 h-9 rounded-[3px] text-sm font-semibold
              transition-all duration-200 cursor-pointer active:scale-95
              ${isActive ? "text-ink" : "text-bone/50 hover:text-bone hover:bg-bone/10"}
            `}
          >
            {isActive && (
              <motion.div
                layoutId="activePage"
                className="absolute inset-0 bg-projector rounded-[3px]"
                style={{ zIndex: -1 }}
                transition={{ type: "spring", stiffness: 500, damping: 40 }}
              />
            )}
            {page}
          </button>
        );
      })}

      {/* Show dots if not ending at last */}
      {pagesCut.end <= pagesCount && (
        <span className="w-9 h-9 flex items-center justify-center text-bone/55 text-sm">…</span>
      )}

      <NavBtn
        icon={HiChevronRight}
        onClick={() => onPageChange(Number(currentPage) + 1)}
        disabled={isLastPage}
        label="Next page"
      />
      <NavBtn
        icon={HiChevronDoubleRight}
        onClick={() => onPageChange(pagesCount)}
        disabled={isLastPage}
        label="Last page"
      />

      {/* Page count info */}
      <div className="w-full text-center mt-2">
        <span className="timecode text-[11px] text-bone/55">
          Page {currentPage} of {pagesCount}
        </span>
      </div>
    </div>
  );
};

export default Pagination;

import React, { useState, useRef, useCallback } from 'react';
import { motion } from 'framer-motion';
import { BiRefresh } from 'react-icons/bi';
import { useHapticFeedback } from '../hooks/useHapticFeedback';

const PullToRefresh = ({ onRefresh, children, threshold = 80, resistance = 0.5 }) => {
  const [isPulling, setIsPulling] = useState(false);
  const [pullDistance, setPullDistance] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [canRefresh, setCanRefresh] = useState(false);

  const startYRef = useRef(0);
  const containerRef = useRef(null);
  const { medium, success } = useHapticFeedback();

  const handleTouchStart = useCallback((e) => {
    if (isRefreshing) return;

    const touch = e.touches[0];
    const scrollTop = containerRef.current?.scrollTop || 0;

    // Only trigger pull-to-refresh at the top
    if (scrollTop === 0) {
      startYRef.current = touch.clientY;
      setIsPulling(true);
    }
  }, [isRefreshing]);

  const handleTouchMove = useCallback((e) => {
    if (!isPulling || isRefreshing) return;

    const touch = e.touches[0];
    const currentY = touch.clientY;
    const deltaY = (currentY - startYRef.current) * resistance;

    // Only allow pulling down
    if (deltaY > 0) {
      setPullDistance(Math.min(deltaY, threshold * 2));
      setCanRefresh(deltaY >= threshold);

      // Haptic feedback when reaching threshold
      if (deltaY >= threshold && !canRefresh) {
        medium();
      }
    }
  }, [isPulling, isRefreshing, threshold, resistance, canRefresh, medium]);

  const handleTouchEnd = useCallback(async () => {
    if (!isPulling) return;

    setIsPulling(false);

    if (canRefresh && onRefresh) {
      setIsRefreshing(true);
      setPullDistance(threshold);
      success();

      try {
        await onRefresh();
      } catch (error) {
        console.error('Refresh failed:', error);
      } finally {
        setIsRefreshing(false);
        setPullDistance(0);
        setCanRefresh(false);
      }
    } else {
      setPullDistance(0);
      setCanRefresh(false);
    }
  }, [isPulling, canRefresh, onRefresh, threshold, success]);

  const progress = Math.min(pullDistance / threshold, 1);

  return (
    <div
      ref={containerRef}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
      className="relative overflow-hidden"
      style={{ touchAction: 'pan-y' }}
    >
      {/* Pull indicator */}
      <motion.div
        className="absolute top-0 left-0 right-0 flex items-center justify-center pointer-events-none z-50"
        initial={{ opacity: 0 }}
        animate={{ 
          opacity: isPulling || isRefreshing ? 1 : 0,
          y: isPulling ? pullDistance : isRefreshing ? threshold : -threshold,
        }}
        transition={{ type: 'spring', stiffness: 300, damping: 30 }}
      >
        <div className="flex flex-col items-center gap-2">
          <motion.div
            animate={{ rotate: isRefreshing ? 360 : progress * 180 }}
            transition={{ 
              rotate: isRefreshing ? { duration: 1, repeat: Infinity, ease: 'linear' } : { type: 'spring', stiffness: 300, damping: 30 }
            }}
            className={`w-10 h-10 rounded-full flex items-center justify-center ${
              canRefresh || isRefreshing 
                ? 'bg-[var(--accent-primary)] text-white' 
                : 'bg-[var(--bg-surface)] text-[var(--text-muted)]'
            }`}
          >
            <BiRefresh className="text-xl" />
          </motion.div>
          <span className="text-xs text-[var(--text-muted)]">
            {isRefreshing ? 'Refreshing...' : canRefresh ? 'Release to refresh' : 'Pull to refresh'}
          </span>
        </div>
      </motion.div>

      {/* Content with offset during pull */}
      <motion.div
        animate={{ y: isPulling ? pullDistance : 0 }}
        transition={{ type: 'spring', stiffness: 300, damping: 30 }}
        className="relative"
      >
        {children}
      </motion.div>
    </div>
  );
};

export default PullToRefresh;

