import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";
import { useParams } from "react-router-dom";
import { motion } from "framer-motion";
import { UserRound } from "lucide-react";
import MovieCard from "../components/MovieCard";
import MovieCardSkeleton from "../components/MovieCardSkeleton";
import Pagination from "../components/Pagination";
import SEO from "../components/SEO";
import { BASE_URL as BASE, SITENAME } from "../config";

export default function CastMedia() {
  const { castId, castName } = useParams();

  const displayName = useMemo(() => {
    try { return decodeURIComponent(castName || "Cast"); }
    catch { return castName || "Cast"; }
  }, [castName]);

  const [media, setMedia] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);

  useEffect(() => {
    let isMounted = true;
    setIsLoading(true);
    window.scrollTo(0, 0);

    axios.get(`${BASE}/api/cast/${castId}`, {
      params: { name: displayName, page: currentPage, page_size: 24 },
    })
      .then(({ data }) => {
        if (!isMounted) return;
        setMedia(Array.isArray(data.results) ? data.results : []);
        setTotalCount(Number(data.total_count || 0));
        setIsLoading(false);
      })
      .catch(() => {
        if (isMounted) { setMedia([]); setTotalCount(0); setIsLoading(false); }
      });

    return () => { isMounted = false; };
  }, [BASE, castId, displayName, currentPage]);

  return (
    <>
      <SEO
        title={`${displayName} - ${SITENAME} Cast`}
        description={`Browse all movies and series featuring ${displayName} on ${SITENAME}.`}
        name={SITENAME}
        /* Paginated person filmography with no unique editorial content —
           indexable would just compete with the title pages it links to. */
        noIndex
      />

      <div>
        {/* Cast Header */}
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4 }}
          className="flex items-center gap-4 mb-8 mt-4"
        >
          {/* Avatar */}
          <div className="flex-shrink-0 w-16 h-16 rounded-[4px] bg-gradient-to-br from-projector/20 to-projector-deep/10 border border-projector/25 flex items-center justify-center">
            <UserRound className="text-projector w-8 h-8" />
          </div>
          <div className="min-w-0">
            <span className="eyebrow mb-1.5">Call sheet</span>
            <h1 className="section-title text-2xl sm:text-3xl tracking-tight truncate">
              {displayName}
            </h1>
            {!isLoading && totalCount > 0 && (
              <p className="timecode text-[11px] text-bone/60 mt-1">
                {totalCount} title{totalCount === 1 ? "" : "s"} on file
              </p>
            )}
          </div>
        </motion.div>

        {/* Divider */}
        <div className="h-px bg-gradient-to-r from-projector/20 via-bone/5 to-transparent mb-8" />

        {/* Section header */}
        <div className="flex items-center gap-3 mb-5">
          <div className="w-px h-5 bg-projector shrink-0" />
          <h2 className="section-title text-base sm:text-lg tracking-tight">Filmography</h2>
        </div>

        {/* Grid */}
        {!isLoading ? (
          media.length > 0 ? (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="grid gap-x-2 sm:gap-x-3 gap-y-6 grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-7"
            >
              {media.map((movie, index) => (
                <motion.div
                  key={index}
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: Math.min(index * 0.03, 0.5) }}
                >
                  <MovieCard movie={movie} />
                </motion.div>
              ))}
            </motion.div>
          ) : (
            /* Empty state */
            <div className="flex flex-col items-center justify-center py-20 text-center">
              <UserRound className="w-16 h-16 text-bone/10 mb-4" />
              <span className="eyebrow mb-3">No screenings</span>
              <p className="font-display text-xl sm:text-2xl text-bone/90">No titles on file yet</p>
              <p className="mt-2 max-w-sm text-[13px] text-bone/50">
                We don&rsquo;t have any media for {displayName} in the archive. Check back after the next programme update.
              </p>
            </div>
          )
        ) : (
          <MovieCardSkeleton count={24} />
        )}

        {/* Pagination */}
        {totalCount > 24 && (
          <Pagination
            currentPage={currentPage}
            total={totalCount}
            limit={24}
            onPageChange={(p) => { setCurrentPage(p); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
          />
        )}
      </div>
    </>
  );
}

// src/pages/GenrePage.jsx
// Unified genre browsing page — handles both movies and TV shows
// Route: /genre/:mediaType/:genreName  (mediaType = "movie" | "tv")
import React, { useState, useEffect, useCallback } from "react";
import axios from "axios";
import { useParams, useNavigate } from "react-router-dom";
import { BASE_URL as BASE, SITENAME } from "../config";
import MovieCard from "../components/MovieCard";
import MovieCardSkeleton from "../components/MovieCardSkeleton";
import Pagination from "../components/Pagination";
import SEO from "../components/SEO";

const SORT_OPTIONS = [
  { value: "rating", label: "Top Rated" },
  { value: "updated_on", label: "Latest Added" },
  { value: "release_year", label: "Release Year" },
];

export default function GenrePage() {
  const { mediaType = "movie", genreName } = useParams();
  const navigate = useNavigate();
  const decodedGenre = decodeURIComponent(genreName || "");

  // Active media type tab — "movie" or "tv"
  const [activeType, setActiveType] = useState(mediaType === "tv" ? "tv" : "movie");

  const [items, setItems] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [sortBy, setSortBy] = useState("rating");

  const PAGE_SIZE = 24;

  // Sync URL when tab changes
  const switchType = (type) => {
    setActiveType(type);
    setCurrentPage(1);
    navigate(`/genre/${type}/${encodeURIComponent(decodedGenre)}`, { replace: true });
  };

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    setItems([]);
    window.scrollTo({ top: 0, behavior: "smooth" });

    try {
      const endpoint = activeType === "movie" ? "/api/movies" : "/api/tvshows";
      const params = {
        genre: decodedGenre,
        sort_by: `${sortBy}:desc`,
        page: currentPage,
        page_size: PAGE_SIZE,
      };

      const { data } = await axios.get(`${BASE}${endpoint}`, { params });
      let results = activeType === "movie" ? data.movies || [] : data.tv_shows || [];

      // Client-side genre filter as safety net (backend may return broader matches)
      const target = decodedGenre.toLowerCase();
      results = results.filter((item) => {
        if (!item.genres?.length) return false;
        const genresArr = Array.isArray(item.genres) ? item.genres : [item.genres];
        return genresArr.some(
          (g) => typeof g === "string" && g.toLowerCase().includes(target)
        );
      });

      setItems(results);
      setTotalCount(data.total_count || results.length);
    } catch (err) {
      console.error("Genre fetch error:", err);
      setItems([]);
    } finally {
      setIsLoading(false);
    }
  }, [activeType, decodedGenre, sortBy, currentPage, BASE]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Reset page when sort or type changes
  useEffect(() => {
    setCurrentPage(1);
  }, [sortBy, activeType]);

  const pageTitle = `${decodedGenre} ${activeType === "movie" ? "Movies" : "TV Shows"}`;

  return (
    <div className="min-h-screen">
      <SEO
        title={`${pageTitle} - ${SITENAME}`}
        description={`Browse ${pageTitle} on ${SITENAME}. Discover the best ${decodedGenre.toLowerCase()} content sorted by rating, release year, and more.`}
        name={SITENAME}
        type="website"
        keywords={`${decodedGenre} movies, ${decodedGenre} TV shows, stream ${decodedGenre} online`}
      />

      {/* Genre Header */}
      <div className="mb-6">
        <span className="eyebrow mb-3">Genre index</span>
        <h1 className="section-title text-2xl sm:text-3xl">{decodedGenre}</h1>
        <p className="timecode text-[11px] text-bone/60 mt-1.5">
          {isLoading ? "Loading…" : `${totalCount.toLocaleString()} titles`}
        </p>

        {/* Tabs + Sort Row */}
        <div className="flex flex-wrap items-center justify-between gap-3 mt-5">
          {/* Media type tabs */}
          <div className="flex bg-bone/[0.04] border border-bone/10 rounded-[3px] p-1 gap-1">
            <button
              onClick={() => switchType("movie")}
              className={`px-4 py-1.5 rounded-[3px] text-sm font-medium transition-all duration-200 ${
                activeType === "movie"
                  ? "bg-projector text-ink"
                  : "text-bone/60 hover:text-bone"
              }`}
            >
              Movies
            </button>
            <button
              onClick={() => switchType("tv")}
              className={`px-4 py-1.5 rounded-[3px] text-sm font-medium transition-all duration-200 ${
                activeType === "tv"
                  ? "bg-projector text-ink"
                  : "text-bone/60 hover:text-bone"
              }`}
            >
              TV Shows
            </button>
          </div>

          {/* Sort selector */}
          <div className="flex items-center gap-2">
            <span className="font-mono text-[10px] uppercase tracking-wider text-bone/55 hidden sm:inline">
              Sort by
            </span>
            <div className="flex bg-bone/[0.04] border border-bone/10 rounded-[3px] p-1 gap-1">
              {SORT_OPTIONS.map((opt) => (
                <button
                  key={opt.value}
                  onClick={() => setSortBy(opt.value)}
                  className={`px-3 py-1 rounded-[3px] text-xs font-medium transition-all duration-200 ${
                    sortBy === opt.value
                      ? "bg-projector text-ink"
                      : "text-bone/60 hover:text-bone"
                  }`}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="mt-4 h-px bg-gradient-to-r from-projector/20 via-bone/5 to-transparent" />
      </div>

      {/* Content Grid */}
      {isLoading ? (
        <MovieCardSkeleton count={PAGE_SIZE} />
      ) : items.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-24 text-center">
          <span className="eyebrow mb-3">No screenings</span>
          <h2 className="font-display text-xl text-bone/90 mb-2">
            No {decodedGenre} {activeType === "movie" ? "movies" : "TV shows"} yet
          </h2>
          <p className="text-bone/50 text-sm max-w-md leading-relaxed">
            This shelf is still being programmed. Check the other format, or come back after the next update.
          </p>
          <button
            onClick={() => switchType(activeType === "movie" ? "tv" : "movie")}
            className="mt-5 px-5 py-2.5 min-h-[44px] rounded-[3px] bg-projector hover:bg-[#F0CA98] text-ink text-sm font-bold transition-colors"
          >
            Try {activeType === "movie" ? "TV Shows" : "Movies"} instead
          </button>
        </div>
      ) : (
        <div className="grid gap-x-2 sm:gap-x-3 gap-y-6 grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-7">
          {items.map((item) => (
            <MovieCard key={item.tmdb_id || item._id} movie={item} />
          ))}
        </div>
      )}

      {/* Pagination */}
      {!isLoading && items.length > 0 && (
        <Pagination
          currentPage={currentPage}
          total={totalCount}
          onPageChange={(p) => {
            setCurrentPage(p);
            window.scrollTo({ top: 0, behavior: "smooth" });
          }}
          limit={PAGE_SIZE}
        />
      )}
    </div>
  );
}

/**
 * Home.jsx
 * Drives all homepage content sections through the SmartSection engine.
 *
 * Architecture:
 *  • HeroSlider      — immediate, uses its own data fetch
 *  • TopTenToday     — immediate, uses its own data fetch
 *  • SmartSection[]  — driven by SECTIONS config array
 *      priority:"high" → fetch on mount (first ~5 sections)
 *      priority:"lazy" → IntersectionObserver (everything below the fold)
 *
 * To add / remove / reorder sections:
 *  → Edit src/config/sectionsConfig.js — do NOT touch this file.
 */

import React, { useState, useEffect } from "react";
import { getJSON } from "../utils/apiCache";
import { BASE_URL as BASE, SITENAME } from "../config";
import { toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

import HeroSlider   from "../components/HomeHero";
import TopTenToday  from "../components/TopTenToday";
import SmartSection from "../components/SmartSection";
import SEO          from "../components/SEO";
import SplashScreen from "../components/SplashScreen";

import { SECTIONS } from "../config/sectionsConfig";

export default function Home() {
  /* ── Hero data (immediate, separate from section engine) ─────── */
  const [heroMovies,   setHeroMovies]   = useState([]);
  const [heroLoading,  setHeroLoading]  = useState(true);
  const [heroError,    setHeroError]    = useState(false);

  /* ── Top 10 Today (immediate, uses its own shape) ─────────────── */
  const [topTenData,    setTopTenData]    = useState([]);
  const [topTenLoading, setTopTenLoading] = useState(true);

  /* ── Fresh-content refresh triggered by app launch/resume ─────── */
  const [contentRefresh, setContentRefresh] = useState(0);

  useEffect(() => {
    const refreshContent = () => setContentRefresh((version) => version + 1);
    window.addEventListener("cloudx:content-refresh", refreshContent);
    return () => window.removeEventListener("cloudx:content-refresh", refreshContent);
  }, []);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  /* ── Hero fetch: curated picks, latest releases when none are pinned ── */
  useEffect(() => {
    let cancelled = false;
    setHeroLoading(true);
    setHeroError(false);
    const latestReleases = () =>
      getJSON(BASE, "/api/movies", { sort_by: "release_year:desc", page: 1, page_size: 12 });

    /*
     * Fall back to latest releases for ANY hero failure. This previously only
     * handled a 404 while the backend raises 400 on a hero error, so a failed
     * hero request left `heroMovies` empty, HeroSlider returned null and the
     * page opened with no hero at all and no explanation.
     */
    getJSON(BASE, "/api/hero")
      .catch(() => latestReleases())
      .then(({ data }) => {
        if (cancelled) return;
        const picks = data.movies || data.tv_shows || [];
        setHeroMovies(picks);
        if (picks.length === 0) setHeroError(true);
        setHeroLoading(false);
      })
      .catch(() => {
        if (cancelled) return;
        setHeroError(true);
        setHeroLoading(false);
      });

    return () => { cancelled = true; };
  }, [BASE, contentRefresh]);

  /* ── Top 10 fetch ────────────────────────────────────────────── */
  useEffect(() => {
    let cancelled = false;
    setTopTenLoading(true);
    getJSON(BASE, "/api/trending/today", { limit: 20 })
      .then(({ data }) => {
        if (cancelled) return;
        const all = [
          ...(data.movies   || []),
          ...(data.tv_shows || []),
        ].sort((a, b) => (b.view_count || 0) - (a.view_count || 0));
        setTopTenData(all.slice(0, 10));
        setTopTenLoading(false);
      })
      .catch(() => {
        if (!cancelled) setTopTenLoading(false);
      });

    return () => { cancelled = true; };
  }, [BASE, contentRefresh]);

  return (
    <div>
      {/* Keep the launch surface up until the above-the-fold content is usable.
          Below-fold shelves remain lazy and continue loading after the first view. */}
      <SplashScreen ready={!heroLoading && !topTenLoading} />

      <SEO
        title={`${SITENAME} – Stream Movies, Series & Anime`}
        description={`Watch HD movies, TV series, anime, and K-Dramas on ${SITENAME}. Trending content, top-rated picks, and personalized recommendations.`}
        name={SITENAME}
        type="website"
        keywords="watch movies online, HD streaming, TV series, anime, k-drama, trending movies, top rated"
      />

      {/* ── HERO CAROUSEL ─────────────────────────────────────────── */}
      <HeroSlider
        movieData={heroMovies}
        isMovieDataLoading={heroLoading}
        hasError={heroError}
      />

      {/* ── TOP 10 TODAY ──────────────────────────────────────────── */}
      <TopTenToday
        data={topTenData}
        isLoading={topTenLoading}
        sectionTitle="Top 10 Today"
      />

      {/* ── ALL CONTENT SECTIONS (config-driven) ──────────────────── */}
      {SECTIONS.map((section) => (
        <SmartSection
          key={section.id}
          config={section}
          BASE={BASE}
          refreshVersion={contentRefresh}
        />
      ))}
    </div>
  );
}

